// ============================================
// Internationalization (i18n)
// ============================================
let currentLanguage = 'en';

const translations =
    typeof CCPCalendarI18n !== 'undefined' && CCPCalendarI18n.translations
        ? CCPCalendarI18n.translations
        : { en: {}, ko: {} };

const SYNC_ERROR_KEYS = {
    'Not signed in': 'syncErrNotSignedIn',
    'Request timed out': 'syncErrTimeout',
    'Request failed': 'syncErrFailed',
    'No active team calendar': 'syncErrNoCalendar',
    'You do not have edit access to this calendar': 'syncErrNoEditAccess',
    'Calendar is locked by another teacher': 'syncErrLocked',
    'View As: change not saved': 'viewAsChangeNotSaved'
};

function translateSyncError(message) {
    if (!message) {
        return message;
    }
    const key = SYNC_ERROR_KEYS[message];
    return key ? t(key) : message;
}

function showSyncErrorToast(err) {
    const raw = err && err.message ? err.message : String(err || '');
    showSyncToast(t('syncError') + ': ' + translateSyncError(raw), true);
}

function t(key) {
    return translations[currentLanguage][key] || translations['en'][key] || key;
}

/**
 * Interpolate `{name}` placeholders from translation strings.
 * Return value must only be assigned to `.textContent` or passed through `escapeHtml()` before HTML.
 * @param {string} key
 * @param {Record<string, unknown>} [vars]
 * @returns {string}
 */
function formatI18n(key, vars) {
    let s = t(key);
    if (vars && typeof vars === 'object') {
        Object.entries(vars).forEach(([name, value]) => {
            s = s.replace(new RegExp(`\\{${name}\\}`, 'g'), String(value ?? ''));
        });
    }
    return s;
}

/** i18n for notes.html only — avoids calendar-only DOM updates that crash without index.html chrome. */
function applyNotesPageLanguage() {
    document.querySelectorAll('[data-i18n]').forEach((el) => {
        const key = el.getAttribute('data-i18n');
        if (translations[currentLanguage][key]) {
            el.textContent = translations[currentLanguage][key];
        }
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (translations[currentLanguage][key]) {
            el.placeholder = translations[currentLanguage][key];
        }
    });
    document.querySelectorAll('[data-i18n-aria-label]').forEach((el) => {
        const key = el.getAttribute('data-i18n-aria-label');
        if (translations[currentLanguage][key]) {
            el.setAttribute('aria-label', translations[currentLanguage][key]);
        }
    });
    document.querySelectorAll('[data-i18n-title]').forEach((el) => {
        const key = el.getAttribute('data-i18n-title');
        if (translations[currentLanguage][key]) {
            el.setAttribute('title', translations[currentLanguage][key]);
        }
    });
    const langBtn = document.getElementById('notesLangToggle');
    if (langBtn) {
        langBtn.textContent = t('langToggle');
    }
    updateThemeToggleButtons();
    document.documentElement.lang = currentLanguage === 'ko' ? 'ko' : 'en';
    const titleBase =
        appData && appData.calendarName && appData.calendarName.trim()
            ? appData.calendarName.trim()
            : t('notesPageTitle');
    document.title = titleBase;
}

function applyLanguage() {
    if (isNotesPage()) {
        applyNotesPageLanguage();
        return;
    }
    // Update all elements with data-i18n attribute
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[currentLanguage][key]) {
            el.textContent = translations[currentLanguage][key];
        }
    });
    
    // Update placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (translations[currentLanguage][key]) {
            el.placeholder = translations[currentLanguage][key];
        }
    });

    document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
        const key = el.getAttribute('data-i18n-aria-label');
        if (translations[currentLanguage][key]) {
            el.setAttribute('aria-label', translations[currentLanguage][key]);
        }
    });

    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        if (translations[currentLanguage][key]) {
            el.setAttribute('title', translations[currentLanguage][key]);
        }
    });
    
    // Update language toggle button text
    const langBtn = document.getElementById('langToggleBtn');
    if (langBtn) {
        langBtn.textContent = t('langToggle');
    }
    const workspaceLangBtn = document.getElementById('workspaceLangToggle');
    if (workspaceLangBtn) {
        workspaceLangBtn.textContent = t('langToggle');
    }

    updateThemeToggleButtons();
    updateContentExpandChrome();
    updateTermSettingsToggleSummary();
    updateSetupChecklistBanner();
    refreshCurriculumUpdatedBanner();

    document.documentElement.lang = currentLanguage === 'ko' ? 'ko' : 'en';
    const titleBase = (appData.calendarName && appData.calendarName.trim())
        ? appData.calendarName.trim()
        : t('appTitle');
    document.title = titleBase;

    // Update calendar title with name
    updateCalendarTitle();
    
    // Refresh dynamic lesson labels
    const totalLessons = getTotalLessonsValue();
    const currentDates = getCustomLessonDatesFromInputs();
    const currentMerges = getSelectedCompressionMerges();
    renderCustomLessonDates(totalLessons, currentDates);
    renderCompressionOptions(totalLessons, currentMerges);
    updateMeetingDayChipLabels();
    refreshMeetingDayPresetLabels();
    updateLessonFilterButtonLabel();
    updatePrintLessonFilterHint();
    if (isLessonFilterPopoverOpen()) {
        renderLessonFilterPopoverBody();
        updateLessonFilterStatusText();
    }
    const searchEl = document.getElementById('lessonFilterSearch');
    if (searchEl && translations[currentLanguage].lessonFilterSearchPlaceholder) {
        searchEl.placeholder = translations[currentLanguage].lessonFilterSearchPlaceholder;
    }
    setupSimsonLevelPresetSelect();
    if (isEventApplicabilityPopoverOpen()) {
        renderEventApplicabilityPopoverBody();
        updateEventApplicabilityStatusText();
    }
    updateEventApplicabilityButtonLabel();
    updateEventApplicabilitySummaryText();
    syncClassOpenEditorButton();
    syncEventOpenEditorButton();
    syncEventTypeHint();
    if (getActiveTab() === 'homework') {
        renderHomeworkReferenceMiniCalendar();
    }
    if (getActiveTab() === 'timetable') {
        refreshTimetablePanels();
    }
    populateTeachersTabDefaultCategorySelect();
    populateTeachersTabCatalogToolbar();
    const eventAppSearchEl = document.getElementById('eventApplicabilitySearch');
    if (eventAppSearchEl && translations[currentLanguage].lessonFilterSearchPlaceholder) {
        eventAppSearchEl.placeholder = translations[currentLanguage].lessonFilterSearchPlaceholder;
    }
    const classNotesTextSearchEl = document.getElementById('classNotesTextSearch');
    if (classNotesTextSearchEl && translations[currentLanguage].classNotesTextSearchPlaceholder) {
        classNotesTextSearchEl.placeholder = translations[currentLanguage].classNotesTextSearchPlaceholder;
    }
    if (elements.classTypeSelect && (isClassPopoutOpen() || (getActiveTab() === 'classes' && classEditorMount === 'tab'))) {
        const v = elements.classTypeSelect.value;
        populateClassTypeSelect();
        if (v && [...elements.classTypeSelect.options].some(o => o.value === v)) {
            elements.classTypeSelect.value = v;
        }
    }

    refreshLocalizedEventDisplayNames();

    // Re-render calendar to update month/day names and localized event labels
    if (appData.termStart) {
        renderCalendar();
    } else {
        updatePrintSummary();
    }
    applyTopBarCollapsedState();
    refreshCalendarNameLabel();
    if (typeof TeamAuth !== 'undefined' && TeamAuth.getUser) {
        updateTeamAccountMenuTrigger(TeamAuth.getUser());
    }
    scheduleAppTabNavShellWidthSync();
    nowClassPopupLastSig = '';
    syncNowClassPopupToggleUi();
    renderNowClassPopup();
    document.dispatchEvent(new CustomEvent('calendarLanguageChanged', { detail: { lang: currentLanguage } }));
}

function refreshCalendarNameLabel() {
    const nameLabel = document.getElementById('calendarNameLabel');
    if (!nameLabel) {
        return;
    }
    nameLabel.textContent = teamSyncEnabled ? t('teamCalendarNameLabel') : t('calendarName');
}

function updateCalendarTitle() {
    const titleBlock = document.querySelector('.app-top-bar-title-block');
    const titleEl = titleBlock?.querySelector('h1');
    const name = (appData.calendarName || '').trim();
    if (titleEl) {
        titleEl.textContent = t('appTitle');
    }
    if (titleBlock) {
        titleBlock.hidden = Boolean(name);
    }
    updateTopBarCalendarLabel();
    requestAnimationFrame(syncAppChromeStickyTop);
}

function toggleLanguage() {
    currentLanguage = currentLanguage === 'en' ? 'ko' : 'en';
    localStorage.setItem('calendarLanguage', currentLanguage);
    applyLanguage();
}

function loadLanguage() {
    if (typeof CCPLanguage !== 'undefined' && CCPLanguage.resolveCalendarLanguage) {
        currentLanguage = CCPLanguage.resolveCalendarLanguage();
        return;
    }
    const saved = localStorage.getItem('calendarLanguage');
    if (saved === 'en' || saved === 'ko') {
        currentLanguage = saved;
        return;
    }
    currentLanguage =
        typeof CCPLanguage !== 'undefined' && CCPLanguage.detectBrowserLanguage
            ? CCPLanguage.detectBrowserLanguage()
            : 'en';
    try {
        localStorage.setItem('calendarLanguage', currentLanguage);
    } catch (_) {
        /* ignore */
    }
}

function getStoredTheme() {
    const saved = localStorage.getItem('calendarTheme');
    if (saved === 'light' || saved === 'dark') {
        return saved;
    }
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        return 'dark';
    }
    return 'light';
}

function updateThemeToggleButtons() {
    const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    const labelKey = isDark ? 'themeLight' : 'themeDark';
    const labelText =
        typeof t === 'function' && translations && translations[currentLanguage] && translations[currentLanguage][labelKey]
            ? t(labelKey)
            : isDark
              ? '☀️ Light'
              : '🌙 Dark';
    const titleText =
        typeof t === 'function' && translations && translations[currentLanguage] && translations[currentLanguage].themeToggleTitle
            ? t('themeToggleTitle')
            : 'Switch light/dark theme';

    ['themeToggleBtn', 'workspaceThemeToggle', 'notesThemeToggle'].forEach((id) => {
        const btn = document.getElementById(id);
        if (!btn) {
            return;
        }
        btn.textContent = labelText;
        btn.setAttribute('aria-pressed', isDark ? 'true' : 'false');
        btn.setAttribute('title', titleText);
    });
}

function applyTheme(theme) {
    if (window.CCPTheme && window.CCPTheme.applyTheme) {
        window.CCPTheme.applyTheme(theme, {
            buttonIds: ['themeToggleBtn', 'workspaceThemeToggle'],
            getButtonLabel: (isDark) => {
                const labelKey = isDark ? 'themeLight' : 'themeDark';
                return translations[currentLanguage][labelKey] || (isDark ? '☀️ Light' : '🌙 Dark');
            },
            getButtonTitle: () => translations[currentLanguage].themeToggleTitle || 'Switch light/dark theme'
        });
        return;
    }
    const next = theme === 'dark' ? 'dark' : 'light';
    document.documentElement.classList.remove('print-color-mode-light');
    document.documentElement.setAttribute('data-theme', next);
    document.documentElement.style.colorScheme = next;
    localStorage.setItem('calendarTheme', next);
    updateThemeToggleButtons();
}

function loadTheme() {
    if (window.CCPTheme && window.CCPTheme.loadTheme) {
        applyTheme(window.CCPTheme.getStoredTheme());
        return;
    }
    applyTheme(getStoredTheme());
}

function toggleTheme() {
    if (window.CCPTheme && window.CCPTheme.toggleTheme) {
        window.CCPTheme.toggleTheme({
            buttonIds: ['themeToggleBtn', 'workspaceThemeToggle'],
            getButtonLabel: (isDark) => {
                const labelKey = isDark ? 'themeLight' : 'themeDark';
                return translations[currentLanguage][labelKey] || (isDark ? '☀️ Light' : '🌙 Dark');
            },
            getButtonTitle: () => translations[currentLanguage].themeToggleTitle || 'Switch light/dark theme'
        });
        return;
    }
    const current = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
    applyTheme(current === 'dark' ? 'light' : 'dark');
}

