let appData = getDefaultAppData();

/** Lightweight pub-sub store (js/core/app-store.js). */
let appStore = null;

function initAppStoreAndRenderOrchestrator() {
    if (typeof CCPAppStore === 'undefined') {
        return;
    }
    if (!appStore) {
        appStore = CCPAppStore.createAppStore(appData);
        appStore.configureMutationSync({
            shouldEnqueue(action) {
                if (typeof TeamAuth !== 'undefined' && TeamAuth.isViewAsMode && TeamAuth.isViewAsMode()) {
                    return false;
                }
                if (!teamSyncEnabled || typeof CalendarSync === 'undefined') {
                    return false;
                }
                if (CalendarSync.isReadOnly && CalendarSync.isReadOnly()) {
                    return false;
                }
                if (CalendarSync.state && CalendarSync.state.canEdit === false) {
                    return false;
                }
                if (!CalendarSync.getActiveCalendarId()) {
                    return false;
                }
                return true;
            }
        });
    } else {
        appStore.setStateRef(appData);
    }
    if (typeof CCPRenderOrchestrator === 'undefined') {
        return;
    }
    CCPRenderOrchestrator.register('calendar', () => {
        if (typeof renderCalendarNow === 'function') {
            renderCalendarNow();
        }
    });
    CCPRenderOrchestrator.register('classList', () => {
        if (typeof renderClassList === 'function') {
            renderClassList();
        }
    });
    CCPRenderOrchestrator.register('eventList', () => {
        if (typeof renderEventList === 'function') {
            renderEventList();
        }
    });
    CCPRenderOrchestrator.register('classNotes', () => {
        if (document.getElementById('classNotesShell') && typeof renderClassNotesTab === 'function') {
            renderClassNotesTab();
        }
        if (!isNotesPage() && typeof refreshNotesPageIfMounted === 'function') {
            refreshNotesPageIfMounted();
        }
    });
    CCPRenderOrchestrator.register('syllabus', () => {
        if (typeof renderSyllabusClassList === 'function') {
            renderSyllabusClassList();
        }
        if (typeof renderAllSyllabusTables === 'function') {
            renderAllSyllabusTables();
        }
    });
    CCPRenderOrchestrator.register('timetable', () => {
        if (typeof renderTimetableView === 'function') {
            renderTimetableView();
        }
    });
    CCPRenderOrchestrator.register('cohorts', () => {
        if (typeof refreshCohortsSetupBoard === 'function') {
            refreshCohortsSetupBoard();
        }
    });
    CCPRenderOrchestrator.register('setup-hub', () => {
        if (typeof CCPSetupHub !== 'undefined' && CCPSetupHub.refresh) {
            CCPSetupHub.refresh();
        }
        if (typeof CCPSetupBoard !== 'undefined' && CCPSetupBoard.renderBoardForScope) {
            CCPSetupBoard.renderBoardForScope('panel-setup-hub');
        }
    });
    CCPRenderOrchestrator.register('homework', () => {
        if (typeof renderHomeworkClassList === 'function') {
            renderHomeworkClassList();
        }
        if (typeof renderHomeworkEditor === 'function') {
            renderHomeworkEditor();
        }
    });
    CCPRenderOrchestrator.register('setupBoard', () => {
        if (typeof refreshCohortsSetupBoard === 'function') {
            refreshCohortsSetupBoard();
        }
    });
    if (!initAppStoreAndRenderOrchestrator._subscribed) {
        initAppStoreAndRenderOrchestrator._subscribed = true;
        CCPRenderOrchestrator.subscribeToStore(appStore);
        appStore.use((action) => {
            const scheduleTypes = new Set([
                'classes/upsert',
                'classes/remove',
                'events/upsert',
                'events/remove',
                'calendar/replace',
                'sync/remote'
            ]);
            if (scheduleTypes.has(action.type) && typeof invalidateScheduleCache === 'function') {
                invalidateScheduleCache();
            }
        });
    }
}

function dispatchUiSet(key, value, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'ui/set', key, value, meta: meta || {} });
    }
    ensureUiState();
    appData.ui[key] = value;
    return null;
}

function dispatchUiMerge(partial, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'ui/merge', partial, meta: meta || {} });
    }
    ensureUiState();
    Object.assign(appData.ui, partial);
    return null;
}

function requestUiCalendarRender() {
    if (typeof CCPRenderOrchestrator !== 'undefined') {
        CCPRenderOrchestrator.requestRender('calendar');
    } else {
        renderCalendar();
    }
}

function dispatchCalendarReplace(data, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'calendar/replace', data, meta: meta || {} });
    }
    Object.keys(appData).forEach((k) => {
        delete appData[k];
    });
    Object.assign(appData, data);
    return null;
}

function dispatchSyncRemote(data, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'sync/remote', data, meta: meta || {} });
    }
    Object.keys(data || {}).forEach((k) => {
        if (k !== 'ui') {
            appData[k] = data[k];
        }
    });
    return null;
}

function dispatchClassesUpsert(classData, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'classes/upsert', classData, meta: meta || {} });
    }
    if (!Array.isArray(appData.classes)) {
        appData.classes = [];
    }
    const idx = appData.classes.findIndex((c) => c && c.id === classData.id);
    if (idx >= 0) {
        appData.classes[idx] = classData;
    } else {
        appData.classes.push(classData);
    }
    return null;
}

function dispatchClassesRemove(id, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'classes/remove', id, meta: meta || {} });
    }
    appData.classes = (appData.classes || []).filter((c) => c && c.id !== id);
    return null;
}

function dispatchEventsUpsert(event, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'events/upsert', event, meta: meta || {} });
    }
    if (!Array.isArray(appData.events)) {
        appData.events = [];
    }
    const idx = appData.events.findIndex((e) => e && e.id === event.id);
    if (idx >= 0) {
        appData.events[idx] = event;
    } else {
        appData.events.push(event);
    }
    return null;
}

function dispatchEventsRemove(id, meta) {
    if (appStore) {
        return appStore.dispatch({ type: 'events/remove', id, meta: meta || {} });
    }
    appData.events = (appData.events || []).filter((e) => e && e.id !== id);
    return null;
}

function initListViewModules() {
    if (typeof CCPClassListView !== 'undefined') {
        CCPClassListView.init({
            getClasses: () => filterClassesForActiveCohort(getClassesInDisplayOrder()),
            getSelectedId: () => (elements.classId && elements.classId.value) || '',
            getSearchQuery: () => (document.getElementById('classListSearch')?.value) || '',
            onSelectClass: (classData) => {
                openClassEditor(classData, 'tab');
                renderClassList();
            },
            t,
            escapeHtml,
            formatClassLabelWithPeriod,
            getClassScheduleGapStatus,
            getClassCurriculumWarningKindForClass,
            inlineWarnBadgeHtml,
            scheduleTabWarningsRefresh
        });
    }
    if (typeof CCPEventListView !== 'undefined') {
        CCPEventListView.init({
            getEvents: () => filterEventsForActiveCohort(appData.events || []),
            getSelectedId: () => (elements.holidayId && elements.holidayId.value) || '',
            getSearchQuery: () => (document.getElementById('eventListSearch')?.value) || '',
            onSelectEvent: (ev) => {
                openEventEditor(ev, 'tab');
                renderEventList();
            },
            getEventDisplayName,
            t,
            escapeHtml
        });
    }
    if (typeof CCPCalendarView !== 'undefined') {
        CCPCalendarView.init({ onCalendarAction: () => {} });
    }
}

function bindAppStoreMutationSync(calendarId) {
    if (!appStore || typeof appStore.setMutationCalendarId !== 'function') {
        return;
    }
    appStore.setMutationCalendarId(calendarId || null);
    if (typeof CalendarSync !== 'undefined' && CalendarSync.setMutationSource) {
        CalendarSync.setMutationSource({
            getMutationQueue: () => appStore.getMutationQueue(),
            flushMutationQueue: (n) => appStore.flushMutationQueue(n)
        });
    }
}

function updateOfflineQueueNotice(queueCount) {
    if (typeof CCPPageChrome === 'undefined' || !CCPPageChrome.showNotice) {
        return;
    }
    if (!queueCount) {
        if (typeof CCPPageChrome !== 'undefined' && CCPPageChrome.dismissNotice) {
            CCPPageChrome.dismissNotice();
        }
        return;
    }
    const offline =
        (typeof CalendarSync !== 'undefined' &&
            CalendarSync.state &&
            CalendarSync.state.syncStatus === 'queued') ||
        !teamSyncEnabled;
    if (offline || queueCount > 0) {
        CCPPageChrome.showNotice(t('syncOfflineQueued'), {
            type: 'info',
            duration: 0,
            force: false
        });
    }
}

function rebindAppStoreStateRef() {
    if (appStore) {
        appStore.setStateRef(appData);
    }
}

/**
 * Run mutate + async save; restore slice snapshot on hard failure (not 409 merge).
 * @param {string} slice
 * @param {() => void} mutateFn
 * @param {() => Promise<void>} saveFn
 */
async function dispatchAsyncSaveWithRollback(slice, mutateFn, saveFn) {
    if (!appStore || typeof CCPAppStore === 'undefined') {
        mutateFn();
        await saveFn();
        return;
    }
    const snapshot = CCPAppStore.snapshotSlice(appStore, slice);
    mutateFn();
    try {
        await saveFn();
    } catch (err) {
        if (err && err.status !== 409 && err.status !== 423) {
            CCPAppStore.restoreSlice(appStore, slice, snapshot);
        }
        throw err;
    }
}

// Color palette for auto-assigning
const colorPalette = [
    '#e67e22', // Orange
    '#27ae60', // Green
    '#3498db', // Blue
    '#9b59b6', // Purple
    '#e74c3c', // Red
    '#1abc9c', // Teal
    '#f39c12', // Yellow
    '#34495e', // Dark Blue
    '#e91e63', // Pink
    '#00bcd4', // Cyan
    '#8bc34a', // Light Green
    '#ff5722'  // Deep Orange
];

let colorIndex = 0;

const DEFAULT_CLASS_TEXT_COLOR = '#ffffff';

const SCHEDULE_CONFIG = {
    maxMergeIterations: 48,
    defaultTermCalendarMonths: 3,
    minTermMonthCount: 3,
    maxTermMonthCount: 6,
    /** Prefer merging this lesson day with the next first (e.g. 2 = combine Day 2+3). */
    autoMergePreferredPairStart: 2
};

/** School day periods (1 = first period … 7 = seventh). */
const CLASS_PERIOD_MIN = 1;
const CLASS_PERIOD_MAX = 7;

function parseClassPeriodValue(raw) {
    if (raw === undefined || raw === null || raw === '') {
        return null;
    }
    const n = parseInt(String(raw).trim(), 10);
    if (Number.isNaN(n) || n < getClassPeriodMin() || n > getClassPeriodMax()) {
        return null;
    }
    return n;
}

function normalizePeriodByWeekday(map) {
    if (!map || typeof map !== 'object') {
        return null;
    }
    const out = {};
    Object.keys(map).forEach(key => {
        const dow = parseInt(key, 10);
        if (Number.isNaN(dow) || dow < 0 || dow > 6) {
            return;
        }
        const p = parseClassPeriodValue(map[key]);
        if (p !== null) {
            out[String(dow)] = p;
        }
    });
    return Object.keys(out).length ? out : null;
}

/** Period for one class; optional weekday (0=Sun … 6=Sat) uses periodByWeekday when set. */
function getClassPeriodNumber(classData, weekday) {
    if (!classData) {
        return null;
    }
    if (weekday !== undefined && weekday !== null) {
        const byWd = normalizePeriodByWeekday(classData.periodByWeekday);
        if (byWd && byWd[String(weekday)] !== undefined) {
            return byWd[String(weekday)];
        }
    }
    return parseClassPeriodValue(classData.period);
}

function getEffectiveClassPeriodValues(classData) {
    if (!classData) {
        return [];
    }
    const byWd = normalizePeriodByWeekday(classData.periodByWeekday);
    const meetingDays = getMeetingDaysFromClass(classData);
    if (byWd && meetingDays.length) {
        const vals = meetingDays
            .map(d => byWd[String(d)] ?? getClassPeriodNumber(classData))
            .filter(p => p !== null);
        if (vals.length) {
            return vals;
        }
    }
    const p = getClassPeriodNumber(classData);
    return p !== null ? [p] : [];
}

function classPeriodVariesByDay(classData) {
    const vals = getEffectiveClassPeriodValues(classData);
    return new Set(vals).size > 1;
}

function getClassPeriodForSort(classData, weekday) {
    if (weekday !== undefined && weekday !== null) {
        const p = getClassPeriodNumber(classData, weekday);
        if (p !== null) {
            return p;
        }
    }
    const vals = getEffectiveClassPeriodValues(classData);
    if (vals.length) {
        return Math.min(...vals);
    }
    return null;
}

function formatClassPeriodSummary(classData) {
    const vals = [...new Set(getEffectiveClassPeriodValues(classData))].sort((a, b) => a - b);
    if (!vals.length) {
        return '';
    }
    if (vals.length === 1) {
        return String(vals[0]);
    }
    return vals.join(', ');
}

function parseClassPeriodFromInput(elOrValue) {
    let raw;
    if (elOrValue && typeof elOrValue === 'object' && 'value' in elOrValue) {
        raw = elOrValue.value;
    } else {
        raw = elOrValue;
    }
    if (raw === undefined || raw === null || String(raw).trim() === '') {
        return null;
    }
    const n = parseInt(String(raw).trim(), 10);
    if (Number.isNaN(n) || n < getClassPeriodMin() || n > getClassPeriodMax()) {
        return null;
    }
    return n;
}

function compareClassesForDisplayOrder(a, b, weekday) {
    const pa = getClassPeriodForSort(a, weekday);
    const pb = getClassPeriodForSort(b, weekday);
    if (pa !== null && pb !== null && pa !== pb) {
        return pa - pb;
    }
    if (pa !== null && pb === null) {
        return -1;
    }
    if (pa === null && pb !== null) {
        return 1;
    }
    const na = (a && a.name) ? String(a.name) : '';
    const nb = (b && b.name) ? String(b.name) : '';
    return na.localeCompare(nb, undefined, { sensitivity: 'base' });
}

function getClassesInDisplayOrder() {
    return [...appData.classes].sort(compareClassesForDisplayOrder);
}

function filterClassesForActiveCohort(classes) {
    const list = Array.isArray(classes) ? classes : [];
    if (typeof CCPCohortSidebarFilter === 'undefined') {
        return list;
    }
    const cohortId = CCPCohortSidebarFilter.getActiveCohortId();
    return CCPCohortSidebarFilter.filterClassesByCohort(list, cohortId);
}

function filterEventsForActiveCohort(events) {
    const list = Array.isArray(events) ? events : [];
    if (typeof CCPCohortSidebarFilter === 'undefined') {
        return list;
    }
    const cohortId = CCPCohortSidebarFilter.getActiveCohortId();
    return CCPCohortSidebarFilter.filterEventsByCohort(list, cohortId, appData.classes || []);
}

function openHomeworkFromTimetable(classId, options) {
    if (!classId) {
        return;
    }
    const dateStr =
        options && options.dow != null
            ? resolveIsoDateForWeekdayInCurrentWeek(options.dow)
            : formatDateISO(new Date());
    if (typeof CCPActiveContext !== 'undefined') {
        CCPActiveContext.setFromClass(appData, classId, dateStr, 'timetable-click');
    }
    ensureUiState();
    appData.ui.homeworkTabClassId = classId;
    saveUiStateToLocalStorage();
    navigateToZone(APP_ZONE_SCHEDULE, 'homework', { classId });
}

function printClassSyllabusByClassId(classId) {
    if (!classId) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const mod = getSyllabusModule();
    if (!mod) {
        alert(t('syllabusModuleMissing'));
        return;
    }
    const saved = appData.classes.find((c) => c.id === classId);
    if (!saved) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const syllabusRows = resolveSyllabusRowsForPrint(saved);
    if (!syllabusRows.length) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const sectionMeta = getSyllabusSectionMeta(saved);
    const sections = [{
        classData: saved,
        rows: syllabusRows,
        classTitle: sectionMeta.classTitle,
        jindoTitle: buildJindoPrintTitle(saved),
        tableYear: sectionMeta.tableYear,
        subtitle: sectionMeta.subtitle,
        termRange: sectionMeta.termRange
    }];
    const meta = {
        title: (appData.calendarName && appData.calendarName.trim()) || t('syllabusTables'),
        subtitle: appData.termStart ? appData.termStart : ''
    };
    const labels = {
        ...getSyllabusTableLabels(saved),
        ...getSyllabusRenderLabels(saved)
    };
    printSyllabusDocument(
        mod.renderSyllabusDocumentHtml(meta, sections, labels),
        sectionMeta.classTitle
    );
}

function normalizeLessonFilters(raw) {
    const out = { ...DEFAULT_LESSON_FILTERS };
    if (!raw || typeof raw !== 'object') {
        return out;
    }
    out.hideAllLessons = raw.hideAllLessons === true;
    LESSON_FILTER_DIMENSIONS.forEach(key => {
        if (raw[key] === undefined || raw[key] === null) {
            return;
        }
        if (!Array.isArray(raw[key])) {
            return;
        }
        if (raw[key].length === 0) {
            out[key] = [];
            return;
        }
        out[key] = raw[key].map(v => String(v));
    });
    return out;
}

function isLessonFilterActive() {
    ensureUiState();
    const f = appData.ui.lessonFilters;
    if (!f) {
        return false;
    }
    if (f.hideAllLessons) {
        return true;
    }
    return hasRestrictiveLessonFilter(f);
}

function hasRestrictiveLessonFilter(f) {
    if (!f) {
        return false;
    }
    return LESSON_FILTER_DIMENSIONS.some(key => Array.isArray(f[key]) && f[key].length > 0);
}

function classPassesLessonFilters(classData) {
    if (!classData) {
        return false;
    }
    if (!isLessonFilterActive()) {
        return true;
    }
    const f = appData.ui.lessonFilters;
    if (f.hideAllLessons) {
        return false;
    }
    if (!hasRestrictiveLessonFilter(f)) {
        return true;
    }
    if (Array.isArray(f.classIds) && f.classIds.length > 0) {
        if (!f.classIds.includes(classData.id)) {
            return false;
        }
    }
    if (Array.isArray(f.grades) && f.grades.length > 0) {
        const gradeToken = (classData.grade || '').trim() || LESSON_FILTER_NO_GRADE;
        if (!f.grades.includes(gradeToken)) {
            return false;
        }
    }
    if (Array.isArray(f.levelPresets) && f.levelPresets.length > 0) {
        const levelToken = (classData.levelPreset || '').trim() || LESSON_FILTER_NO_LEVEL;
        if (!f.levelPresets.includes(levelToken)) {
            return false;
        }
    }
    if (Array.isArray(f.classTypeIds) && f.classTypeIds.length > 0) {
        const typeToken = (classData.classTypeId || '').trim() || LESSON_FILTER_NO_TYPE;
        if (!f.classTypeIds.includes(typeToken)) {
            return false;
        }
    }
    if (Array.isArray(f.periods) && f.periods.length > 0) {
        const periodVals = getEffectiveClassPeriodValues(classData).map(p => String(p));
        if (!periodVals.some(p => f.periods.includes(p))) {
            return false;
        }
    }
    if (Array.isArray(f.books) && f.books.length > 0) {
        const bookToken = (classData.book || '').trim() || LESSON_FILTER_NO_BOOK;
        if (!f.books.includes(bookToken)) {
            return false;
        }
    }
    if (Array.isArray(f.teacherUserIds) && f.teacherUserIds.length > 0) {
        if (!classMatchesLessonFilterTeachers(classData, f.teacherUserIds)) {
            return false;
        }
    }
    return true;
}

function getClassTeachersListForLessonFilter(classData) {
    const api = getTimetableApi();
    if (api && api.getClassTeachersList) {
        return api.getClassTeachersList(classData);
    }
    if (!classData) {
        return [];
    }
    const list = [];
    if (Array.isArray(classData.classTeachers)) {
        classData.classTeachers.forEach((row) => {
            const userId = String(row.userId || '').trim();
            const name = String(row.name || '').trim();
            if (userId || name || String(row.curriculumId || '').trim()) {
                list.push({ userId, name });
            }
        });
    }
    if (!list.length) {
        const userId = String(classData.assignedTeacherUserId || '').trim();
        const name = String(classData.assignedTeacherName || '').trim();
        if (userId || name || String(classData.curriculumId || '').trim()) {
            list.push({ userId, name });
        }
    }
    return list;
}

function normalizeLessonFilterTeacherName(name) {
    return String(name == null ? '' : name).trim().toLowerCase().replace(/\s+/g, ' ');
}

function lessonFilterTeacherNamesMatch(a, b) {
    const left = normalizeLessonFilterTeacherName(a);
    const right = normalizeLessonFilterTeacherName(b);
    if (!left || !right) {
        return false;
    }
    if (left === right) {
        return true;
    }
    if (left.includes(right) || right.includes(left)) {
        return true;
    }
    const lt = left.split(/[\s,]+/).filter(Boolean);
    const rt = right.split(/[\s,]+/).filter(Boolean);
    return Boolean(lt[0] && rt[0] && lt[0] === rt[0]);
}

function lessonFilterTeacherMatchesRef(ref, selector) {
    if (!ref || !selector) {
        return false;
    }
    const uid = String(selector.userId || '').trim();
    const refUid = String(ref.userId || ref.assignedTeacherUserId || '').trim();
    const refName = ref.displayName || ref.name || ref.assignedTeacherName || '';
    const selName = selector.displayName || '';
    if (uid && refUid && uid === refUid) {
        return true;
    }
    return lessonFilterTeacherNamesMatch(selName, refName);
}

function teacherMatchesClassForLessonFilter(classData, selector) {
    if (!classData || !selector) {
        return false;
    }
    const api = getTimetableApi();
    if (api && api.teacherMatchesClass) {
        return api.teacherMatchesClass(classData, selector);
    }
    return getClassTeachersListForLessonFilter(classData).some((row) =>
        lessonFilterTeacherMatchesRef({ userId: row.userId, displayName: row.name }, selector)
    );
}

function classHasNoAssignedTeacherAccount(classData) {
    if (!classData) {
        return true;
    }
    const rows = getClassTeachersListForLessonFilter(classData);
    if (!rows.length) {
        return !(classData.assignedTeacherUserId || '').trim();
    }
    return !rows.some((row) => (row.userId || '').trim());
}

function lessonFilterTeacherSelectorForUserId(userId) {
    const uid = String(userId || '').trim();
    if (!uid || uid === LESSON_FILTER_NO_TEACHER) {
        return null;
    }
    const viewer = getCalendarViewerTeacherSelector();
    if (viewer && viewer.userId === uid) {
        return viewer;
    }
    const row = listTimetableTeachers().find((t) => t.userId === uid);
    return {
        userId: uid,
        displayName: row ? (row.displayName || row.name || uid) : uid
    };
}

function classMatchesLessonFilterTeachers(classData, teacherUserIds) {
    if (!teacherUserIds || !teacherUserIds.length) {
        return true;
    }
    let matched = false;
    if (teacherUserIds.includes(LESSON_FILTER_NO_TEACHER) && classHasNoAssignedTeacherAccount(classData)) {
        matched = true;
    }
    teacherUserIds.forEach((uid) => {
        if (uid === LESSON_FILTER_NO_TEACHER) {
            return;
        }
        const selector = lessonFilterTeacherSelectorForUserId(uid);
        if (selector && teacherMatchesClassForLessonFilter(classData, selector)) {
            matched = true;
        }
    });
    return matched;
}

function getActiveLessonFilterTeacherSelectors() {
    ensureUiState();
    const f = appData.ui.lessonFilters;
    if (!f || !Array.isArray(f.teacherUserIds) || !f.teacherUserIds.length) {
        return [];
    }
    const teachers = listTimetableTeachers();
    return f.teacherUserIds
        .filter((uid) => uid && uid !== LESSON_FILTER_NO_TEACHER)
        .map((uid) => {
            const row = teachers.find((t) => t.userId === uid);
            return {
                userId: uid,
                displayName: row ? (row.displayName || uid) : uid
            };
        });
}

function getVisibleClassesInDisplayOrder() {
    return getClassesInDisplayOrder().filter(classPassesLessonFilters);
}

/** Visible classes that also have lessons in the displayed term (what the calendar can show). */
function getVisibleScheduledClassesInDisplayOrder() {
    return getClassesScheduledOnCalendar().filter(classPassesLessonFilters);
}

/** Classes used for calendar lesson bars and class-related print summary when no lesson filter is on. */
function getClassesForCalendarAndPrintSummary() {
    if (isLessonFilterActive()) {
        return getVisibleScheduledClassesInDisplayOrder();
    }
    return getClassesScheduledOnCalendar();
}

/** True if this class has at least one lesson on a day inside the displayed term months. */
function classHasLessonsInDisplayedTerm(classData) {
    const { start, end } = getTermDateRangeISO();
    if (!classData || !start || !end) {
        return false;
    }
    const rangeStart = parseISODateLocal(start);
    const rangeEnd = parseISODateLocal(end);
    if (!rangeStart || !rangeEnd) {
        return false;
    }
    const slices = getClassCurriculumSlicesForCalendar(classData);
    return slices.some((slice) => {
        const { lessons } = calculateLessonDates(classData, {
            sliceKey: slice.sliceKey,
            effectiveClassData: slice.classData
        });
        return lessons.some(lesson => {
        const d = lesson && lesson.date;
        if (!d || !(d instanceof Date) || Number.isNaN(d.getTime())) {
            return false;
        }
        const day = new Date(d.getFullYear(), d.getMonth(), d.getDate());
        return day >= rangeStart && day <= rangeEnd;
        });
    });
}

/** Classes that actually have lesson bars in the current term calendar view. */
function getClassesScheduledOnCalendar() {
    return getClassesInDisplayOrder().filter(classHasLessonsInDisplayedTerm);
}

function countScheduledClassesOnCalendar() {
    return getClassesScheduledOnCalendar().length;
}

function countVisibleClassesForLessonFilter() {
    return getClassesScheduledOnCalendar().filter(classPassesLessonFilters).length;
}

function getVisibleClassIdsForLessonFilter() {
    if (!isLessonFilterActive()) {
        return null;
    }
    return getVisibleScheduledClassesInDisplayOrder().map(c => c.id);
}

function getNextSuggestedClassPeriod() {
    const periods = appData.classes.map(getClassPeriodNumber).filter(n => n !== null);
    if (periods.length === 0) {
        return CLASS_PERIOD_MIN;
    }
    return Math.min(Math.max(...periods) + 1, getClassPeriodMax());
}

function formatClassLabelWithPeriod(classData) {
    const name = classData && classData.name ? classData.name : '';
    const summary = formatClassPeriodSummary(classData);
    if (!summary) {
        return name;
    }
    return `P${summary} · ${name}`;
}

function buildClassPeriodSelectInnerHtml(selectedValue) {
    const sel = selectedValue != null && selectedValue !== '' ? String(selectedValue) : '';
    let html = '<option value="">—</option>';
    const maxP = getClassPeriodMax();
    const minP = getClassPeriodMin();
    for (let p = minP; p <= maxP; p += 1) {
        const chosen = sel === String(p) ? ' selected' : '';
        html += `<option value="${p}"${chosen}>${p}</option>`;
    }
    return html;
}

function upgradeClassPeriodFieldToSelect(fieldEl) {
    if (!fieldEl) {
        return null;
    }
    if (fieldEl.tagName === 'SELECT') {
        fieldEl.innerHTML = buildClassPeriodSelectInnerHtml(fieldEl.value);
        return fieldEl;
    }
    const select = document.createElement('select');
    select.id = fieldEl.id || 'classPeriod';
    if (fieldEl.className) {
        select.className = fieldEl.className;
    }
    select.innerHTML = buildClassPeriodSelectInnerHtml(fieldEl.value);
    fieldEl.replaceWith(select);
    return select;
}

function ensureClassPeriodMarkup() {
    const form = document.getElementById('classForm');
    if (!form) {
        return;
    }

    let periodField = document.getElementById('classPeriod');
    if (!periodField) {
        const levelRow = form.querySelector('#classLevel')?.closest('.form-row');
        if (!levelRow) {
            return;
        }
        const group = document.createElement('d' + 'iv');
        group.className = 'form-group form-group-class-period';
        group.innerHTML = `
            <label for="classPeriod" data-i18n="classPeriod">Period</label>
            <select id="classPeriod"></select>
            <p class="section-hint" data-i18n="classPeriodHint"></p>`;
        levelRow.insertBefore(group, levelRow.firstChild);
        periodField = group.querySelector('#classPeriod');
    }

    elements.classPeriod = upgradeClassPeriodFieldToSelect(periodField);
    ensurePeriodByDayMarkup();
}

function periodVariesFromMap(periodByWeekday, meetingDays) {
    const map = normalizePeriodByWeekday(periodByWeekday);
    if (!map || !meetingDays || meetingDays.length < 2) {
        return false;
    }
    const vals = meetingDays.map(d => map[String(d)]).filter(p => p !== null && p !== undefined);
    return new Set(vals).size > 1;
}

function ensurePeriodByDayMarkup() {
    const form = document.getElementById('classForm');
    const periodGroup = form && form.querySelector('.form-group-class-period');
    if (!periodGroup || document.getElementById('classPeriodByDayWrap')) {
        return;
    }
    const wrap = document.createElement('div');
    wrap.id = 'classPeriodByDayWrap';
    wrap.className = 'form-group class-period-by-day-wrap';
    wrap.hidden = true;
    wrap.innerHTML = `
        <label class="checkbox-label class-period-varies-label">
            <input type="checkbox" id="classPeriodVariesByDay">
            <span data-i18n="classPeriodVariesByDay">Different period on some meeting days</span>
        </label>
        <p class="section-hint" data-i18n="classPeriodVariesByDayHint"></p>
        <div id="classPeriodByDayRow" class="period-by-day-row" role="group" aria-label="Period by day"></div>`;
    periodGroup.insertAdjacentElement('afterend', wrap);

    const variesCb = document.getElementById('classPeriodVariesByDay');
    if (variesCb && !variesCb.dataset.bound) {
        variesCb.dataset.bound = '1';
        variesCb.addEventListener('change', () => syncPeriodByDayUi());
    }
    if (elements.classPeriod && !elements.classPeriod.dataset.periodByDayBound) {
        elements.classPeriod.dataset.periodByDayBound = '1';
        elements.classPeriod.addEventListener('change', () => {
            if (!document.getElementById('classPeriodVariesByDay')?.checked) {
                return;
            }
            const meetingDays = readMeetingDaysFromFormScope('#classForm', MEETING_DAY_INPUT_CLASS);
            renderPeriodByDayRow(document.getElementById('classPeriodByDayRow'), meetingDays);
        });
    }
}

function readPeriodByWeekdayFromForm() {
    const out = {};
    document.querySelectorAll('#classPeriodByDayRow select.class-period-by-day').forEach(sel => {
        const d = parseInt(sel.dataset.weekday, 10);
        const p = parseClassPeriodFromInput(sel);
        if (!Number.isNaN(d) && p !== null) {
            out[d] = p;
        }
    });
    return out;
}

function renderPeriodByDayRow(container, meetingDays) {
    if (!container) {
        return;
    }
    const short = t('dayNamesShort');
    const existing = readPeriodByWeekdayFromForm();
    const defaultP = elements.classPeriod
        ? (parseClassPeriodFromInput(elements.classPeriod) ?? CLASS_PERIOD_MIN)
        : CLASS_PERIOD_MIN;
    container.innerHTML = '';
    meetingDays.forEach(d => {
        const chip = document.createElement('div');
        chip.className = 'period-by-day-chip';
        const label = document.createElement('label');
        label.className = 'period-by-day-chip-label';
        const daySpan = document.createElement('span');
        daySpan.className = 'period-by-day-day';
        daySpan.textContent = short[d] != null ? short[d] : String(d);
        const sel = document.createElement('select');
        sel.dataset.weekday = String(d);
        sel.className = 'class-period-by-day';
        sel.innerHTML = buildClassPeriodSelectInnerHtml(existing[d] ?? defaultP);
        label.appendChild(daySpan);
        label.appendChild(sel);
        chip.appendChild(label);
        container.appendChild(chip);
    });
}

function syncPeriodByDayUi() {
    const wrap = document.getElementById('classPeriodByDayWrap');
    const variesCb = document.getElementById('classPeriodVariesByDay');
    const row = document.getElementById('classPeriodByDayRow');
    const periodGroup = document.querySelector('#classForm .form-group-class-period');
    if (!wrap || !variesCb || !row) {
        return;
    }
    const custom = elements.customScheduleEnabled && elements.customScheduleEnabled.checked;
    const meetingDays = readMeetingDaysFromFormScope('#classForm', MEETING_DAY_INPUT_CLASS);
    const showWrap = !custom && meetingDays.length >= 2;
    wrap.hidden = !showWrap;
    if (!showWrap) {
        variesCb.checked = false;
        row.innerHTML = '';
        if (periodGroup) {
            periodGroup.style.display = '';
        }
        return;
    }
    if (periodGroup) {
        periodGroup.style.display = variesCb.checked ? 'none' : '';
    }
    if (variesCb.checked) {
        renderPeriodByDayRow(row, meetingDays);
    } else {
        row.innerHTML = '';
    }
}

function writePeriodByWeekdayToForm(periodByWeekday, meetingDays) {
    const variesCb = document.getElementById('classPeriodVariesByDay');
    if (!variesCb) {
        return;
    }
    variesCb.checked = periodVariesFromMap(periodByWeekday, meetingDays);
    syncPeriodByDayUi();
    if (!variesCb.checked) {
        return;
    }
    const map = normalizePeriodByWeekday(periodByWeekday) || {};
    document.querySelectorAll('#classPeriodByDayRow select.class-period-by-day').forEach(sel => {
        const d = sel.dataset.weekday;
        if (map[d] !== undefined) {
            sel.value = String(map[d]);
        }
    });
}

function collectPeriodFieldsForSave() {
    const variesCb = document.getElementById('classPeriodVariesByDay');
    const meetingDays = readMeetingDaysFromFormScope('#classForm', MEETING_DAY_INPUT_CLASS);
    let period = elements.classPeriod ? parseClassPeriodFromInput(elements.classPeriod) : null;
    let periodByWeekday = null;
    if (variesCb && variesCb.checked && meetingDays.length >= 2) {
        const map = {};
        meetingDays.forEach(d => {
            const sel = document.querySelector(
                `#classPeriodByDayRow select.class-period-by-day[data-weekday="${d}"]`
            );
            const p = sel ? parseClassPeriodFromInput(sel) : period;
            if (p !== null) {
                map[String(d)] = p;
            }
        });
        const vals = Object.values(map);
        if (vals.length) {
            periodByWeekday = map;
            period = Math.min(...vals);
        }
    }
    return { period, periodByWeekday };
}

function applyPeriodFieldsToClassForm(classData) {
    if (!classData) {
        return;
    }
    if (elements.classPeriod) {
        const p = getClassPeriodNumber(classData);
        elements.classPeriod.value = p !== null ? String(p) : '';
    }
    const meetingDays = getMeetingDaysFromClass(classData);
    writePeriodByWeekdayToForm(classData.periodByWeekday, meetingDays);
}

