/** Match sticky month header / panels to the real global top bar height (avoids a gap below it). */
function syncAppChromeStickyTop() {
    const topBar = document.getElementById('appTopBar');
    if (!topBar) {
        return;
    }
    const topHeight = Math.ceil(topBar.getBoundingClientRect().height);
    if (topHeight > 0) {
        document.documentElement.style.setProperty('--app-chrome-sticky-top', `${topHeight}px`);
    }

    let monthStickyTop = topHeight > 0 ? topHeight : 72;
    const dock = document.querySelector('.calendar-visibility-dock');
    if (
        dock
        && typeof getActiveTab === 'function'
        && getActiveTab() === 'calendar'
        && !dock.hidden
    ) {
        monthStickyTop += Math.ceil(dock.getBoundingClientRect().height) + 8;
    }
    document.documentElement.style.setProperty('--calendar-month-sticky-top', `${monthStickyTop}px`);
    syncCohortsBoardStickyOffsets();
    if (
        openHeaderFixedPopoverId
        || isLessonFilterPopoverOpen()
        || isEventApplicabilityPopoverOpen()
    ) {
        scheduleForcedRepositionAllFixedAnchorPopovers();
    }
}

