/** Subject category for Teachers tab catalog (classTeachers, legacy field, or derive). */
function getClassCatalogCategory(classData) {
    if (!classData) {
        return '';
    }
    const teachers = classData.classTeachers;
    if (Array.isArray(teachers) && teachers.length) {
        const cat = (teachers[0].category || '').trim();
        if (cat) {
            return cat;
        }
    }
    const legacy = (classData.teacherCategory || '').trim();
    if (legacy) {
        return legacy;
    }
    const api = getTimetableApi();
    if (api && typeof api.deriveTeacherCategory === 'function') {
        return String(api.deriveTeacherCategory(classData) || '').trim();
    }
    return '';
}

const HOMEROOM_NONE_KEY = '__no_homeroom__';

function buildCohortsByIdMap() {
    const cohortsById = {};
    (appData.cohorts || []).forEach((c) => {
        if (c && c.id) {
            cohortsById[c.id] = c;
        }
    });
    return cohortsById;
}

function resolveHomeroomTeacherDisplayName(hrUid) {
    const uid = String(hrUid || '').trim();
    if (!uid) {
        return '';
    }
    const row = listTimetableTeachers().find((r) => r.userId === uid);
    if (row) {
        const name = String(row.displayName || row.name || '').trim();
        if (name && name !== uid) {
            return name;
        }
    }
    const api = getTimetableApi();
    if (api && typeof api.listTeachersFromAppData === 'function') {
        const fromData = api.listTeachersFromAppData(appData);
        const hit = fromData.find((r) => String(r.userId || '').trim() === uid);
        if (hit) {
            const name = String(hit.displayName || hit.name || '').trim();
            if (name && name !== uid) {
                return name;
            }
        }
    }
    for (const classData of appData.classes || []) {
        if (String(classData.homeroomTeacherUserId || '').trim() === uid) {
            const classHrName = String(classData.homeroomTeacherName || '').trim();
            if (classHrName) {
                return classHrName;
            }
        }
        for (const teacherRow of getClassTeachersListForLessonFilter(classData)) {
            if (String(teacherRow.userId || '').trim() === uid) {
                const teacherName = String(teacherRow.name || '').trim();
                if (teacherName) {
                    return teacherName;
                }
            }
        }
    }
    for (const cohort of appData.cohorts || []) {
        if (cohort && String(cohort.homeroomTeacherUserId || '').trim() === uid) {
            const cohortName = String(cohort.homeroomTeacherName || '').trim();
            if (cohortName) {
                return cohortName;
            }
        }
    }
    return '';
}

function resolveHomeroomMetaForClass(classData, cohortsById) {
    if (!classData) {
        return { key: HOMEROOM_NONE_KEY, label: t('cohortsNoHomeroom') };
    }
    const map = cohortsById || buildCohortsByIdMap();
    const api = getTimetableApi();
    let label = '';
    if (api && typeof api.resolveHomeroomLabel === 'function') {
        label = api.resolveHomeroomLabel(classData, map, appData) || '';
    }
    const hrUid = resolveHomeroomUserIdForClass(classData);
    const key = hrUid || HOMEROOM_NONE_KEY;
    if (key !== HOMEROOM_NONE_KEY && (!label || label === key)) {
        const resolved = resolveHomeroomTeacherDisplayName(key);
        if (resolved) {
            label = resolved;
        }
    }
    if (!label) {
        label = t('cohortsNoHomeroom');
    }
    return { key, label };
}

function getHomeroomOrderKeys(classIds) {
    const cohortsById = buildCohortsByIdMap();
    const seen = new Map();
    (classIds || []).forEach((classId) => {
        const classData = appData.classes.find((c) => c.id === classId);
        const meta = resolveHomeroomMetaForClass(classData, cohortsById);
        if (!seen.has(meta.key)) {
            seen.set(meta.key, meta.label);
        }
    });
    return [...seen.keys()].sort((a, b) => {
        if (a === HOMEROOM_NONE_KEY) {
            return 1;
        }
        if (b === HOMEROOM_NONE_KEY) {
            return -1;
        }
        return (seen.get(a) || '').localeCompare(seen.get(b) || '', undefined, { sensitivity: 'base' });
    });
}

function resolveDayNoteMeta(classId, displayNameOverride) {
    const classData = classId ? appData.classes.find((c) => c.id === classId) : null;
    if (!classData) {
        return {
            className: displayNameOverride || classId || '',
            subject: '',
            homeroomKey: HOMEROOM_NONE_KEY,
            homeroomLabel: t('cohortsNoHomeroom')
        };
    }
    const homeroom = resolveHomeroomMetaForClass(classData);
    return {
        className: displayNameOverride || classData.name || '',
        subject: getClassSubjectForDayNotes(classData),
        homeroomKey: homeroom.key,
        homeroomLabel: homeroom.label
    };
}

function resolveHomeroomUserIdForClass(classData) {
    const api = getTimetableApi();
    if (api && typeof api.resolveHomeroomUserIdForClass === 'function') {
        return api.resolveHomeroomUserIdForClass(classData, appData) || '';
    }
    if (!classData) {
        return '';
    }
    const classHr = String(classData.homeroomTeacherUserId || '').trim();
    if (classHr) {
        return classHr;
    }
    const cohortId = String(classData.cohortId || '').trim();
    if (cohortId) {
        const cohort = (appData.cohorts || []).find((c) => c && c.id === cohortId);
        if (cohort) {
            return String(cohort.homeroomTeacherUserId || '').trim();
        }
    }
    return '';
}

function resolveDayNoteSearchHay(classId) {
    const meta = resolveDayNoteMeta(classId);
    return [meta.className, meta.subject, meta.homeroomLabel].filter(Boolean).join(' ');
}

