function initCalendarContextMenu() {
    initLessonContextMenu();
    initTimetableContextMenu();
    if (document.getElementById('calendarContextMenu')) {
        return;
    }
    const menu = document.createElement('div');
    menu.id = 'calendarContextMenu';
    menu.className = 'calendar-context-menu';
    menu.hidden = true;

    const actions = [
        { action: 'view-day-notes', handler: () => {
            const dateStr = calendarContextMenuDate;
            hideCalendarContextMenu();
            if (dateStr) {
                openDayNotesSummaryModal(dateStr);
            }
        } },
        { action: 'copy-day-notes', handler: async () => {
            const dateStr = calendarContextMenuDate;
            hideCalendarContextMenu();
            if (dateStr) {
                await copyDayNotesForDate(dateStr);
            }
        } },
        { action: 'download-day-notes', handler: () => {
            const dateStr = calendarContextMenuDate;
            hideCalendarContextMenu();
            if (dateStr) {
                downloadDayNotesForDate(dateStr);
            }
        } },
        { action: 'add-event', handler: () => {
            const dateStr = calendarContextMenuDate;
            hideCalendarContextMenu();
            if (dateStr) {
                openEventEditor(null, 'calendar-popout', { defaultDate: dateStr });
            }
        } }
    ];

    actions.forEach(({ action, handler }) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'calendar-context-menu-item';
        btn.dataset.action = action;
        btn.addEventListener('click', handler);
        menu.appendChild(btn);
    });

    document.body.appendChild(menu);
    updateCalendarContextMenuLabels('');

    document.addEventListener('click', (e) => {
        const dayMenu = document.getElementById('calendarContextMenu');
        const lessonMenu = document.getElementById('lessonContextMenu');
        const timetableMenu = document.getElementById('timetableContextMenu');
        if (dayMenu && !dayMenu.contains(e.target) && dayMenu.hidden === false) {
            hideCalendarContextMenu();
        }
        if (lessonMenu && !lessonMenu.contains(e.target) && lessonMenu.hidden === false) {
            hideLessonContextMenu();
        }
        if (timetableMenu && !timetableMenu.contains(e.target) && timetableMenu.hidden === false) {
            hideTimetableContextMenu();
        }
    });
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            hideCalendarContextMenu();
        }
    });
    document.addEventListener('scroll', hideCalendarContextMenu, true);
    window.addEventListener('resize', hideCalendarContextMenu);
}

function initDayNotesUi() {
    if (document.body.dataset.dayNotesUiBound === '1') {
        return;
    }
    document.body.dataset.dayNotesUiBound = '1';

    document.getElementById('classDayNoteModalClose')?.addEventListener('click', closeClassDayNoteModal);
    document.getElementById('classDayNoteSaveBtn')?.addEventListener('click', saveClassDayNoteFromModal);
    document.getElementById('dayNoteCategoryModalClose')?.addEventListener('click', () => {
        const modal = document.getElementById('dayNoteCategoryModal');
        if (modal) {
            closeModal(modal);
        }
    });
    document.getElementById('dayNoteCategoryForm')?.addEventListener('submit', handleDayNoteCategoryFormSubmit);
    const dayNoteCategoryModal = document.getElementById('dayNoteCategoryModal');
    if (dayNoteCategoryModal) {
        bindModalBackdropClose(dayNoteCategoryModal);
    }
    document.getElementById('dayNotesSummaryModalClose')?.addEventListener('click', closeDayNotesSummaryModal);
    function bindOpenNotesAppControl(el) {
        if (!el || el.dataset.openNotesAppBound === '1') {
            return;
        }
        el.dataset.openNotesAppBound = '1';
        el.addEventListener('click', (e) => {
            if (el.tagName === 'A') {
                e.preventDefault();
            }
            const defaults = resolveDefaultOpenNotesParams();
            void openNotesPage(Object.assign({ sameTab: true }, defaults));
        });
    }

    bindOpenNotesAppControl(document.getElementById('openNotesAppHeaderBtn'));
    bindOpenNotesAppControl(document.getElementById('openNotesAppTabBtn'));
    bindOpenNotesAppControl(document.getElementById('openNotesAppLink'));

    document.getElementById('dayNotesToolbarBtn')?.addEventListener('click', () => {
        const defaults = resolveDefaultOpenNotesParams();
        const dateStr = defaults.dateStr;
        if (prefersMobileNotesNav()) {
            void openNotesPage(Object.assign({ sameTab: true }, defaults));
            return;
        }
        openDayNotesSummaryModal(dateStr);
    });
    document.getElementById('dayNotesSummaryTodayBtn')?.addEventListener('click', () => {
        const input = document.getElementById('dayNotesSummaryDate');
        const today = formatDateISO(new Date());
        if (input) {
            input.value = today;
        }
        lastDayNotesSummaryDate = today;
        renderDayNotesSummaryList(today);
    });
    document.getElementById('dayNotesSummaryDate')?.addEventListener('change', (e) => {
        const dateStr = e.target.value;
        if (dateStr) {
            lastDayNotesSummaryDate = dateStr;
            renderDayNotesSummaryList(dateStr);
        }
    });
    document.getElementById('dayNotesSummaryCopyBtn')?.addEventListener('click', async () => {
        const input = document.getElementById('dayNotesSummaryDate');
        const dateStr = input?.value || lastDayNotesSummaryDate;
        if (dateStr) {
            await copyDayNotesForDate(dateStr);
        }
    });
    document.getElementById('dayNotesSummaryDownloadBtn')?.addEventListener('click', () => {
        const input = document.getElementById('dayNotesSummaryDate');
        const dateStr = input?.value || lastDayNotesSummaryDate;
        if (dateStr) {
            downloadDayNotesForDate(dateStr);
        }
    });
}

const CLASS_NOTES_FILTER_ATTR = (typeof ClassNotesPanel !== 'undefined' && ClassNotesPanel.FILTER_ATTR)
    ? ClassNotesPanel.FILTER_ATTR
    : 'data-class-notes-filter';


function isClassNotesUiActive() {
    const tab = getActiveTab();
    return tab === 'notes' || (tab === 'classes' && classesPanelSegment === 'notes');
}

function ensureClassNotesShell() {
    let shell = document.getElementById('classNotesShell');
    if (shell) {
        return shell;
    }
    const tpl = document.getElementById('classNotesShellTemplate');
    const mount = document.getElementById('panelNotesMount');
    if (!tpl || !tpl.content || !mount) {
        return null;
    }
    mount.appendChild(tpl.content.cloneNode(true));
    return document.getElementById('classNotesShell');
}

function mountClassNotesShell(mountEl) {
    const shell = ensureClassNotesShell();
    if (!shell || !mountEl) {
        return;
    }
    if (shell.parentElement !== mountEl) {
        mountEl.appendChild(shell);
    }
}

function mountClassNotesToNotesTab() {
    mountClassNotesShell(document.getElementById('panelNotesMount'));
}

function mountClassNotesToClassesSegment() {
    mountClassNotesShell(document.getElementById('classesSegmentNotesMount'));
}

function getClassNotesSortMode() {
    const api = getDayNotesApi();
    ensureUiState();
    if (api && api.normalizeClassNotesSortMode) {
        return api.normalizeClassNotesSortMode(appData.ui.classNotesSort);
    }
    return 'classGroup';
}

function syncClassNotesSortSelect() {
    const select = document.getElementById('classNotesSortSelect');
    if (!select) {
        return;
    }
    select.value = getClassNotesSortMode();
}

function saveClassNotesSortToUi() {
    ensureUiState();
    const select = document.getElementById('classNotesSortSelect');
    const api = getDayNotesApi();
    const mode = api && api.normalizeClassNotesSortMode
        ? api.normalizeClassNotesSortMode(select ? select.value : '')
        : 'classGroup';
    appData.ui.classNotesSort = mode;
    saveUiStateToLocalStorage();
}

function updateClassDayNote(id, patch) {
    const api = getDayNotesApi();
    if (!api || !api.updateDayNote) {
        return false;
    }
    if (dayNoteSaveInFlight || (ensureDayNotesSaver() && ensureDayNotesSaver().isSaveInFlight())) {
        return false;
    }
    ensureDayNotesArray();
    const existing = appData.dayNotes.find((n) => n && n.id === id);
    if (!canUserEditDayNoteEntry(existing)) {
        showClassNotesExportStatus(false, getDayNoteEntryBlockedMessage(existing));
        return false;
    }
    const next = api.updateDayNote(appData.dayNotes, id, patch);
    if (next === appData.dayNotes) {
        return false;
    }
    const rollbackSnapshot = JSON.parse(JSON.stringify(appData.dayNotes));
    appData.dayNotes = next;
    if (appStore) {
        appStore.dispatch({ type: 'dayNotes/mutate', dayNotes: next, meta: { silent: true } });
    }
    void persistDayNotesAfterChange(rollbackSnapshot).then(() => {
        refreshDayNotesUiAfterChange(false);
    });
    return true;
}

function deleteClassDayNote(id) {
    const api = getDayNotesApi();
    if (!api || !api.removeDayNote) {
        return false;
    }
    if (dayNoteSaveInFlight || (ensureDayNotesSaver() && ensureDayNotesSaver().isSaveInFlight())) {
        return false;
    }
    ensureDayNotesArray();
    const existing = appData.dayNotes.find((n) => n && n.id === id);
    if (!canUserEditDayNoteEntry(existing)) {
        showClassNotesExportStatus(false, getDayNoteEntryBlockedMessage(existing));
        return false;
    }
    const rollbackSnapshot = JSON.parse(JSON.stringify(appData.dayNotes));
    appData.dayNotes = api.removeDayNote(appData.dayNotes, id);
    if (classNotesEditingId === id) {
        classNotesEditingId = null;
    }
    if (appStore) {
        appStore.dispatch({ type: 'dayNotes/mutate', dayNotes: appData.dayNotes, meta: { silent: true } });
    }
    void persistDayNotesAfterChange(rollbackSnapshot).then(() => {
        refreshDayNotesUiAfterChange(false);
    });
    return true;
}

function refreshNotesPageIfMounted() {
    if (
        document.body.classList.contains('notes-page')
        && typeof window.refreshNotesEditorAfterDayNotesChange === 'function'
    ) {
        window.refreshNotesEditorAfterDayNotesChange();
        return;
    }
    if (document.body.classList.contains('notes-page') && typeof window.finalizeNotesPageBoot === 'function') {
        window.finalizeNotesPageBoot({ invalidateIndex: true, preserveFocus: true });
        return;
    }
    if (typeof window.refreshNotesPageUi === 'function') {
        window.refreshNotesPageUi();
    }
}

function prefersMobileNotesNav() {
    return typeof window !== 'undefined' && window.matchMedia && window.matchMedia(`(max-width: ${VIEWPORT_BP_PHONE}px)`).matches;
}

async function openNotesPage(options = {}) {
    if (typeof CalendarSync !== 'undefined' && CalendarSync.flushPendingSave) {
        try {
            await CalendarSync.flushPendingSave();
        } catch (err) {
            if (err.status !== 423) {
                console.warn('Flush before notes open failed:', err);
            }
        }
    }
    const params = new URLSearchParams();
    let dateStr = options.dateStr || options.date;
    let classId = options.classId;
    if (!classId || !dateStr) {
        const ctx = getCurrentClassContext();
        if (ctx) {
            if (!dateStr) {
                dateStr = ctx.dateStr;
            }
            if (!classId) {
                classId = ctx.classId;
            }
        }
    }
    if (!dateStr) {
        dateStr = formatDateISO(new Date());
    }
    if (dateStr) {
        params.set('date', String(dateStr));
    }
    if (classId) {
        params.set('classId', String(classId));
    }
    if (typeof CalendarSync !== 'undefined' && CalendarSync.getActiveCalendarId) {
        const calId = CalendarSync.getActiveCalendarId();
        if (calId) {
            try {
                localStorage.setItem('teamCalendarActiveId', calId);
            } catch (_) {
                /* ignore */
            }
        }
    }
    const url = '/notes.html?' + params.toString();
    if (options.sameTab || prefersMobileNotesNav()) {
        location.href = url;
        return;
    }
    window.open(url, '_blank', 'noopener');
}

async function reloadNotesCalendar() {
    if (typeof CalendarSync === 'undefined' || !teamSyncEnabled) {
        return;
    }
    const id = CalendarSync.getActiveCalendarId();
    if (!id) {
        return;
    }
    const doc = await CalendarSync.loadCalendar(id);
    applyServerDocument(doc);
    if (!isNotesPage()) {
        refreshNotesPageIfMounted();
    }
    const banner = document.getElementById('notesRemoteBanner');
    if (banner) {
        banner.hidden = true;
    }
    const initErr = document.getElementById('notesInitErrorBanner');
    if (initErr) {
        initErr.hidden = true;
    }
    CalendarSync.state.remoteNewer = false;
    const label = document.getElementById('notesCalendarLabel');
    if (label) {
        label.textContent = appData.calendarName || '';
    }
    setAppStatusMessage(t('syncReload') || 'Reloaded', false);
}

function setClassesPanelSegment(segment, options = {}) {
    const next = segment === 'notes' ? 'notes' : 'info';
    classesPanelSegment = next;
    ensureUiState();
    appData.ui.classesPanelSegment = next;
    saveUiStateToLocalStorage();
    syncClassesPanelSegmentUi();
    if (next === 'notes') {
        mountClassNotesToClassesSegment();
        initClassNotesTab();
        resetClassNotesAddForm();
        renderClassNotesTab();
    } else {
        mountClassForm('tab');
        renderClassList();
        if (options.classId) {
            const cls = appData.classes.find((c) => c.id === options.classId);
            if (cls) {
                populateClassForm(cls);
            }
        } else if (options.newClass) {
            populateClassForm(null, options);
        }
        updateClassEditorEmptyState();
    }
}

function syncClassesPanelSegmentUi() {
    const infoPanel = document.getElementById('classesSegmentInfoPanel');
    const notesPanel = document.getElementById('classesSegmentNotesPanel');
    const btnInfo = document.getElementById('classesSegmentInfo');
    const btnNotes = document.getElementById('classesSegmentNotes');
    const toolbar = document.getElementById('classesInfoToolbar');
    const isInfo = classesPanelSegment !== 'notes';
    if (infoPanel) {
        infoPanel.hidden = !isInfo;
    }
    if (notesPanel) {
        notesPanel.hidden = isInfo;
    }
    if (btnInfo) {
        btnInfo.classList.toggle('is-active', isInfo);
        btnInfo.setAttribute('aria-selected', String(isInfo));
    }
    if (btnNotes) {
        btnNotes.classList.toggle('is-active', !isInfo);
        btnNotes.setAttribute('aria-selected', String(!isInfo));
    }
    if (toolbar) {
        toolbar.hidden = !isInfo;
    }
}

function getClassNotesFilterOptionGroups() {
    const subjects = new Map();
    const grades = new Map();
    const homerooms = new Map();
    const cohortsById = buildCohortsByIdMap();
    const classById = new Map();
    getClassesInDisplayOrder().forEach((classData) => {
        const subject = getClassSubjectForDayNotes(classData) || '';
        const subjectKey = subject || '__no_subject__';
        subjects.set(subjectKey, subject || (currentLanguage === 'ko' ? '(과목 없음)' : '(No subject)'));
        const gradeKey = (classData.grade || '').trim() || LESSON_FILTER_NO_GRADE;
        grades.set(gradeKey, gradeKey === LESSON_FILTER_NO_GRADE
            ? (currentLanguage === 'ko' ? '(학년 없음)' : '(No grade)')
            : classData.grade);
        const homeroom = resolveHomeroomMetaForClass(classData, cohortsById);
        homerooms.set(homeroom.key, homeroom.label);
        classById.set(classData.id, {
            value: classData.id,
            label: classData.name || classData.id,
            searchHay: [classData.name, classData.grade, subject, homeroom.label].join(' ').toLowerCase()
        });
    });
    ensureDayNotesArray();
    (appData.dayNotes || []).forEach((note) => {
        const cid = note && note.classId ? String(note.classId).trim() : '';
        if (!cid || classById.has(cid)) {
            return;
        }
        const meta = resolveDayNoteMeta(cid);
        const subject = meta.subject || '';
        const subjectKey = subject || '__no_subject__';
        subjects.set(subjectKey, subject || (currentLanguage === 'ko' ? '(과목 없음)' : '(No subject)'));
        const gradeKey = LESSON_FILTER_NO_GRADE;
        grades.set(gradeKey, currentLanguage === 'ko' ? '(학년 없음)' : '(No grade)');
        classById.set(cid, {
            value: cid,
            label: meta.className || cid,
            searchHay: [meta.className, meta.subject].join(' ').toLowerCase()
        });
    });
    const classes = [...classById.values()];
    const homeroomEntries = [...homerooms.entries()].map(([value, label]) => ({ value, label }));
    homeroomEntries.sort((a, b) => {
        if (a.value === HOMEROOM_NONE_KEY) {
            return 1;
        }
        if (b.value === HOMEROOM_NONE_KEY) {
            return -1;
        }
        return a.label.localeCompare(b.label, undefined, { sensitivity: 'base' });
    });
    return {
        classes,
        subjects: [...subjects.entries()].map(([value, label]) => ({ value, label })),
        grades: [...grades.entries()].map(([value, label]) => ({ value, label })),
        homerooms: homeroomEntries
    };
}

function getClassNotesCategoryCheckboxState() {
    const state = new Map();
    const mount = document.getElementById('classNotesFilterCategories');
    const inputs = mount
        ? mount.querySelectorAll(`input[${CLASS_NOTES_FILTER_ATTR}="categories"]`)
        : [];
    inputs.forEach((input) => {
        state.set(input.value, input.checked);
    });
    return state;
}

function getClassNotesCategoriesForBaseFilters(filters) {
    if (!filters || !filters.classIds.length) {
        return [];
    }
    const api = getDayNotesApi();
    const normalize = api && api.normalizeCategoryId
        ? (id) => api.normalizeCategoryId(id)
        : (id) => String(id || 'class-notes');
    const notes = filterClassNotesWithSidebarFilters(filters, { omitCategoryFilter: true });
    const catIds = new Set();
    notes.forEach((note) => {
        catIds.add(normalize(note.categoryId));
    });
    return getDayNoteCategoryList()
        .filter((cat) => catIds.has(cat.id))
        .map((cat) => ({ value: cat.id, label: cat.name }));
}

function restoreClassNotesChipFiltersFromState(prev) {
    if (!prev) {
        return;
    }
    const shell = document.getElementById('classNotesShell');
    if (!shell) {
        return;
    }
    if (prev.subjectSet) {
        shell.querySelectorAll(`input[${CLASS_NOTES_FILTER_ATTR}="subjects"]`).forEach((input) => {
            input.checked = prev.subjectSet.has(input.value);
        });
    }
    if (prev.gradeSet) {
        shell.querySelectorAll(`input[${CLASS_NOTES_FILTER_ATTR}="grades"]`).forEach((input) => {
            input.checked = prev.gradeSet.has(input.value);
        });
    }
    if (prev.homeroomSet) {
        shell.querySelectorAll(`input[${CLASS_NOTES_FILTER_ATTR}="homerooms"]`).forEach((input) => {
            input.checked = prev.homeroomSet.has(input.value);
        });
    }
    if (prev.categorySet) {
        shell.querySelectorAll(`input[${CLASS_NOTES_FILTER_ATTR}="categories"]`).forEach((input) => {
            input.checked = prev.categorySet.has(input.value);
        });
    }
}

function ensureClassNotesFilterIncludes(classId) {
    const cid = String(classId || '').trim();
    if (!cid) {
        return;
    }
    const shell = document.getElementById('classNotesShell');
    if (!shell) {
        return;
    }
    let input = shell.querySelector(`input[${CLASS_NOTES_FILTER_ATTR}="classIds"][value="${CSS.escape(cid)}"]`);
    if (!input) {
        renderClassNotesFilterClasses();
        renderClassNotesFilterSubjectsAndGrades();
        input = shell.querySelector(`input[${CLASS_NOTES_FILTER_ATTR}="classIds"][value="${CSS.escape(cid)}"]`);
    }
    if (input) {
        input.checked = true;
    }
}

function getDayNotesDateSpan() {
    ensureDayNotesArray();
    let minDate = '';
    let maxDate = '';
    (appData.dayNotes || []).forEach((note) => {
        const d = note && note.date ? String(note.date).trim() : '';
        if (!d) {
            return;
        }
        if (!minDate || d < minDate) {
            minDate = d;
        }
        if (!maxDate || d > maxDate) {
            maxDate = d;
        }
    });
    return { minDate, maxDate };
}

/** Widen From/To so existing notes are not hidden by stale saved date filters. */
function ensureClassNotesDateRangeCoversExistingNotes() {
    const fromEl = document.getElementById('classNotesFilterFrom');
    const toEl = document.getElementById('classNotesFilterTo');
    const { minDate, maxDate } = getDayNotesDateSpan();
    if (!fromEl || !toEl || !minDate) {
        return;
    }
    if (!fromEl.value || fromEl.value > minDate) {
        fromEl.value = minDate;
    }
    if (!toEl.value || toEl.value < maxDate) {
        toEl.value = maxDate;
    }
}

function widenClassNotesDateRangeForNote(dateStr) {
    const date = String(dateStr || '').trim();
    if (!date) {
        return;
    }
    const fromEl = document.getElementById('classNotesFilterFrom');
    const toEl = document.getElementById('classNotesFilterTo');
    if (fromEl && (!fromEl.value || date < fromEl.value)) {
        fromEl.value = date;
    }
    if (toEl && (!toEl.value || date > toEl.value)) {
        toEl.value = date;
    }
}

function ensureClassNotesFiltersCoverExistingNotes() {
    ensureDayNotesArray();
    const classIds = new Set();
    (appData.dayNotes || []).forEach((note) => {
        const cid = note && note.classId ? String(note.classId).trim() : '';
        if (cid) {
            classIds.add(cid);
        }
    });
    classIds.forEach((cid) => ensureClassNotesFilterIncludes(cid));
}

function buildClassNotesFilterChipHtml(filterKey, options, checkedState) {
    if (!options.length) {
        return '';
    }
    return options.map((opt) => {
        const checked = checkedState && checkedState.has(opt.value)
            ? checkedState.get(opt.value)
            : true;
        const checkedAttr = checked ? ' checked' : '';
        return `
        <label class="checkbox-label lesson-filter-chip">
            <input type="checkbox" ${CLASS_NOTES_FILTER_ATTR}="${filterKey}" value="${escapeAttr(opt.value)}"${checkedAttr}>
            <span>${escapeHtml(opt.label)}</span>
        </label>`;
    }).join('');
}

function renderClassNotesFilterClasses() {
    const body = document.getElementById('classNotesFilterClasses');
    if (!body) {
        return;
    }
    const groups = getClassNotesFilterOptionGroups();
    if (!groups.classes.length) {
        body.innerHTML = `<p class="module-empty-hint">${escapeHtml(t('classNotesNoClassesDefined'))}</p>`;
        return;
    }
    body.innerHTML = groups.classes.map((opt) => `
        <label class="checkbox-label lesson-filter-chip class-notes-class-chip" data-search-hay="${escapeAttr(opt.searchHay)}">
            <input type="checkbox" ${CLASS_NOTES_FILTER_ATTR}="classIds" value="${escapeAttr(opt.value)}" checked>
            <span>${escapeHtml(opt.label)}</span>
        </label>`).join('');
}

function renderClassNotesFilterSubjectsAndGrades() {
    const groups = getClassNotesFilterOptionGroups();
    const subWrap = document.getElementById('classNotesFilterSubjectsWrap');
    const subMount = document.getElementById('classNotesFilterSubjects');
    const gradeWrap = document.getElementById('classNotesFilterGradesWrap');
    const gradeMount = document.getElementById('classNotesFilterGrades');
    const hrWrap = document.getElementById('classNotesFilterHomeroomWrap');
    const hrMount = document.getElementById('classNotesFilterHomeroom');
    if (subMount && subWrap) {
        if (groups.subjects.length) {
            subWrap.hidden = false;
            subMount.innerHTML = buildClassNotesFilterChipHtml('subjects', groups.subjects);
        } else {
            subWrap.hidden = true;
            subMount.innerHTML = '';
        }
    }
    if (gradeMount && gradeWrap) {
        if (groups.grades.length) {
            gradeWrap.hidden = false;
            gradeMount.innerHTML = buildClassNotesFilterChipHtml('grades', groups.grades);
        } else {
            gradeWrap.hidden = true;
            gradeMount.innerHTML = '';
        }
    }
    if (hrMount && hrWrap) {
        if (groups.homerooms.length) {
            hrWrap.hidden = false;
            hrMount.innerHTML = buildClassNotesFilterChipHtml('homerooms', groups.homerooms);
        } else {
            hrWrap.hidden = true;
            hrMount.innerHTML = '';
        }
    }
    renderClassNotesCategoryFilterChips();
}

function renderClassNotesCategoryFilterChips() {
    const catWrap = document.getElementById('classNotesFilterCategoriesWrap');
    const catMount = document.getElementById('classNotesFilterCategories');
    const exportWrap = document.getElementById('classNotesExportCategoriesWrap');
    const exportMount = document.getElementById('classNotesExportCategories');
    const filters = collectClassNotesFilterState();
    const checkedState = getClassNotesCategoryCheckboxState();
    const categories = getClassNotesCategoriesForBaseFilters(filters);
    const chipHtml = categories.length
        ? buildClassNotesFilterChipHtml('categories', categories, checkedState)
        : '';
    const show = categories.length >= 1;
    if (catMount && catWrap) {
        catWrap.hidden = !show;
        catMount.innerHTML = chipHtml;
    }
    if (exportMount && exportWrap) {
        exportWrap.hidden = !show;
        exportMount.innerHTML = chipHtml;
    }
}

function syncClassNotesCategoryChipsFromInput(changedInput) {
    if (!changedInput || changedInput.getAttribute(CLASS_NOTES_FILTER_ATTR) !== 'categories') {
        return;
    }
    const value = changedInput.value;
    const checked = changedInput.checked;
    document.querySelectorAll(
        `input[${CLASS_NOTES_FILTER_ATTR}="categories"][value="${CSS.escape(value)}"]`
    ).forEach((input) => {
        if (input !== changedInput) {
            input.checked = checked;
        }
    });
}

function applyDefaultClassNotesDateRange() {
    const fromEl = document.getElementById('classNotesFilterFrom');
    const toEl = document.getElementById('classNotesFilterTo');
    const { start, end } = getTermDateRangeISO();
    if (fromEl && start) {
        fromEl.value = start;
    }
    if (toEl && end) {
        toEl.value = end;
    }
}

