function parseISODateLocal(dateStr) {
    if (window.CCPUtils && window.CCPUtils.parseISODateLocal) {
        return window.CCPUtils.parseISODateLocal(dateStr);
    }
    if (!dateStr || typeof dateStr !== 'string') {
        return new Date(NaN);
    }
    const parts = dateStr.split('-').map(Number);
    return new Date(parts[0], parts[1] - 1, parts[2]);
}

function maxDate(a, b) {
    return a > b ? a : b;
}

function minDate(a, b) {
    return a < b ? a : b;
}

function enumerateMonthKeysBetween(startDateStr, endDateStr) {
    const keys = [];
    const start = parseISODateLocal(startDateStr);
    const end = parseISODateLocal(endDateStr);
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
        return keys;
    }
    let y = start.getFullYear();
    let mo = start.getMonth();
    const endY = end.getFullYear();
    const endMo = end.getMonth();
    while (y < endY || (y === endY && mo <= endMo)) {
        keys.push(`${y}-${String(mo + 1).padStart(2, '0')}`);
        mo += 1;
        if (mo > 11) {
            mo = 0;
            y += 1;
        }
    }
    return keys;
}

function formatDateForInput(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function computeTermEndDateExactMonths(startDateStr, monthCount) {
    const api = getTermDatesApi();
    if (api) {
        const endD = api.computeTermEndDateExactMonths(startDateStr, monthCount);
        return endD;
    }
    const d = parseISODateLocal(startDateStr);
    if (Number.isNaN(d.getTime())) {
        return null;
    }
    const n = parseInt(monthCount, 10);
    if (Number.isNaN(n) || n < 1) {
        return null;
    }
    const end = new Date(d.getFullYear(), d.getMonth() + n, d.getDate());
    end.setDate(end.getDate() - 1);
    return end;
}

function computeTermEndDateFromStart(startDateStr, monthCount) {
    const d = parseISODateLocal(startDateStr);
    if (Number.isNaN(d.getTime())) {
        return null;
    }
    const n = parseInt(monthCount, 10);
    if (Number.isNaN(n) || n < 1) {
        return null;
    }
    const y = d.getFullYear();
    const m0 = d.getMonth();
    const lastMonthIndex = m0 + n - 1;
    const endY = y + Math.floor(lastMonthIndex / 12);
    const endM = ((lastMonthIndex % 12) + 12) % 12;
    return new Date(endY, endM + 1, 0);
}

function applyClassTermEndUiState() {
    if (!elements.classUseAutoTermEnd || !elements.classEndDate) {
        return;
    }
    const auto = elements.classUseAutoTermEnd.checked;
    elements.classEndDate.readOnly = auto;
    elements.classEndDate.classList.toggle('input-readonly', auto);
    const modeWrap = document.getElementById('classTermEndModeWrap');
    if (modeWrap) {
        modeWrap.hidden = !auto;
    }
}

function refreshBookRowsForTermRange() {
    const start = elements.classStartDate.value;
    const end = elements.classEndDate.value;
    if (!start || !end) {
        return;
    }
    const existing = collectDebateBookPeriodsFromForm().filter(p => p.startDate >= start && p.startDate <= end);
    if (existing.length > 0) {
        renderDebateBookPeriodRows(existing);
    } else {
        const debateApi = getCCPDebatePeriods();
        if (debateApi) {
            renderDebateBookPeriodRows(
                debateApi.suggestPeriodsFromCalendarMonths(start, end, elements.classBook.value || '')
            );
        } else {
            renderDebateBookPeriodRows([]);
        }
    }
    syncCompressionSectionsForMode();
}

function syncClassTermEndAndBooks() {
    if (!elements.classUseAutoTermEnd || !elements.classUseAutoTermEnd.checked) {
        return;
    }
    const start = elements.classStartDate.value;
    const n = parseInt(elements.classTermMonths.value, 10);
    if (!start || Number.isNaN(n) || n < 1) {
        return;
    }
    const modeEl = document.getElementById('classTermEndMode');
    const mode = modeEl && modeEl.value === 'exactMonths' ? 'exactMonths' : 'calendarMonths';
    const endD = mode === 'exactMonths'
        ? computeTermEndDateExactMonths(start, n)
        : computeTermEndDateFromStart(start, n);
    if (endD) {
        elements.classEndDate.value = formatDateForInput(endD);
    }
    refreshBookRowsForTermRange();
}

function applyCalendarTermEndUiState() {
    if (!elements.termUseAutoTermEnd || !elements.termEnd) {
        return;
    }
    const auto = elements.termUseAutoTermEnd.checked;
    elements.termEnd.readOnly = auto;
    elements.termEnd.classList.toggle('input-readonly', auto);
    if (elements.termMonthCount) {
        const wrap = elements.termMonthCount.closest('.toolbar-field');
        if (wrap) {
            wrap.hidden = !auto;
        }
    }
}

function syncCalendarTermEndFromSettings() {
    if (!elements.termUseAutoTermEnd || !elements.termUseAutoTermEnd.checked) {
        return;
    }
    const start = elements.termStart && elements.termStart.value;
    if (!start) {
        return;
    }
    const endD = computeTermEndDateFromStart(start, getTermMonthCount());
    if (endD && elements.termEnd) {
        elements.termEnd.value = formatDateForInput(endD);
        appData.termEnd = elements.termEnd.value;
    }
}

function getClassLevelDisplay(classData) {
    const custom = (classData.levelCustom || '').trim();
    if (custom) {
        return custom;
    }
    const preset = (classData.levelPreset || '').trim();
    if (preset) {
        const def = getSimsonLevelById(preset);
        return def ? def.name : preset;
    }
    return (classData.level || '').trim();
}

function getClassLevelDisplayFromParts(preset, custom) {
    const c = (custom || '').trim();
    if (c) {
        return c;
    }
    const p = (preset || '').trim();
    const def = getSimsonLevelById(p);
    if (def) {
        return def.name;
    }
    return p;
}

function getBookForMonthKey(classData, monthKey) {
    const map = classData.booksByMonth && typeof classData.booksByMonth === 'object'
        ? classData.booksByMonth
        : {};
    const entry = map[monthKey];
    if (entry && String(entry).trim()) {
        return String(entry).trim();
    }
    return (classData.book || '').trim();
}

function getCCPDebatePeriods() {
    return typeof globalThis !== 'undefined' && globalThis.CCPDebatePeriods
        ? globalThis.CCPDebatePeriods
        : null;
}

function getBookForLesson(classData, dateStr, monthKey) {
    const debateApi = getCCPDebatePeriods();
    if (classUsesDebateCompression(classData) && debateApi) {
        return debateApi.getBookForDate(classData, dateStr);
    }
    return getBookForMonthKey(classData, monthKey);
}

function ensureDebatePeriodsOnClass(classData) {
    const debateApi = getCCPDebatePeriods();
    if (!classData || !classUsesDebateCompression(classData) || !debateApi) {
        return [];
    }
    return debateApi.ensureDebateBookPeriodsForClass(classData);
}

function mergePlanToFit(availableSlots, totalLessons, userMerges, mode, startOrder) {
    const normalizedUser = normalizeCompressionMerges(userMerges, totalLessons);
    if (mode !== 'autoWhenNeeded') {
        return normalizedUser;
    }
    if (window.CCPSchedule && window.CCPSchedule.mergePlanToFit) {
        return window.CCPSchedule.mergePlanToFit(
            availableSlots,
            totalLessons,
            userMerges,
            mode,
            startOrder || null
        );
    }
    // Auto: start with no merges; only add merges when there are not enough class
    // meetings in this month for one group per lesson day.
    let merges = [];
    let { groups } = buildLessonGroups(totalLessons, merges);
    if (groups.length <= availableSlots) {
        return merges;
    }
    let guard = 0;
    while (groups.length > availableSlots && guard < SCHEDULE_CONFIG.maxMergeIterations) {
        guard += 1;
        const startOrder = getAutoMergeStartPreferenceOrder(totalLessons);
        const startRank = {};
        startOrder.forEach((s, i) => {
            startRank[s] = i;
        });
        let bestTrial = null;
        let bestCount = groups.length;
        let bestRank = 9999;
        for (const start of startOrder) {
            if (merges.includes(start)) {
                continue;
            }
            const trial = normalizeCompressionMerges([...merges, start], totalLessons);
            const cnt = buildLessonGroups(totalLessons, trial).groups.length;
            const rnk = startRank[start];
            if (cnt < bestCount || (cnt === bestCount && rnk < bestRank)) {
                bestCount = cnt;
                bestTrial = trial;
                bestRank = rnk;
            }
        }
        if (!bestTrial) {
            break;
        }
        merges = bestTrial;
        ({ groups } = buildLessonGroups(totalLessons, merges));
    }
    return merges;
}

function escapeAttr(s) {
    if (window.CCPUtils && window.CCPUtils.escapeAttr) {
        return window.CCPUtils.escapeAttr(s);
    }
    return String(s || '')
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;');
}

function escapeHtml(s) {
    if (window.CCPUtils && window.CCPUtils.escapeHtml) {
        return window.CCPUtils.escapeHtml(s);
    }
    return escapeAttr(s).replace(/>/g, '&gt;');
}

function formatBooksByMonthSummary(classData) {
    if (classUsesDebateCompression(classData)) {
        ensureDebatePeriodsOnClass(classData);
        const debateApi = getCCPDebatePeriods();
        if (debateApi) {
            return debateApi.formatDebatePeriodsSummary(classData);
        }
    }
    const m = classData.booksByMonth && typeof classData.booksByMonth === 'object'
        ? classData.booksByMonth
        : {};
    const keys = Object.keys(m).sort();
    if (keys.length === 0) {
        return '—';
    }
    return keys.map(k => `${k}: ${m[k]}`).join('; ');
}

function getCompressionModeFromForm() {
    return getCompressionModeFromSurface('classForm');
}

function getCompressionModeFromSurface(surface) {
    const sid = surface || getScheduleAdjustmentSurface();
    const map = SCHEDULE_ADJ_SURFACE[sid];
    if (!map) {
        return 'autoWhenNeeded';
    }
    const r = document.querySelector(`input[name="${map.compressionModeName}"]:checked`);
    if (!r) {
        return 'autoWhenNeeded';
    }
    if (r.value === 'manual') {
        return 'manual';
    }
    if (r.value === 'manualPerMonth') {
        return 'manualPerMonth';
    }
    return 'autoWhenNeeded';
}

/** Debate: form radios. Sequential/WR+SP: manual only (same fields as debate manual global). */
function getCompressionModeForSaveAndSchedule({ isCustomSchedule, isDebateSchedule, surface }) {
    if (isCustomSchedule) {
        return 'sequentialTerm';
    }
    if (isDebateSchedule) {
        return getCompressionModeFromSurface(surface);
    }
    return 'manual';
}

function collectClassCompressionForSave({ isDebateSchedule, isCustomSchedule, surface }) {
    const sid = surface || getScheduleAdjustmentSurface();
    return {
        compressionMode: getCompressionModeForSaveAndSchedule({ isCustomSchedule, isDebateSchedule, surface: sid }),
        compressionMerges: isCustomSchedule ? [] : getSelectedCompressionMerges(sid),
        skippedLessons: isCustomSchedule ? [] : collectSkippedLessonsFromForm(sid),
        compressionMergesByPeriod: isDebateSchedule ? collectCompressionMergesByPeriodFromForm(sid) : {}
    };
}

function collectDebateBookPeriodsFromForm() {
    const periods = [];
    if (!elements.debateBookPeriodRows) {
        return periods;
    }
    elements.debateBookPeriodRows.querySelectorAll('.debate-book-period-row').forEach(row => {
        const dateIn = row.querySelector('input.book-period-start');
        const bookIn = row.querySelector('input.debate-book-period-title');
        const idIn = row.querySelector('input.book-period-id');
        if (!dateIn || !bookIn) {
            return;
        }
        const startDate = (dateIn.value || '').trim();
        if (!startDate) {
            return;
        }
        periods.push({
            id: (idIn && idIn.value) ? idIn.value : '',
            startDate,
            book: (bookIn.value || '').trim()
        });
    });
    const draft = {
        startDate: elements.classStartDate ? elements.classStartDate.value : '',
        endDate: elements.classEndDate ? elements.classEndDate.value : '',
        book: elements.classBook ? elements.classBook.value : '',
        debateBookPeriods: periods
    };
    const debateApi = getCCPDebatePeriods();
    if (debateApi) {
        return debateApi.normalizeDebateBookPeriods(draft);
    }
    return periods;
}

/** @deprecated Legacy map; debate classes use debateBookPeriods. */
function collectBooksByMonthFromForm() {
    const map = {};
    collectDebateBookPeriodsFromForm().forEach(p => {
        if (p.startDate) {
            map[p.startDate.slice(0, 7)] = p.book;
        }
    });
    return map;
}

function addBookPeriodRow(period) {
    const startDate = (period && period.startDate) || '';
    const title = (period && period.book) || '';
    const periodId = (period && period.id) || '';
    const row = document.createElement('div');
    row.className = 'debate-book-period-row';
    row.innerHTML = `
        <input type="hidden" class="book-period-id" value="${escapeAttr(periodId)}">
        <input type="date" class="book-period-start" value="${escapeAttr(startDate)}">
        <input type="text" class="debate-book-period-title" placeholder="" value="${escapeAttr(title)}">
        <button type="button" class="btn btn-outline btn-small debate-book-period-remove">${t('delete')}</button>
    `;
    row.querySelector('.debate-book-period-title').placeholder = t('bookPlaceholder');
    row.querySelector('.debate-book-period-remove').addEventListener('click', () => {
        row.remove();
        if (!elements.debateBookPeriodRows.querySelector('.debate-book-period-row')) {
            addBookPeriodRow(null);
        }
        syncCompressionSectionsForMode();
    });
    row.querySelector('.book-period-start').addEventListener('change', () => {
        syncCompressionSectionsForMode();
    });
    elements.debateBookPeriodRows.appendChild(row);
}

function addBookMonthRow(monthKey, title) {
    const startDate = monthKey && /^\d{4}-\d{2}$/.test(monthKey) ? `${monthKey}-01` : monthKey;
    addBookPeriodRow({ startDate, book: title });
}

function renderDebateBookPeriodRows(periods) {
    elements.debateBookPeriodRows.innerHTML = '';
    const list = Array.isArray(periods) ? periods : [];
    if (list.length === 0) {
        addBookPeriodRow(null);
        return;
    }
    list.forEach(p => addBookPeriodRow(p));
}

function renderBooksByMonthRows(booksByMonthOrPeriods) {
    if (Array.isArray(booksByMonthOrPeriods)) {
        renderDebateBookPeriodRows(booksByMonthOrPeriods);
        return;
    }
    const map = booksByMonthOrPeriods && typeof booksByMonthOrPeriods === 'object' ? booksByMonthOrPeriods : {};
    const entries = Object.entries(map).sort((a, b) => a[0].localeCompare(b[0]));
    const periods = entries.map(([k, v]) => ({
        startDate: /^\d{4}-\d{2}$/.test(k) ? `${k}-01` : k,
        book: v
    }));
    renderDebateBookPeriodRows(periods);
}

function fillBooksFromTermDefaultBook() {
    const defaultBook = (elements.classBook.value || '').trim();
    if (!defaultBook) {
        return;
    }
    const start = elements.classStartDate.value;
    const end = elements.classEndDate.value;
    if (!start || !end) {
        return;
    }
    elements.debateBookPeriodRows.innerHTML = '';
    const debateApi = getCCPDebatePeriods();
    const suggested = debateApi
        ? debateApi.suggestPeriodsFromCalendarMonths(start, end, defaultBook)
        : enumerateMonthKeysBetween(start, end).map(k => ({
            startDate: `${k}-01`,
            book: defaultBook
        }));
    suggested.forEach(p => addBookPeriodRow(p));
    syncCompressionSectionsForMode();
}

function renderCompressionByPeriodRows(periods, surface) {
    const sid = surface || getScheduleAdjustmentSurface();
    const container = scheduleAdjEl(sid, 'compressionByMonthRows');
    if (!container) {
        return;
    }
    const list = Array.isArray(periods) ? periods : [];
    const classId = sid === 'syllabus'
        ? ((getSelectedSyllabusClass() && getSelectedSyllabusClass().id) || '')
        : (elements.classId ? elements.classId.value : '');
    const existingClass = classId ? appData.classes.find(c => c.id === classId) : null;
    const mergeMap = existingClass && existingClass.compressionMergesByPeriod
        ? existingClass.compressionMergesByPeriod
        : {};
    const totalLessons = getTotalLessonsValue(sid);
    container.innerHTML = '';

    list.forEach(period => {
        if (!period || !period.id || !period.startDate) {
            return;
        }
        const block = document.createElement('div');
        block.className = 'compression-period-block';
        block.dataset.periodId = period.id;
        const heading = document.createElement('p');
        heading.className = 'compression-period-label';
        const bookLabel = period.book ? ` · ${period.book}` : '';
        heading.textContent = `${period.startDate}${bookLabel}`;
        block.appendChild(heading);

        const checks = document.createElement('div');
        checks.className = 'compression-period-checkboxes';
        const selected = normalizeCompressionMerges(mergeMap[period.id] || [], totalLessons);
        for (let i = 1; i < totalLessons; i++) {
            const label = document.createElement('label');
            label.className = 'checkbox-label';
            const input = document.createElement('input');
            input.type = 'checkbox';
            input.dataset.periodId = period.id;
            input.dataset.mergeStart = String(i);
            input.checked = selected.includes(i);
            input.addEventListener('change', () => {
                updateCompressionCheckboxStates(sid);
                if (sid === 'syllabus') {
                    refreshSyllabusScheduleAdjustmentUi(getSelectedSyllabusClass());
                }
            });
            const span = document.createElement('span');
            span.textContent = formatMergeLabel(i, i + 1);
            label.appendChild(input);
            label.appendChild(span);
            checks.appendChild(label);
        }
        block.appendChild(checks);
        container.appendChild(block);
    });
    updateCompressionCheckboxStates(sid);
}

function collectCompressionMergesByPeriodFromForm(surface) {
    const map = {};
    const sid = surface || getScheduleAdjustmentSurface();
    const container = scheduleAdjEl(sid, 'compressionByMonthRows');
    if (!container) {
        return map;
    }
    const totalLessons = getTotalLessonsValue(sid);
    container.querySelectorAll('.compression-period-block').forEach(block => {
        const periodId = block.dataset.periodId;
        if (!periodId) {
            return;
        }
        const merges = [];
        block.querySelectorAll('input[type="checkbox"]:checked').forEach(cb => {
            const start = parseInt(cb.dataset.mergeStart, 10);
            if (Number.isInteger(start)) {
                merges.push(start);
            }
        });
        const normalized = normalizeCompressionMerges(merges, totalLessons);
        if (normalized.length) {
            map[periodId] = normalized;
        }
    });
    return map;
}

// ============================================
// App shell: templates, tabs, form mounts
// ============================================
const APP_HOST_TEACHING = 'teaching';
const APP_HOST_SETUP = 'setup';
const APP_SHARED_TAB_IDS = ['calendar', 'classes'];
const APP_TEACHING_ONLY_TAB_IDS = [
    'homework',
    'notes',
    'timetable',
    'command-center',
    'students',
    'attendance',
    'ledger',
    'homework-tracking',
    'points',
    'tests'
];
const APP_SETUP_ONLY_TAB_IDS = ['cohorts', 'setup-hub', 'teachers', 'curriculum', 'syllabus', 'events', 'data'];
/** Setup subtabs that require head-teacher / manage_calendar_access (cohorts, setup hub & teachers only). */
const APP_SETUP_ADMIN_TAB_IDS = ['cohorts', 'setup-hub', 'teachers'];
const APP_TEACHING_TAB_IDS = [...APP_SHARED_TAB_IDS, ...APP_TEACHING_ONLY_TAB_IDS];
const APP_SETUP_TAB_IDS = [...APP_SHARED_TAB_IDS, ...APP_SETUP_ONLY_TAB_IDS];
const APP_TAB_IDS = [...APP_SHARED_TAB_IDS, ...APP_TEACHING_ONLY_TAB_IDS, ...APP_SETUP_ONLY_TAB_IDS];

const APP_ZONE_SCHEDULE = 'schedule';
const APP_ZONE_CLASSES = 'classes';
const APP_ZONE_SETUP_HUB = 'setup-hub';
const APP_ZONE_CLASSROOM = 'classroom';
const APP_ZONE_MORE = 'more';
const APP_ZONE_IDS = [APP_ZONE_SCHEDULE, APP_ZONE_CLASSES, APP_ZONE_SETUP_HUB, APP_ZONE_CLASSROOM, APP_ZONE_MORE];

const ZONE_SEGMENT_TO_TAB = {
    schedule: { calendar: 'calendar', homework: 'homework', timetable: 'timetable' },
    classes: {
        classes: 'classes',
        cohorts: 'cohorts',
        events: 'events',
        teachers: 'teachers',
        curriculum: 'curriculum',
        syllabus: 'syllabus'
    },
    'setup-hub': { 'setup-hub': 'setup-hub' },
    classroom: {
        students: 'students',
        attendance: 'attendance',
        ledger: 'ledger',
        homework: 'homework-tracking',
        points: 'points',
        tests: 'tests',
        notes: 'notes'
    },
    more: { data: 'data' }
};

const DEFAULT_ZONE_ORDER = [...APP_ZONE_IDS];
const DEFAULT_SEGMENT_ORDER = Object.fromEntries(
    Object.entries(ZONE_SEGMENT_TO_TAB).map(([zoneId, segments]) => [zoneId, Object.keys(segments)])
);

const NAV_ARCHIVED_SEGMENT_IDS = new Set(['command-center']);

function normalizeNavZoneOrder(order) {
    if (typeof CCPZoneNavReorder !== 'undefined' && CCPZoneNavReorder.normalizeZoneOrder) {
        return CCPZoneNavReorder.normalizeZoneOrder(order, DEFAULT_ZONE_ORDER);
    }
    return DEFAULT_ZONE_ORDER.slice();
}

function normalizeNavSegmentOrder(zoneId, order) {
    const defaults = DEFAULT_SEGMENT_ORDER[zoneId] || [];
    if (typeof CCPZoneNavReorder !== 'undefined' && CCPZoneNavReorder.normalizeSegmentOrder) {
        return CCPZoneNavReorder.normalizeSegmentOrder(zoneId, order, defaults);
    }
    return defaults.slice();
}

function getStoredNavZoneOrder() {
    ensureUiState();
    return normalizeNavZoneOrder(appData.ui.navZoneOrder);
}

function getStoredNavSegmentOrder(zoneId) {
    ensureUiState();
    const stored = appData.ui.navSegmentOrder && typeof appData.ui.navSegmentOrder === 'object'
        ? appData.ui.navSegmentOrder[zoneId]
        : null;
    return normalizeNavSegmentOrder(zoneId, stored);
}

function setStoredNavZoneOrder(order) {
    ensureUiState();
    appData.ui.navZoneOrder = normalizeNavZoneOrder(order);
}

function setStoredNavSegmentOrder(zoneId, order) {
    ensureUiState();
    if (!appData.ui.navSegmentOrder || typeof appData.ui.navSegmentOrder !== 'object') {
        appData.ui.navSegmentOrder = {};
    }
    appData.ui.navSegmentOrder[zoneId] = normalizeNavSegmentOrder(zoneId, order);
}

function isNavSegmentVisibleInDom(zoneId, segmentId) {
    if (NAV_ARCHIVED_SEGMENT_IDS.has(segmentId)) {
        return false;
    }
    const panel = document.querySelector(`.app-zone-segment-panel[data-zone="${zoneId}"]`);
    if (!panel) {
        return true;
    }
    const btn = panel.querySelector(`.app-zone-segment-btn[data-segment="${segmentId}"]`);
    if (!btn) {
        return false;
    }
    return !btn.hidden && !btn.disabled && btn.getAttribute('aria-disabled') !== 'true';
}

function getOrderedSegmentsForZone(zoneId) {
    const order = getStoredNavSegmentOrder(zoneId);
    return order.filter((segmentId) => {
        if (!ZONE_SEGMENT_TO_TAB[zoneId] || !ZONE_SEGMENT_TO_TAB[zoneId][segmentId]) {
            return false;
        }
        if (NAV_ARCHIVED_SEGMENT_IDS.has(segmentId)) {
            return false;
        }
        if (!canAccessZoneSegment(zoneId, segmentId)) {
            return false;
        }
        if (typeof document !== 'undefined' && document.querySelector) {
            return isNavSegmentVisibleInDom(zoneId, segmentId);
        }
        return true;
    });
}

function applyZoneNavOrderFromUi() {
    if (typeof CCPZoneNavReorder !== 'undefined' && CCPZoneNavReorder.applyOrder) {
        CCPZoneNavReorder.applyOrder();
    }
}

function getZoneNavReorderHooks() {
    return {
        t,
        getZoneOrder: getStoredNavZoneOrder,
        getSegmentOrder: getStoredNavSegmentOrder,
        setZoneOrder: setStoredNavZoneOrder,
        setSegmentOrder: setStoredNavSegmentOrder,
        saveUiState: saveUiStateToLocalStorage,
        showSavedToast() {
            const msg = t('navReorderSaved');
            if (msg) {
                showSyncToast(msg, false);
            }
        },
        onOrderApplied() {
            syncAllZoneNavScrollAffordances();
        }
    };
}

function syncZoneNavScrollAffordance(scrollEl) {
    if (!scrollEl) {
        return;
    }
    const overflow = scrollEl.scrollWidth > scrollEl.clientWidth + 1;
    if (overflow) {
        scrollEl.dataset.scrollable = '1';
    } else {
        delete scrollEl.dataset.scrollable;
    }
    if (scrollEl.scrollLeft <= 1) {
        scrollEl.dataset.scrollStart = '1';
    } else {
        delete scrollEl.dataset.scrollStart;
    }
    if (scrollEl.scrollLeft + scrollEl.clientWidth >= scrollEl.scrollWidth - 1) {
        scrollEl.dataset.scrollEnd = '1';
    } else {
        delete scrollEl.dataset.scrollEnd;
    }
}

function syncAllZoneNavScrollAffordances() {
    if (isNotesPage()) {
        return;
    }
    const zoneNav = document.getElementById('appZoneNav');
    if (zoneNav) {
        syncZoneNavScrollAffordance(zoneNav);
    }
    document.querySelectorAll('.app-zone-segment-panel:not([hidden])').forEach((panel) => {
        syncZoneNavScrollAffordance(panel);
    });
}

function scrollActiveZoneNavIntoView() {
    if (isNotesPage()) {
        return;
    }
    const activeSegment = document.querySelector('.app-zone-segment-panel:not([hidden]) .app-zone-segment-btn.is-active');
    if (activeSegment) {
        activeSegment.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
        return;
    }
    const activeZone = document.querySelector('.app-zone-btn.is-active');
    if (activeZone) {
        activeZone.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
    }
}

let zoneNavScrollObserverBound = false;
let zoneNavScrollListenersBound = false;

function bindZoneNavScrollListeners() {
    if (zoneNavScrollListenersBound || isNotesPage()) {
        return;
    }
    zoneNavScrollListenersBound = true;
    const onScroll = (e) => {
        syncZoneNavScrollAffordance(e.currentTarget);
    };
    const zoneNav = document.getElementById('appZoneNav');
    if (zoneNav) {
        zoneNav.addEventListener('scroll', onScroll, { passive: true });
    }
    document.querySelectorAll('.app-zone-segment-panel').forEach((panel) => {
        panel.addEventListener('scroll', onScroll, { passive: true });
    });
}

function bindZoneNavScrollObserver() {
    if (zoneNavScrollObserverBound || typeof ResizeObserver === 'undefined') {
        return;
    }
    const cluster = document.getElementById('appZoneNavCluster');
    if (!cluster) {
        return;
    }
    zoneNavScrollObserverBound = true;
    const observer = new ResizeObserver(() => {
        scheduleAppTabNavShellWidthSync();
    });
    observer.observe(cluster);
}

/** Map removed zones (content, journal) and relocated segments for bookmarks and saved UI state. */
function normalizeLegacyZoneAndSegment(zoneId, segmentId) {
    let zone = typeof zoneId === 'string' ? zoneId : '';
    let segment = typeof segmentId === 'string' ? segmentId : '';
    if (zone === 'content') {
        zone = APP_ZONE_CLASSES;
        if (segment === 'homework') {
            zone = APP_ZONE_SCHEDULE;
        }
    } else if (zone === 'journal') {
        zone = APP_ZONE_CLASSROOM;
        if (!segment) {
            segment = 'notes';
        }
    }
    if (segment === 'events' && (zone === APP_ZONE_SCHEDULE || zone === APP_ZONE_MORE)) {
        zone = APP_ZONE_CLASSES;
    }
    if (segment === 'teachers' && zone === APP_ZONE_MORE) {
        zone = APP_ZONE_CLASSES;
    }
    if (segment === 'setup-hub' && zone === APP_ZONE_CLASSES) {
        zone = APP_ZONE_SETUP_HUB;
    }
    if (segment === 'command-center') {
        zone = APP_ZONE_SCHEDULE;
        segment = 'timetable';
    }
    return { zone, segment };
}

const TAB_TO_ZONE_SEGMENT = (() => {
    const map = {};
    Object.keys(ZONE_SEGMENT_TO_TAB).forEach((zone) => {
        Object.entries(ZONE_SEGMENT_TO_TAB[zone]).forEach(([segment, tabId]) => {
            map[tabId] = { zone, segment };
        });
    });
    return map;
})();

const LEGACY_TAB_ZONE_REDIRECT = {
    calendar: { zone: APP_ZONE_SCHEDULE, segment: 'calendar' },
    timetable: { zone: APP_ZONE_SCHEDULE, segment: 'timetable' },
    classes: { zone: APP_ZONE_CLASSES, segment: 'classes' },
    cohorts: { zone: APP_ZONE_CLASSES, segment: 'cohorts' },
    'setup-hub': { zone: APP_ZONE_SETUP_HUB, segment: 'setup-hub' },
    homework: { zone: APP_ZONE_SCHEDULE, segment: 'homework' },
    'command-center': { zone: APP_ZONE_SCHEDULE, segment: 'timetable' },
    notes: { zone: APP_ZONE_CLASSROOM, segment: 'notes' },
    students: { zone: APP_ZONE_CLASSROOM, segment: 'students' },
    attendance: { zone: APP_ZONE_CLASSROOM, segment: 'attendance' },
    ledger: { zone: APP_ZONE_CLASSROOM, segment: 'ledger' },
    'homework-tracking': { zone: APP_ZONE_CLASSROOM, segment: 'homework' },
    points: { zone: APP_ZONE_CLASSROOM, segment: 'points' },
    tests: { zone: APP_ZONE_CLASSROOM, segment: 'tests' },
    curriculum: { zone: APP_ZONE_CLASSES, segment: 'curriculum' },
    syllabus: { zone: APP_ZONE_CLASSES, segment: 'syllabus' },
    events: { zone: APP_ZONE_CLASSES, segment: 'events' },
    teachers: { zone: APP_ZONE_CLASSES, segment: 'teachers' },
    data: { zone: APP_ZONE_MORE, segment: 'data' }
};

function getZoneInfoForTab(tabId) {
    return TAB_TO_ZONE_SEGMENT[tabId] || LEGACY_TAB_ZONE_REDIRECT[tabId] || { zone: APP_ZONE_SCHEDULE, segment: 'calendar' };
}

function getDefaultSegmentForZone(zoneId) {
    const ordered = getOrderedSegmentsForZone(zoneId);
    if (ordered.length) {
        return ordered[0];
    }
    const segments = ZONE_SEGMENT_TO_TAB[zoneId];
    if (!segments) {
        return 'calendar';
    }
    const keys = Object.keys(segments).filter((id) => !NAV_ARCHIVED_SEGMENT_IDS.has(id));
    return keys[0] || 'calendar';
}

function getTabIdForZoneSegment(zoneId, segmentId) {
    const segments = ZONE_SEGMENT_TO_TAB[zoneId];
    if (!segments) {
        return 'calendar';
    }
    if (segmentId && segments[segmentId]) {
        return segments[segmentId];
    }
    return segments[getDefaultSegmentForZone(zoneId)];
}

function canAccessZone(zoneId) {
    if (zoneId === APP_ZONE_MORE) {
        return canAccessSetupHost();
    }
    if (zoneId === APP_ZONE_SETUP_HUB) {
        return canAccessTeachersTab();
    }
    if (zoneId === APP_ZONE_CLASSES || zoneId === APP_ZONE_SCHEDULE || zoneId === APP_ZONE_CLASSROOM) {
        return true;
    }
    return canAccessSetupHost();
}

function canAccessZoneSegment(zoneId, segmentId) {
    if (segmentId === 'cohorts' || segmentId === 'teachers' || segmentId === 'setup-hub') {
        return canAccessTeachersTab();
    }
    if (segmentId === 'events' || segmentId === 'data') {
        return canAccessSetupHost();
    }
    return true;
}

function syncZoneNavFromTab(tabId) {
    const { zone, segment } = getZoneInfoForTab(tabId);
    document.body.dataset.activeZone = zone;
    document.body.dataset.activeSegment = segment;

    syncZoneNavPermissions();

    document.querySelectorAll('.app-zone-btn').forEach((btn) => {
        const z = btn.dataset.zone;
        const active = z === zone;
        btn.classList.toggle('is-active', active);
        btn.setAttribute('aria-selected', String(active));
    });

    document.querySelectorAll('.app-zone-segment-panel').forEach((panel) => {
        const panelZone = panel.dataset.zone;
        const show = panelZone === zone;
        panel.hidden = !show;
        panel.classList.toggle('is-active', show);
    });

    const activePanel = document.querySelector(`.app-zone-segment-panel[data-zone="${zone}"]`);
    if (activePanel) {
        activePanel.querySelectorAll('.app-zone-segment-btn').forEach((btn) => {
            const seg = btn.dataset.segment;
            const active = seg === segment;
            btn.classList.toggle('is-active', active);
            btn.setAttribute('aria-selected', String(active));
        });
    }

    syncAllZoneNavScrollAffordances();
    scrollActiveZoneNavIntoView();

    updateContentPipelineStepper(tabId);
    updateContentExpandChrome();
    syncContentExpandToggleVisibility(tabId);
}

function syncZoneNavPermissions() {
    const cohortsSeg = document.querySelector('.app-zone-segment-btn[data-segment="cohorts"]');
    if (cohortsSeg) {
        cohortsSeg.hidden = !canAccessTeachersTab();
    }
    const setupHubZoneBtn = document.getElementById('zoneBtn-setup-hub');
    if (setupHubZoneBtn) {
        setupHubZoneBtn.hidden = !canAccessTeachersTab();
    }
    const commandCenterSeg = document.querySelector('.app-zone-segment-btn[data-segment="command-center"]');
    if (commandCenterSeg) {
        commandCenterSeg.hidden = true;
    }
    const classesPanel = document.getElementById('zoneSegments-classes');
    if (classesPanel) {
        classesPanel.querySelectorAll('.app-zone-segment-btn[data-segment="teachers"]').forEach((el) => {
            el.hidden = true;
        });
        classesPanel.querySelectorAll('.app-zone-segment-btn[data-segment="events"]').forEach((el) => {
            el.hidden = !canAccessSetupHost();
        });
    }
    const morePanel = document.getElementById('zoneSegments-more');
    if (morePanel) {
        morePanel.querySelectorAll('.app-zone-segment-btn[data-segment="data"]').forEach((el) => {
            el.hidden = !canAccessSetupHost();
        });
    }
    const adminAcct = document.getElementById('teamAdminLink');
    const showAdmin = typeof TeamAuth !== 'undefined' && TeamAuth.canAccessAdmin && TeamAuth.canAccessAdmin();
    if (adminAcct) {
        adminAcct.hidden = !showAdmin;
    }
    applyZoneNavOrderFromUi();
}

function navigateToZone(zoneId, segmentId, options = {}) {
    const normalized = normalizeLegacyZoneAndSegment(zoneId, segmentId);
    zoneId = normalized.zone;
    segmentId = normalized.segment;
    if (!APP_ZONE_IDS.includes(zoneId)) {
        zoneId = APP_ZONE_SCHEDULE;
    }
    if (!canAccessZone(zoneId)) {
        navigateToZone(APP_ZONE_SCHEDULE, 'calendar', options);
        return;
    }
    let segment = segmentId || getDefaultSegmentForZone(zoneId);
    if (!canAccessZoneSegment(zoneId, segment)) {
        segment = getDefaultSegmentForZone(zoneId);
    }
    const tabId = getTabIdForZoneSegment(zoneId, segment);
    ensureUiState();
    appData.ui.activeZone = zoneId;
    appData.ui.activeSegment = segment;
    saveUiStateToLocalStorage();
    navigateToTab(tabId, options);
}

function resolveZoneFromUrl() {
    try {
        const params = new URLSearchParams(location.search);
        const zone = params.get('zone');
        const segment = params.get('segment');
        const legacyTab = params.get('tab');
        if (params.get('contentExpanded') === '1') {
            document.documentElement.setAttribute('data-content-expanded', '1');
        }
        if (zone) {
            const opts = {};
            if (params.get('classId')) {
                opts.classId = params.get('classId');
            }
            if (params.get('book')) {
                opts.curriculumId = params.get('book');
            }
            const migrated = normalizeLegacyZoneAndSegment(zone, segment || '');
            let resolvedZone = migrated.zone;
            let resolvedSegment = migrated.segment || getDefaultSegmentForZone(resolvedZone);
            if (!APP_ZONE_IDS.includes(resolvedZone)) {
                resolvedZone = APP_ZONE_SCHEDULE;
                resolvedSegment = 'calendar';
            }
            return { zone: resolvedZone, segment: resolvedSegment, options: opts };
        }
        if (legacyTab && LEGACY_TAB_ZONE_REDIRECT[legacyTab]) {
            const info = LEGACY_TAB_ZONE_REDIRECT[legacyTab];
            const opts = {};
            if (params.get('classId')) {
                opts.classId = params.get('classId');
            }
            if (params.get('book')) {
                opts.curriculumId = params.get('book');
            }
            return { ...info, options: opts };
        }
    } catch (_) {
        /* ignore */
    }
    return null;
}

function getHostForTab(tabId) {
    if (APP_SETUP_ONLY_TAB_IDS.includes(tabId)) {
        return APP_HOST_SETUP;
    }
    if (APP_TEACHING_ONLY_TAB_IDS.includes(tabId)) {
        return APP_HOST_TEACHING;
    }
    if (APP_SHARED_TAB_IDS.includes(tabId)) {
        const ui = appData.ui;
        const stored = ui && ui.activeHostTab;
        if (stored === APP_HOST_SETUP || stored === APP_HOST_TEACHING) {
            return stored;
        }
        return APP_HOST_TEACHING;
    }
    return APP_HOST_TEACHING;
}

function getSubTabButton(tabId, hostId) {
    if (tabId === 'calendar') {
        return document.getElementById(
            hostId === APP_HOST_SETUP ? 'tabBtn-calendar-setup' : 'tabBtn-calendar-teaching'
        );
    }
    if (tabId === 'classes') {
        return document.getElementById(
            hostId === APP_HOST_SETUP ? 'tabBtn-classes-setup' : 'tabBtn-classes'
        );
    }
    return document.getElementById(`tabBtn-${tabId}`);
}

function getActiveHostTab() {
    ensureUiState();
    const stored = appData.ui.activeHostTab;
    if (stored === APP_HOST_SETUP || stored === APP_HOST_TEACHING) {
        return stored;
    }
    return getHostForTab(getActiveTab());
}

function defaultTabForHost(hostId) {
    return hostId === APP_HOST_SETUP ? defaultLastSetupTabId() : 'calendar';
}

/** When switching Teaching/Setup: keep calendar/classes; else open that host's last sub-tab. */
function resolveSubTabForHostSwitch(hostId) {
    ensureUiState();
    const currentTab = appData.ui.activeTab || getActiveTab();
    if (currentTab && APP_SHARED_TAB_IDS.includes(currentTab)) {
        if (hostId === APP_HOST_SETUP && APP_SETUP_TAB_IDS.includes(currentTab)) {
            return currentTab;
        }
        if (hostId === APP_HOST_TEACHING && APP_TEACHING_TAB_IDS.includes(currentTab)) {
            return currentTab;
        }
    }
    if (hostId === APP_HOST_SETUP) {
        const last = appData.ui.lastSetupTab;
        if (typeof last === 'string' && APP_SETUP_TAB_IDS.includes(last)) {
            return last;
        }
        return defaultTabForHost(APP_HOST_SETUP);
    }
    const last = appData.ui.lastTeachingTab;
    if (typeof last === 'string' && APP_TEACHING_TAB_IDS.includes(last)) {
        return last;
    }
    return defaultTabForHost(APP_HOST_TEACHING);
}

let appTabNavShellWidthTimer = 0;

/** Clear legacy inline tab-nav width (layout is CSS: context strip + scrollable sub-tabs + fixed hosts). */
function syncAppTabNavShellWidth() {
    const cluster = document.getElementById('appZoneNavCluster') || document.getElementById('appTabNavCluster');
    const nav = document.getElementById('appZoneSegmentNav') || document.getElementById('appTabNav');
    if (!cluster || isNotesPage()) {
        return;
    }
    cluster.style.removeProperty('--app-tab-nav-min-width');
    if (nav) {
        nav.style.removeProperty('--app-tab-nav-min-width');
    }
}

function scheduleAppTabNavShellWidthSync() {
    clearTimeout(appTabNavShellWidthTimer);
    appTabNavShellWidthTimer = setTimeout(() => {
        requestAnimationFrame(() => {
            syncAppTabNavShellWidth();
            const tabId = typeof getActiveTab === 'function' ? getActiveTab() : '';
            if (tabId) {
                syncZoneNavFromTab(tabId);
            } else {
                syncZoneNavPermissions();
                syncAllZoneNavScrollAffordances();
            }
        });
    }, 80);
}

function syncHostSubTabNav(hostId, subTabId) {
    document.body.dataset.activeHostTab = hostId;
    syncZoneNavFromTab(subTabId);
    scheduleAppTabNavShellWidthSync();
}

function canAccessSetupHost() {
    return typeof TeamAuth !== 'undefined' && TeamAuth.getUser();
}

function navigateToHost(hostId, options = {}) {
    if (hostId !== APP_HOST_SETUP && hostId !== APP_HOST_TEACHING) {
        hostId = APP_HOST_TEACHING;
    }
    if (hostId === APP_HOST_SETUP && !canAccessSetupHost()) {
        navigateToTab('calendar', { host: APP_HOST_TEACHING });
        return;
    }
    if (hostId === APP_HOST_SETUP && isViewportPhone()) {
        navigateToTab('calendar', { host: APP_HOST_TEACHING });
        return;
    }
    ensureUiState();
    let subTab = options.subTab || '';
    if (!subTab || !APP_TAB_IDS.includes(subTab)) {
        subTab = resolveSubTabForHostSwitch(hostId);
    }
    if (hostId === APP_HOST_SETUP && !APP_SETUP_TAB_IDS.includes(subTab)) {
        subTab = defaultTabForHost(APP_HOST_SETUP);
    }
    if (hostId === APP_HOST_TEACHING && !APP_TEACHING_TAB_IDS.includes(subTab)) {
        subTab = defaultTabForHost(APP_HOST_TEACHING);
    }
    navigateToTab(subTab, { ...options, host: hostId });
}

