const SETUP_GUIDE_BANNER_TEXT_FALLBACK =
    'Create student cohorts first on the Setup tab → Cohorts, then assign classes and teachers.';
const SETUP_GUIDE_BANNER_ACTION_FALLBACK = 'Create cohorts';
const SETUP_GUIDE_BANNER_DISMISS_FALLBACK = 'Dismiss';

function setSetupGuideBannerVisible(banner, visible) {
    if (!banner) {
        return;
    }
    banner.hidden = !visible;
    banner.classList.toggle('is-hidden', !visible);
}

function shouldShowSetupGuideBanner() {
    try {
        if (shouldDeferSetupGuideBanner()) {
            return false;
        }
        if (!canAccessTeachersTab()) {
            return false;
        }
        ensureUiState();
        if (appData.ui.setupGuideBannerDismissed) {
            return false;
        }
        const cohorts = (appData.cohorts || []).filter((c) => c && c.id);
        if (!cohorts.length) {
            return true;
        }
        if (typeof CCPCohortManagement === 'undefined' || !CCPCohortManagement.computeCohortStatus) {
            return false;
        }
        return cohorts.some((c) => CCPCohortManagement.computeCohortStatus(c, appData) !== 'ready');
    } catch (_err) {
        return false;
    }
}

function updateSetupGuideBanner() {
    scheduleTabWarningsRefresh();
    refreshCurriculumUpdatedBanner();
}

function setupCohortsUsageTips() {
    const tips = document.getElementById('cohortsUsageTips');
    const dismissBtn = document.getElementById('cohortsUsageTipsDismiss');
    if (!tips) {
        return;
    }
    try {
        ensureUiState();
        if (appData.ui.cohortsUsageTipsDismissed) {
            tips.hidden = true;
            return;
        }
    } catch (_err) {
        /* show tips */
    }
    if (!tips.dataset.cohortsTipsBound) {
        tips.dataset.cohortsTipsBound = '1';
        dismissBtn?.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            try {
                ensureUiState();
                appData.ui.cohortsUsageTipsDismissed = true;
                saveUiStateToLocalStorage();
                void dismissUiNotificationOnServer(UI_NOTIFICATION_IDS.cohortsUsageTips);
            } catch (_saveErr) {
                /* still hide */
            }
            tips.hidden = true;
            updateCohortsExtraSummary();
            requestAnimationFrame(() => syncCohortsBoardStickyOffsets());
        });
    }
}

async function initCohortsTabControls(options = {}) {
    await ensureExtensionScriptsLoaded();
    if (typeof CCPTabScripts !== 'undefined') {
        await CCPTabScripts.ensureTabScripts('cohorts');
    }
    await ensureTeamTeacherAccountsLoaded();
    initCohortsExtraToggle();
    setupCohortsUsageTips();
    initCohortManagementModule();
    if (typeof CCPCohortManagement !== 'undefined') {
        try {
            CCPCohortManagement.initTab(getCohortManagementHooks(), options);
        } catch (err) {
            console.error('CCPCohortManagement.initTab failed', err);
            setAppStatusMessage(t('cohortsModuleMissing'), true);
        }
    } else {
        setAppStatusMessage(t('cohortsModuleMissing'), true);
    }
    try {
        initSetupBoardModule();
    } finally {
        updateSetupGuideBanner();
        requestAnimationFrame(() => {
            syncCohortsBoardStickyOffsets();
        });
    }
}

function mergeClassroomFieldsFromServer(serverData, options) {
    if (!serverData || typeof serverData !== 'object') {
        return;
    }
    if (Array.isArray(serverData.cohorts)) {
        appData.cohorts = serverData.cohorts;
    }
    if (Array.isArray(serverData.attendanceSessions)) {
        appData.attendanceSessions = serverData.attendanceSessions;
    }
    if (Array.isArray(serverData.homeworkCompletions)) {
        appData.homeworkCompletions = serverData.homeworkCompletions;
    }
    if (Array.isArray(serverData.studentPoints)) {
        appData.studentPoints = serverData.studentPoints;
        if (!options || !options.skipPointsNoteReconcile) {
            void reconcilePointsDayNotesFromLedger();
        }
    }
    if (Array.isArray(serverData.studentTests)) {
        appData.studentTests = serverData.studentTests;
    }
}

async function saveClassroomPartial(fields, options) {
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'cohorts')) {
        appData.cohorts = fields.cohorts;
    }
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'attendanceSessions')) {
        appData.attendanceSessions = fields.attendanceSessions;
    }
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'homeworkCompletions')) {
        appData.homeworkCompletions = fields.homeworkCompletions;
    }
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'studentPoints')) {
        appData.studentPoints = fields.studentPoints;
    }
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'studentTests')) {
        appData.studentTests = fields.studentTests;
    }
    if (fields && Object.prototype.hasOwnProperty.call(fields, 'ui')) {
        Object.assign(appData.ui, fields.ui);
        saveUiStateToLocalStorage();
    }
    saveDataToLocalCache();
    if (!teamSyncEnabled || typeof CalendarSync === 'undefined' || !CalendarSync.saveClassroomData) {
        return null;
    }
    const doc = await CalendarSync.saveClassroomData(fields);
    if (doc && doc.data) {
        mergeClassroomFieldsFromServer(doc.data, options);
        saveDataToLocalCache();
    }
    return doc;
}

function getClassroomHooks() {
    return {
        getAppData: () => appData,
        getLang: () => currentLanguage,
        t,
        escapeHtml,
        escapeAttr,
        generateId,
        getCohorts: () => (Array.isArray(appData.cohorts) ? appData.cohorts : []),
        getCalendarName: () => (appData.calendarName || '').trim(),
        getCurrentUserId: () => {
            if (typeof TeamAuth === 'undefined' || !TeamAuth.getUser) {
                return '';
            }
            const user = TeamAuth.getUser();
            return user && user.id != null ? String(user.id) : '';
        },
        isViewOnly: isTeamCalendarViewOnly,
        openModal,
        closeModal,
        showToast: (msg, isError) => showSyncToast(msg, isError),
        setUiPref(key, value) {
            ensureUiState();
            appData.ui[key] = value == null ? '' : String(value);
            if (typeof CCPActiveContext !== 'undefined') {
                if (key === 'classroomTabClassId' || key === 'homeworkTabClassId') {
                    CCPActiveContext.set({ classId: appData.ui[key] }, { source: 'classroom-ui-pref' });
                } else if (key === 'classroomTabDate' || key === 'homeworkReferenceDate') {
                    CCPActiveContext.set({ sessionDate: appData.ui[key] }, { source: 'classroom-ui-pref' });
                } else if (key === 'cohortsTabSelectedId') {
                    CCPActiveContext.set({ cohortId: appData.ui[key] }, { source: 'cohort-ui-pref' });
                } else {
                    saveUiStateToLocalStorage();
                }
            } else {
                saveUiStateToLocalStorage();
            }
        },
        async saveClassroom(fields, options) {
            return saveClassroomPartial(fields, options);
        },
        async syncPointsDayNote(classId, dateStr) {
            return syncPointsDayNoteForClassDate(classId, dateStr);
        },
        navigateToTab,
        getArchiveRetentionDays() {
            ensureUiState();
            return appData.ui.studentArchiveRetentionDays;
        },
        async setArchiveRetentionDays(days) {
            ensureUiState();
            appData.ui.studentArchiveRetentionDays = Math.max(0, Number(days) || 0);
            saveUiStateToLocalStorage();
        },
        async verifyAdminPassword(password) {
            if (typeof CalendarSync === 'undefined' || !CalendarSync.verifyPassword) {
                throw new Error('Password verification unavailable');
            }
            return CalendarSync.verifyPassword(password);
        },
        canDeleteStudents: () =>
            typeof CCPClassroomAccess !== 'undefined' && CCPClassroomAccess.canDeleteStudentPermanently(),
        getStudentTaggedNotes,
        resolveDayNoteMeta,
        renderDayNoteTextHtml,
        resolveDayNoteCategoryLabel: resolveDayNoteCategoryLabelForUi,
        buildDayNoteCategoryBadgeHtml,
        formatDateDisplay,
        printStudentTermSummary(studentId) {
            openStudentTermSummaryPrint(studentId);
        }
    };
}

async function initClassroomTabControls(tabId, options = {}) {
    await ensureExtensionScriptsLoaded();
    if (typeof CCPTabScripts !== 'undefined') {
        await CCPTabScripts.ensureTabScripts(tabId);
    }
    await ensureTeamTeacherAccountsLoaded();
    const hooks = getClassroomHooks();
    try {
        if (tabId === 'students' && typeof CCPClassroomRoster !== 'undefined') {
            CCPClassroomRoster.initTab(hooks, options);
        } else if (tabId === 'attendance' && typeof CCPClassroomAttendance !== 'undefined') {
            CCPClassroomAttendance.initTab(hooks, options);
        } else if (tabId === 'homework-tracking' && typeof CCPClassroomHomework !== 'undefined') {
            CCPClassroomHomework.initTab(hooks, options);
        } else if (tabId === 'ledger' && typeof CCPClassroomLedger !== 'undefined') {
            CCPClassroomLedger.initTab(hooks, options);
        } else if (tabId === 'points' && typeof CCPClassroomPoints !== 'undefined') {
            CCPClassroomPoints.initTab(hooks, options);
        } else if (tabId === 'tests' && typeof CCPClassroomTests !== 'undefined') {
            CCPClassroomTests.initTab(hooks, options);
        } else {
            setAppStatusMessage(t('classroomModuleMissing'), true);
        }
    } catch (err) {
        console.error('Classroom tab init failed', err);
        setAppStatusMessage(t('classroomModuleMissing'), true);
    }
}

