/** Set term fields on appData only (safe on notes/workspace pages without calendar chrome). */
function ensureTermStartData() {
    if (!appData.termStart) {
        const now = new Date();
        appData.termStart = formatDateForInput(new Date(now.getFullYear(), now.getMonth(), 1));
    } else {
        appData.termStart = normalizeTermStartDate(appData.termStart);
    }
    if (!appData.termMonthCount) {
        appData.termMonthCount = SCHEDULE_CONFIG.defaultTermCalendarMonths;
    }
    if (appData.useAutoTermEnd !== true && appData.useAutoTermEnd !== false) {
        appData.useAutoTermEnd = true;
    }
    if (!appData.termEnd) {
        appData.termEnd = getResolvedTermEndISO();
    }
}

function refreshWorkspaceHomeworkUi() {
    if (!isWorkspacePage()) {
        return;
    }
    renderHomeworkClassList();
    renderHomeworkEditor();
    renderHomeworkReferenceMiniCalendar();
}

function refreshCalendarScopedUi() {
    if (isNotesPage()) {
        refreshNotesPageIfMounted();
        return;
    }
    renderClassList();
    renderEventList();
    updateDataTabCalendarSection();
    updateCalendarTitle();
    updateTopBarCalendarLabel();
    updateCohortsTabCalendarName();

    if (getActiveTab() === 'timetable') {
        refreshTimetablePanels();
    }
    if (getActiveTab() === 'cohorts') {
        void initCohortsTabControls();
    }
    if (typeof CCPSetupBoard !== 'undefined' && CCPSetupBoard.onCalendarDataChanged) {
        CCPSetupBoard.onCalendarDataChanged();
    }
    updateSetupGuideBanner();
    refreshClassEditorCohortUiIfOpen();
    if (getActiveTab() === 'homework' || isWorkspacePage()) {
        renderHomeworkClassList();
        renderHomeworkEditor();
        renderHomeworkReferenceMiniCalendar();
    }
    if (getActiveTab() === 'syllabus') {
        renderSyllabusClassList();
        renderSyllabusTemplateList();
    }
}

function renderTimetableTeacherList() {
    const list = document.getElementById('timetableTeacherList');
    if (!list) {
        return;
    }
    const q = (document.getElementById('timetableTeacherSearch')?.value || '').trim().toLowerCase();
    const active = getTimetableTeacherSelectorFromUi();
    list.innerHTML = '';
    const teachers = listTimetableTeachers().filter((row) => {
        if (!q) {
            return true;
        }
        const hay = [row.displayName, row.userId, row.email].filter(Boolean).join(' ').toLowerCase();
        return hay.includes(q);
    });
    if (!teachers.length) {
        const empty = document.createElement('p');
        empty.className = 'module-list-empty';
        empty.style.padding = 'var(--space-3)';
        empty.style.color = 'var(--text-secondary)';
        empty.textContent = q ? t('lessonFilterSearchEmpty') : t('timetableTeachersListEmpty');
        list.appendChild(empty);
        return;
    }
    const teacherConflictCounts = buildTimetableTeacherConflictCountMap();
    teachers.forEach((row) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        const isSelected = active && timetableTeacherMatchesUi(row, active);
        btn.className = 'module-list-item' + (isSelected ? ' is-selected' : '');
        btn.setAttribute('role', 'option');
        btn.setAttribute('aria-selected', String(isSelected));
        const label = formatTeacherAccountOptionLabel(row);
        const api = getTimetableApi();
        const teacherKey = api ? api.teacherKeyFromSelector(row) : '';
        const conflictCount = teacherConflictCounts.get(teacherKey) || 0;
        const badgeHtml = conflictCount
            ? `<span class="timetable-teacher-conflict-dot" title="${escapeAttr(formatI18n('timetableConflictCount', { count: conflictCount }))}" aria-label="${escapeAttr(formatI18n('timetableConflictCount', { count: conflictCount }))}"></span>`
            : '';
        btn.innerHTML = `<span>${escapeHtml(label)}</span>${badgeHtml}`;
        btn.addEventListener('click', () => {
            selectTimetableTeacher({ userId: row.userId, displayName: row.displayName });
        });
        list.appendChild(btn);
    });
}

function createTimetableClassListButton(classData, teacherRow, onClick) {
    const api = getTimetableApi();
    const lang = currentLanguage === 'ko' ? 'ko' : 'en';
    const category = (teacherRow && teacherRow.category)
        || (api ? api.getTeacherCategoryForClass(classData, {
            userId: teacherRow.userId,
            displayName: teacherRow.name
        }) : '');
    const schedule = api && teacherRow
        ? api.formatTeacherRowScheduleSummary(classData, teacherRow, appData, lang)
        : '';
    const metaParts = [category, schedule].filter(Boolean);
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'module-list-item';
    btn.setAttribute('role', 'option');
    btn.innerHTML = `<span>${escapeHtml(classData.name || '')}</span><span class="module-list-item-meta">${escapeHtml(metaParts.join(' · '))}</span>`;
    btn.addEventListener('click', onClick);
    return btn;
}

function renderTimetableClassList(selector) {
    const list = document.getElementById('timetableClassList');
    if (!list) {
        return;
    }
    list.innerHTML = '';
    if (!selector || (!selector.userId && !selector.displayName)) {
        return;
    }
    const api = getTimetableApi();
    if (!api) {
        return;
    }
    const q = (document.getElementById('timetableClassListSearch')?.value || '').trim().toLowerCase();
    let items = api.getClassesForTeacherSchedule(appData, selector);
    items = items.slice().sort((a, b) =>
        (a.classData.name || '').localeCompare(b.classData.name || '', undefined, { sensitivity: 'base' })
    );
    if (q) {
        items = items.filter(({ classData, teacherRow }) => {
            const category = teacherRow.category
                || api.getTeacherCategoryForClass(classData, selector);
            const hay = [classData.name, classData.grade, category].filter(Boolean).join(' ').toLowerCase();
            return hay.includes(q);
        });
    }
    if (!items.length) {
        const empty = document.createElement('p');
        empty.className = 'module-list-empty';
        empty.style.padding = 'var(--space-3)';
        empty.style.color = 'var(--text-secondary)';
        if (q) {
            empty.textContent = t('lessonFilterSearchEmpty');
        } else {
            const lang = currentLanguage === 'ko' ? 'ko' : 'en';
            const grid = api.buildTeacherWeeklyGrid(appData, selector, { lang });
            const homeroomOnly = grid.homeroomCohorts && grid.homeroomCohorts.length > 0
                && !grid.assignedClassCount;
            empty.textContent = homeroomOnly
                ? t('timetableHomeroomOnlyTeacher')
                : t('timetableNoClassesForTeacher');
        }
        list.appendChild(empty);
        return;
    }
    items.forEach(({ classData, teacherRow }) => {
        list.appendChild(createTimetableClassListButton(classData, teacherRow, () => {
            openTimetableClassEditor(classData.id);
        }));
    });
}

function getTimetableEntryDisplayColors(entry) {
    const bg = (entry && entry.color) ? entry.color : '#6366f1';
    const preferred = (entry && entry.textColor) || DEFAULT_CLASS_TEXT_COLOR;
    return {
        bg,
        text: getReadableTextOnBackground(bg, preferred)
    };
}

function openTimetableClassEditor(classId) {
    if (!classId) {
        return;
    }
    const classData = appData.classes.find((c) => c.id === classId);
    if (!classData) {
        return;
    }
    openClassEditor(classData, 'calendar-popout');
}

function bindTimetableClassClickTarget(el, classId, options) {
    options = options || {};
    if (!el || !classId) {
        return;
    }
    const classData = appData.classes.find((c) => c.id === classId);
    const label = ((classData && classData.name) || options.displayName || '').trim() || t('editClass');
    const openTarget = () => {
        if (typeof options.onSelect === 'function') {
            options.onSelect(classId, options);
            return;
        }
        openHomeworkFromTimetable(classId, options);
    };
    el.classList.add('timetable-cell--clickable');
    el.setAttribute('role', 'button');
    el.tabIndex = 0;
    el.setAttribute('aria-label', `${label} — ${t('contextOpenHomework')}`);
    el.addEventListener('click', openTarget);
    el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openTarget();
        }
    });
    el.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        e.stopPropagation();
        showTimetableContextMenu(e.clientX, e.clientY, {
            classId,
            displayName: options.displayName || (classData && classData.name) || '',
            dow: options.dow,
            timeSlotId: options.timeSlotId
        });
    });
}

function appendTimetableEntryContent(container, entry) {
    const nameLine = document.createElement('span');
    nameLine.className = 'timetable-cell-name';
    nameLine.textContent = entry.className;
    container.appendChild(nameLine);
    if (entry.category) {
        container.appendChild(document.createElement('br'));
        const catLine = document.createElement('span');
        catLine.className = 'timetable-cell-category';
        catLine.textContent = `(${entry.category})`;
        container.appendChild(catLine);
    }
    if (entry.homeroomLabel) {
        container.appendChild(document.createElement('br'));
        const hrLine = document.createElement('span');
        hrLine.className = 'timetable-cell-hr';
        const hrPrefix = currentLanguage === 'ko' ? t('timetableCellHomeroom') : 'HR';
        hrLine.textContent = `${hrPrefix}: ${entry.homeroomLabel}`;
        container.appendChild(hrLine);
    }
}

const TIMETABLE_UI_ROW_HEIGHT_PX = 96;
const TIMETABLE_SCREEN_GRID_GAP_MM = 4;

function wrapTimetableCellInner(cellEl) {
    if (!cellEl || cellEl.querySelector(':scope > .timetable-cell-inner')) {
        return;
    }
    const inner = document.createElement('div');
    inner.className = 'timetable-cell-inner';
    while (cellEl.firstChild) {
        inner.appendChild(cellEl.firstChild);
    }
    cellEl.appendChild(inner);
}

function parseTimetableCssLengthToPx(doc, value) {
    const raw = String(value || '').trim();
    if (!raw || raw === 'auto' || raw === 'normal') {
        return null;
    }
    const num = parseFloat(raw);
    if (Number.isNaN(num)) {
        return null;
    }
    if (raw.endsWith('px')) {
        return num;
    }
    if (raw.endsWith('rem')) {
        const rootSize = parseFloat(doc.defaultView.getComputedStyle(doc.documentElement).fontSize) || 16;
        return num * rootSize;
    }
    return num;
}

function applyTimetableUniformRowHeights(rootEl, rowHeightPx) {
    if (!rootEl) {
        return;
    }
    const tables = rootEl.classList && rootEl.classList.contains('timetable-grid')
        ? [rootEl]
        : Array.from(rootEl.querySelectorAll('.timetable-grid'));
    tables.forEach((table) => {
        const doc = table.ownerDocument;
        let px = rowHeightPx;
        if (px == null || px < 1) {
            const computed = doc.defaultView.getComputedStyle(table);
            const raw = computed.getPropertyValue('--timetable-row-height').trim()
                || computed.getPropertyValue('--timetable-print-row-height').trim();
            px = parseTimetableCssLengthToPx(doc, raw);
        }
        if (!px || px < 1) {
            px = TIMETABLE_UI_ROW_HEIGHT_PX;
        }
        const h = `${Math.round(px)}px`;
        table.style.setProperty('--timetable-row-height', h);
        table.querySelectorAll('tbody tr').forEach((tr) => {
            tr.style.height = h;
            tr.style.maxHeight = h;
            tr.querySelectorAll('td, th').forEach((cell) => {
                cell.style.height = h;
                cell.style.maxHeight = h;
                cell.style.overflow = 'hidden';
                cell.style.boxSizing = 'border-box';
                cell.style.padding = '0';
                const inner = cell.querySelector(':scope > .timetable-cell-inner');
                if (inner) {
                    inner.style.height = h;
                    inner.style.maxHeight = h;
                    inner.style.overflow = 'hidden';
                    inner.style.boxSizing = 'border-box';
                }
            });
        });
    });
}

function renderTimetableGridTable(block, lang, options) {
    options = options || {};
    const printMode = !!options.printMode;
    const highlightCurrent = !printMode && options.highlightCurrentClass === true;
    const currentCtx = highlightCurrent ? getCurrentClassContext() : null;
    const conflicts = options.conflicts || null;
    const table = document.createElement('table');
    table.className = 'timetable-grid' + (block.id === 'secondary' ? ' timetable-grid--secondary' : '');
    const thead = document.createElement('thead');
    const headRow = document.createElement('tr');
    const timeTh = document.createElement('th');
    timeTh.scope = 'col';
    timeTh.className = 'timetable-col-time';
    timeTh.textContent = t('timetableTimeHeader');
    headRow.appendChild(timeTh);
    block.columns.forEach((col) => {
        const th = document.createElement('th');
        th.scope = 'col';
        th.textContent = lang === 'ko' ? col.ko : col.en;
        headRow.appendChild(th);
    });
    thead.appendChild(headRow);
    table.appendChild(thead);

    const tbody = document.createElement('tbody');
    block.rows.forEach((row) => {
        const tr = document.createElement('tr');
        const timeTd = document.createElement('th');
        timeTd.scope = 'row';
        timeTd.className = 'timetable-col-time';
        timeTd.textContent = row.timeLabel || '';
        wrapTimetableCellInner(timeTd);
        tr.appendChild(timeTd);
        row.cells.forEach((cell) => {
            const td = document.createElement('td');
            td.className = 'timetable-cell';
            applyTimetableCellConflictState(td, cell, row, block, conflicts);
            if (cell.conflict || cell.cohortCollision) {
                appendTimetableCellConflictLabel(td, cell);
            }
            if (cell.entries.length === 1) {
                const entry = cell.entries[0];
                if (entry.combinedCohorts) {
                    td.classList.add('timetable-cell--combined');
                }
                const { bg, text } = getTimetableEntryDisplayColors(entry);
                td.classList.add('timetable-cell--colored');
                td.style.backgroundColor = bg;
                td.style.color = text;
                appendTimetableEntryContent(td, entry);
                if (
                    currentCtx
                    && currentCtx.classId === entry.classId
                    && currentCtx.dow === cell.dow
                    && currentCtx.timeSlotId === row.timeSlotId
                ) {
                    td.classList.add('timetable-cell--now');
                }
                if (!printMode) {
                    const clickOpts = {
                        displayName: entry.className,
                        dow: cell.dow,
                        timeSlotId: row.timeSlotId
                    };
                    if (typeof options.onClassClick === 'function') {
                        clickOpts.onSelect = options.onClassClick;
                    }
                    bindTimetableClassClickTarget(td, entry.classId, clickOpts);
                }
            } else if (cell.entries.length > 1) {
                cell.entries.forEach((entry) => {
                    const { bg, text } = getTimetableEntryDisplayColors(entry);
                    const entryBlock = document.createElement('div');
                    entryBlock.className = 'timetable-cell-entry timetable-cell-entry--colored';
                    entryBlock.style.backgroundColor = bg;
                    entryBlock.style.color = text;
                    appendTimetableEntryContent(entryBlock, entry);
                    if (
                        currentCtx
                        && currentCtx.classId === entry.classId
                        && currentCtx.dow === cell.dow
                        && currentCtx.timeSlotId === row.timeSlotId
                    ) {
                        entryBlock.classList.add('timetable-cell--now');
                    }
                    if (!printMode) {
                        const clickOpts = {
                            displayName: entry.className,
                            dow: cell.dow,
                            timeSlotId: row.timeSlotId
                        };
                        if (typeof options.onClassClick === 'function') {
                            clickOpts.onSelect = options.onClassClick;
                        }
                        bindTimetableClassClickTarget(entryBlock, entry.classId, clickOpts);
                    }
                    td.appendChild(entryBlock);
                });
            }
            wrapTimetableCellInner(td);
            tr.appendChild(td);
        });
        tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    return table;
}

function setTimetableClassesSidebarVisible(visible) {
    const sidebar = document.getElementById('timetableClassesSidebar');
    if (sidebar) {
        sidebar.hidden = !visible;
    }
}

function renderTimetableView(selector) {
    const api = getTimetableApi();
    const pickHint = document.getElementById('timetablePickTeacherHint');
    const view = document.getElementById('timetableView');
    const titleEl = document.getElementById('timetableTeacherTitle');
    const homeroomLine = document.getElementById('timetableHomeroomLine');
    const homeroomChips = document.getElementById('timetableHomeroomChips');
    const termLabel = document.getElementById('timetableTermLabel');
    const gridsMount = document.getElementById('timetableGridsMount');
    const conflictBadge = document.getElementById('timetableConflictBadge');
    if (!api || !gridsMount) {
        return;
    }
    if (!selector || (!selector.userId && !selector.displayName)) {
        if (pickHint) {
            pickHint.hidden = false;
        }
        if (view) {
            view.hidden = true;
        }
        if (conflictBadge) {
            conflictBadge.hidden = true;
        }
        const conflictPanel = document.getElementById('timetableConflictPanel');
        if (conflictPanel) {
            conflictPanel.hidden = true;
            conflictPanel.innerHTML = '';
        }
        setTimetableClassesSidebarVisible(false);
        return;
    }
    const lang = currentLanguage === 'ko' ? 'ko' : 'en';
    const grid = api.buildTeacherWeeklyGrid(appData, selector, { lang });
    if (pickHint) {
        pickHint.hidden = true;
    }
    if (view) {
        view.hidden = false;
    }
    setTimetableClassesSidebarVisible(true);
    if (titleEl) {
        const suffix = lang === 'ko' ? ' 선생님' : '';
        titleEl.textContent = `${grid.teacherName || selector.displayName || selector.userId}${suffix}`;
    }
    if (homeroomLine && homeroomChips) {
        homeroomChips.innerHTML = '';
        if (grid.homeroomLabels.length) {
            homeroomLine.hidden = false;
            grid.homeroomLabels.forEach((label) => {
                const chip = document.createElement('span');
                chip.className = 'timetable-homeroom-chip';
                chip.textContent = label;
                homeroomChips.appendChild(chip);
            });
        } else {
            homeroomLine.hidden = true;
        }
    }
    if (termLabel) {
        const termParts = [];
        if (appData.calendarName) {
            termParts.push(appData.calendarName);
        } else if (appData.termStart) {
            termParts.push(appData.termStart);
        }
        termLabel.textContent = termParts.join(' · ');
    }
    const cohortsSummary = document.getElementById('timetableCohortsSummary');
    if (cohortsSummary) {
        cohortsSummary.innerHTML = '';
        if (grid.homeroomCohorts && grid.homeroomCohorts.length) {
            cohortsSummary.hidden = false;
            const heading = document.createElement('h3');
            heading.className = 'timetable-cohorts-summary-title';
            heading.textContent = t('timetableHomeroomCohortsHeading');
            cohortsSummary.appendChild(heading);
            const list = document.createElement('ul');
            list.className = 'timetable-cohorts-summary-list';
            grid.homeroomCohorts.forEach((cohort) => {
                const li = document.createElement('li');
                const suffix = cohort.homeroomDaySuffix ? ` (${cohort.homeroomDaySuffix})` : '';
                const count = (cohort.classIds || []).length;
                li.textContent = `${cohort.name || cohort.level || cohort.id}${suffix} — ${t('timetableHomeroomCohortClasses').replace('{n}', String(count))}`;
                list.appendChild(li);
            });
            cohortsSummary.appendChild(list);
        } else {
            cohortsSummary.hidden = true;
        }
    }
    gridsMount.innerHTML = '';
    renderTimetableConflictPanel(grid.conflicts);
    const highlightCurrent = isViewingOwnTimetableSchedule(selector);
    const gridRenderOptions = {
        highlightCurrentClass: highlightCurrent,
        conflicts: grid.conflicts
    };
    if (preferTimetableListView()) {
        renderTimetableListInto(gridsMount, grid, lang, gridRenderOptions);
    } else {
        grid.blocks.forEach((block) => {
            gridsMount.appendChild(renderTimetableGridTable(block, lang, gridRenderOptions));
        });
        layoutTimetableGridsForScreen(gridsMount);
    }
    if (conflictBadge) {
        conflictBadge.hidden = false;
        if (grid.hasConflicts && grid.conflicts) {
            conflictBadge.textContent = formatI18n('timetableConflictCount', {
                count: grid.conflicts.conflictCount
            });
        } else {
            conflictBadge.textContent = t('timetableNoConflicts');
        }
        conflictBadge.classList.toggle('timetable-conflict-badge--warn', grid.hasConflicts);
    }
    scheduleTabWarningsRefresh();
}

const TIMETABLE_PRINT_LANDSCAPE = {
    pageW: 297,
    pageH: 210,
    margin: 10,
    fitSafety: 2,
    get contentW() {
        return this.pageW - this.margin * 2;
    },
    get contentH() {
        return this.pageH - this.margin * 2;
    },
    get fitContentH() {
        return this.contentH - this.fitSafety;
    }
};

function computeTimetableUniformRowPx(tables, contentHpx, gapPx, minRowPx) {
    if (!tables.length) {
        return minRowPx;
    }
    let theadHeights = 0;
    let totalBodyRows = 0;
    tables.forEach((table) => {
        const thead = table.querySelector('thead');
        if (thead) {
            theadHeights += thead.offsetHeight;
        }
        totalBodyRows += table.querySelectorAll('tbody tr').length;
    });
    const gapsTotal = Math.max(0, tables.length - 1) * gapPx;
    const bodyBudget = Math.max(minRowPx, contentHpx - theadHeights - gapsTotal);
    if (totalBodyRows <= 0) {
        return minRowPx;
    }
    return Math.max(minRowPx, Math.floor(bodyBudget / totalBodyRows));
}

function measureTimetableScreenPrintHeaderPx() {
    let total = 0;
    ['timetableTeacherTitle', 'timetableHomeroomLine', 'timetableTermLabel'].forEach((id) => {
        const el = document.getElementById(id);
        if (!el || el.hidden) {
            return;
        }
        const style = window.getComputedStyle(el);
        total += el.offsetHeight;
        total += (parseFloat(style.marginTop) || 0) + (parseFloat(style.marginBottom) || 0);
    });
    return total;
}

function measureTimetablePreviewHeaderPx(mountEl) {
    if (!mountEl) {
        return 0;
    }
    let total = 0;
    Array.from(mountEl.children).forEach((child) => {
        if (child.classList.contains('timetable-grid')) {
            return;
        }
        const style = window.getComputedStyle(child);
        total += child.offsetHeight;
        total += (parseFloat(style.marginTop) || 0) + (parseFloat(style.marginBottom) || 0);
    });
    return total;
}

/** Match on-screen row heights to the A4 landscape print grid layout. */
function layoutTimetableGridsForScreen(mountEl) {
    if (!mountEl) {
        return;
    }
    const tables = Array.from(mountEl.querySelectorAll('.timetable-grid'));
    if (!tables.length) {
        return;
    }

    const doc = mountEl.ownerDocument;
    const mmPx = measureMmToPxForPrint(doc);
    const a4 = TIMETABLE_PRINT_LANDSCAPE;
    const contentWpx = Math.round(a4.contentW * mmPx);
    const headerH = mountEl.id === 'timetableGridsMount'
        ? measureTimetableScreenPrintHeaderPx()
        : measureTimetablePreviewHeaderPx(mountEl);
    const contentHpx = Math.max(1, Math.round(a4.fitContentH * mmPx) - headerH - 4);
    const gapPx = Math.round(TIMETABLE_SCREEN_GRID_GAP_MM * mmPx);

    tables.forEach((table) => {
        table.style.width = `${contentWpx}px`;
        table.style.maxWidth = '100%';
        table.style.tableLayout = 'fixed';
    });

    void doc.body.offsetHeight;

    const rowPx = computeTimetableUniformRowPx(
        tables,
        contentHpx,
        gapPx,
        TIMETABLE_UI_ROW_HEIGHT_PX
    );
    applyTimetableUniformRowHeights(mountEl, rowPx);
}

