const TIMETABLE_PRINT_GRID_GAP_MM = 4;

function resetTimetablePrintGridSizing(grids) {
    if (!grids) {
        return;
    }
    grids.style.removeProperty('--timetable-print-row-height');
    grids.querySelectorAll('.timetable-grid').forEach((table) => {
        table.style.width = '';
        table.style.tableLayout = '';
        table.style.fontSize = '';
        table.querySelectorAll('tbody tr').forEach((tr) => {
            tr.style.height = '';
            tr.style.maxHeight = '';
            tr.querySelectorAll('td, th').forEach((cell) => {
                cell.style.height = '';
                cell.style.maxHeight = '';
                cell.style.overflow = '';
                cell.style.boxSizing = '';
            });
        });
    });
}

/** Distribute body row height evenly so the grid fills the landscape printable area. */
function layoutTimetableGridsForPrint(doc, grids, contentWpx, contentHpx, mmPx) {
    if (!grids) {
        return 0;
    }
    resetTimetablePrintGridSizing(grids);

    const tables = Array.from(grids.querySelectorAll('.timetable-grid'));
    if (!tables.length) {
        return 0;
    }

    const gapPx = Math.round(TIMETABLE_PRINT_GRID_GAP_MM * mmPx);

    tables.forEach((table) => {
        table.style.width = `${contentWpx}px`;
        table.style.tableLayout = 'fixed';
    });

    void doc.body.offsetHeight;

    const rowPx = computeTimetableUniformRowPx(tables, contentHpx, gapPx, 10);

    grids.style.setProperty('--timetable-print-row-height', `${rowPx}px`);
    applyTimetableUniformRowHeights(grids, rowPx);

    void doc.body.offsetHeight;
    return rowPx;
}

function computeTimetableGridScale(naturalH, naturalW, contentWpx, contentHpx) {
    if (!naturalH || naturalH < 1 || !naturalW || naturalW < 1) {
        return 1;
    }
    const scaleW = contentWpx / naturalW;
    const scaleH = contentHpx / naturalH;
    return Math.min(scaleW, scaleH, 1);
}

function fitTimetableGridForPrint(doc) {
    const a4 = TIMETABLE_PRINT_LANDSCAPE;
    const sheet = doc.querySelector('.timetable-print-sheet--landscape');
    const wrap = doc.querySelector('[data-timetable-fit-wrap="1"]');
    const inner = doc.querySelector('[data-timetable-fit-inner="1"]');
    const grids = doc.querySelector('.timetable-print-grids');
    if (!sheet || !wrap || !inner || !grids) {
        return;
    }

    const mmPx = measureMmToPxForPrint(doc);
    const contentWpx = Math.round(a4.contentW * mmPx);
    const header = sheet.querySelector('.timetable-print-header');
    const headerH = header ? header.offsetHeight : 0;
    const contentHpx = Math.max(1, Math.round(a4.fitContentH * mmPx) - headerH - 4);

    wrap.style.width = `${contentWpx}px`;
    wrap.style.height = `${contentHpx}px`;
    wrap.style.maxHeight = `${contentHpx}px`;
    wrap.style.display = '';
    wrap.style.justifyContent = '';
    wrap.style.alignItems = '';
    wrap.style.paddingTop = '';

    inner.style.transform = '';
    inner.style.transformOrigin = '';
    inner.style.width = '';

    layoutTimetableGridsForPrint(doc, grids, contentWpx, contentHpx, mmPx);

    void doc.body.offsetHeight;

    let naturalH = inner.scrollHeight;
    let naturalW = inner.scrollWidth || inner.offsetWidth;
    let scale = computeTimetableGridScale(naturalH, naturalW, contentWpx, contentHpx);

    if (scale < 0.85) {
        grids.querySelectorAll('.timetable-grid').forEach((table) => {
            table.style.fontSize = '8pt';
        });
        void doc.body.offsetHeight;
        naturalH = inner.scrollHeight;
        naturalW = inner.scrollWidth || inner.offsetWidth;
        scale = computeTimetableGridScale(naturalH, naturalW, contentWpx, contentHpx);
    }

    const scaledH = Math.ceil(naturalH * scale);
    if (scale < 0.999) {
        inner.style.transformOrigin = 'top center';
        inner.style.transform = `scale(${scale})`;
        inner.style.width = `${naturalW}px`;
        wrap.style.display = 'flex';
        wrap.style.justifyContent = 'center';
        wrap.style.alignItems = 'flex-start';
        wrap.style.paddingTop = scaledH < contentHpx
            ? `${Math.floor((contentHpx - scaledH) / 2)}px`
            : '0';
    } else {
        inner.style.width = '100%';
        wrap.style.paddingTop = '0';
    }
}

function runTimetablePrint(opts) {
    const ctx = getTimetablePrintContext();
    if (!ctx) {
        alert(t('timetableSelectTeacher'));
        return;
    }
    const { selector, grid } = ctx;
    const html = buildTimetablePrintDocumentHtml(opts, grid);
    if (!html) {
        alert(t('timetableSelectTeacher'));
        return;
    }

    beginPrintColorMode();
    const printWin = window.open('', '_blank');
    if (!printWin) {
        alert(t('printSyllabusBlocked'));
        endPrintColorMode();
        return;
    }
    printWin.document.open();
    printWin.document.write(html);
    printWin.document.close();
    const teacherLabel = grid.teacherName || selector.displayName || 'timetable';
    printWin.document.title = `${t('timetablePrint')} — ${teacherLabel}`;
    printWin.document.documentElement.classList.add('print-color-mode-light');

    whenPrintWindowReady(printWin, () => {
        fitTimetableGridForPrint(printWin.document);
        const orient = printWin.document.createElement('style');
        orient.setAttribute('data-timetable-print-orient', '1');
        orient.textContent = '@page timetable-landscape { size: A4 landscape; margin: 0; }';
        printWin.document.head.appendChild(orient);
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                let finished = false;
                let closedPoll = null;
                const finish = () => {
                    if (finished) {
                        return;
                    }
                    finished = true;
                    if (closedPoll !== null) {
                        clearInterval(closedPoll);
                        closedPoll = null;
                    }
                    try {
                        printWin.close();
                    } catch (e) { /* ignore */ }
                    endPrintColorMode();
                };
                printWin.addEventListener('afterprint', finish, { once: true });
                printWin.addEventListener('pagehide', finish, { once: true });
                closedPoll = setInterval(() => {
                    if (finished) {
                        return;
                    }
                    let closed = false;
                    try {
                        closed = printWin.closed;
                    } catch (e) {
                        closed = true;
                    }
                    if (closed) {
                        finish();
                    }
                }, 250);
                try {
                    printWin.print();
                } catch (e) { /* user may print manually */ }
                setTimeout(finish, 120000);
            });
        });
    });
}

function handleTimetablePrintSubmit(e) {
    e.preventDefault();
    const opts = getTimetablePrintOptionsFromForm();
    const modal = document.getElementById('timetablePrintOptionsModal');
    if (modal && modal.classList.contains('active')) {
        closeTimetablePrintOptionsModal();
    }
    runTimetablePrint(opts);
}

function initTimetablePrintControls() {
    const form = document.getElementById('timetablePrintForm');
    if (form && !form.dataset.timetablePrintInit) {
        form.dataset.timetablePrintInit = '1';
        form.addEventListener('submit', handleTimetablePrintSubmit);
    }
    const closeBtn = document.getElementById('closeTimetablePrintOptionsModal');
    if (closeBtn && !closeBtn.dataset.timetablePrintInit) {
        closeBtn.dataset.timetablePrintInit = '1';
        closeBtn.addEventListener('click', closeTimetablePrintOptionsModal);
    }
    const selectAll = document.getElementById('timetablePrintExtrasSelectAllBtn');
    if (selectAll && !selectAll.dataset.timetablePrintInit) {
        selectAll.dataset.timetablePrintInit = '1';
        selectAll.addEventListener('click', () => setTimetablePrintExtrasCheckboxes(true));
    }
    const clearAll = document.getElementById('timetablePrintExtrasClearAllBtn');
    if (clearAll && !clearAll.dataset.timetablePrintInit) {
        clearAll.dataset.timetablePrintInit = '1';
        clearAll.addEventListener('click', () => setTimetablePrintExtrasCheckboxes(false));
    }
    const secondaryCb = document.getElementById('timetablePrintIncludeSecondary');
    if (secondaryCb && !secondaryCb.dataset.timetablePrintInit) {
        secondaryCb.dataset.timetablePrintInit = '1';
        secondaryCb.addEventListener('change', () => {
            secondaryCb.dataset.userTouched = '1';
        });
    }
}

function renderTimetableCohortsList() {
    if (getActiveTab() === 'cohorts' && typeof CCPCohortManagement !== 'undefined') {
        CCPCohortManagement.initTab(getCohortManagementHooks(), {});
    }
}

function syncClassCohortLinks(cohort) {
    if (!cohort || !cohort.id) {
        return;
    }
    const api = getTimetableApi();
    const ids = new Set();
    (appData.classes || []).forEach((cls) => {
        if (api ? api.classHasCohortId(cls, cohort.id) : normalizeStr(cls.cohortId) === cohort.id) {
            ids.add(cls.id);
        }
    });
    cohort.classIds = Array.from(ids);
    cohort.classIds.forEach((classId) => {
        const cls = appData.classes.find((c) => c.id === classId);
        if (!cls) {
            return;
        }
        if (api) {
            api.addClassCohortId(cls, cohort.id);
        } else {
            cls.cohortId = cohort.id;
        }
    });
}

function suggestAndMergeCohorts() {
    const api = getTimetableApi();
    if (!api) {
        return;
    }
    const suggestions = api.suggestCohortsFromClasses(appData.classes || []);
    let added = 0;
    suggestions.forEach((sug) => {
        const existing = (appData.cohorts || []).find((c) =>
            c.level === sug.level
            && c.grade === sug.grade
            && api.meetingDaysKey(c.meetingDays) === api.meetingDaysKey(sug.meetingDays)
        );
        if (existing) {
            sug.classIds.forEach((classId) => {
                if (!existing.classIds.includes(classId)) {
                    existing.classIds.push(classId);
                }
            });
            syncClassCohortLinks(existing);
            return;
        }
        const cohort = {
            id: generateId(),
            name: sug.name,
            level: sug.level,
            grade: sug.grade,
            meetingDays: sug.meetingDays,
            classIds: sug.classIds.slice(),
            homeroomTeacherUserId: '',
            homeroomTeacherName: '',
            homeroomDaySuffix: api.inferHomeroomDaySuffix(sug, {})
        };
        appData.cohorts.push(cohort);
        syncClassCohortLinks(cohort);
        added += 1;
    });
    (appData.cohorts || []).forEach((cohort) => syncClassCohortLinks(cohort));
    if (added) {
        saveData();
        refreshClassEditorCohortUiIfOpen();
    }
    renderTimetableCohortsList();
    setAppStatusMessage(t('timetableCohortsSuggested').replace('{n}', String(added)), false);
}

async function initTimetableTabControls(options) {
    await ensureTeamTeacherAccountsLoaded();
    initTimetableTabListeners();
    renderTimetableCohortsList();
    if (options && options.teacherUserId) {
        const teachers = listTimetableTeachers();
        const match = teachers.find((row) => row.userId === options.teacherUserId);
        if (match) {
            selectTimetableTeacher({ userId: match.userId, displayName: match.displayName });
            return;
        }
    }
    const saved = getTimetableTeacherSelectorFromUi();
    renderTimetableTeacherList();
    if (saved) {
        renderTimetableClassList(saved);
        renderTimetableView(saved);
    } else {
        renderTimetableClassList(null);
        renderTimetableView(null);
    }
}

function initTimetablePeriodSchedule() {
    const openBtn = document.getElementById('timetablePeriodScheduleBtn');
    const modal = document.getElementById('timetablePeriodModal');
    if (!openBtn || !modal || openBtn.dataset.timetablePeriodInit) {
        return;
    }
    openBtn.dataset.timetablePeriodInit = '1';
    let draftSlots = [];
    let draftMap = {};

    const closeModal = () => {
        modal.style.display = 'none';
    };

    const renderRows = () => {
        const mount = document.getElementById('timetablePeriodRows');
        const api = getTimetablePeriodsApi();
        if (!mount || !api) {
            return;
        }
        const nums = api.getPeriodNumbers(draftMap);
        mount.innerHTML = '';
        const table = document.createElement('table');
        table.className = 'timetable-period-table';
        const thead = document.createElement('thead');
        thead.innerHTML = `<tr>
            <th>${escapeHtml(t('timetablePeriodColPeriod'))}</th>
            <th>${escapeHtml(t('timetablePeriodColStart'))}</th>
            <th>${escapeHtml(t('timetablePeriodColEnd'))}</th>
            <th>${escapeHtml(t('timetablePeriodColDuration'))}</th>
            <th></th>
        </tr>`;
        table.appendChild(thead);
        const tbody = document.createElement('tbody');
        nums.forEach((periodNum) => {
            const slotId = draftMap[String(periodNum)];
            const slot = draftSlots.find((s) => s.id === slotId) || {};
            const tr = document.createElement('tr');
            tr.dataset.period = String(periodNum);
            tr.innerHTML = `
                <td>${periodNum}</td>
                <td><input type="time" class="field-input field-control timetable-period-start" value="${escapeHtml(slot.start || '')}"></td>
                <td><input type="time" class="field-input field-control timetable-period-end" value="${escapeHtml(slot.end || '')}"></td>
                <td><input type="number" min="1" max="240" class="field-input field-control timetable-period-duration" value="${slot.durationMin != null ? slot.durationMin : ''}"></td>
                <td><button type="button" class="btn btn-outline btn-small timetable-period-remove">${escapeHtml(t('timetablePeriodRemove'))}</button></td>
            `;
            tbody.appendChild(tr);
        });
        table.appendChild(tbody);
        mount.appendChild(table);
    };

    const collectDraftFromDom = () => {
        const api = getTimetablePeriodsApi();
        if (!api) {
            return { slots: draftSlots, map: draftMap };
        }
        const nums = api.getPeriodNumbers(draftMap);
        const slotById = new Map(draftSlots.map((s) => [s.id, Object.assign({}, s)]));
        document.querySelectorAll('#timetablePeriodRows tbody tr').forEach((tr) => {
            const periodNum = tr.dataset.period;
            const slotId = draftMap[String(periodNum)];
            if (!slotId || !slotById.has(slotId)) {
                return;
            }
            const start = tr.querySelector('.timetable-period-start')?.value || '';
            const end = tr.querySelector('.timetable-period-end')?.value || '';
            const durRaw = tr.querySelector('.timetable-period-duration')?.value;
            const slot = slotById.get(slotId);
            slot.start = start;
            slot.end = end;
            if (durRaw !== '' && durRaw != null) {
                slot.durationMin = parseInt(durRaw, 10);
            } else {
                const auto = api.computeDurationMin(start, end);
                if (auto != null) {
                    slot.durationMin = auto;
                }
            }
        });
        return {
            slots: api.normalizeTimeSlots([...slotById.values()]),
            map: Object.assign({}, draftMap)
        };
    };

    openBtn.addEventListener('click', () => {
        if (isTeamCalendarViewOnly()) {
            showLockFlash(t('teamReadOnlySave'), false);
            return;
        }
        const api = getTimetablePeriodsApi();
        if (!api) {
            return;
        }
        draftSlots = api.getSortedTimeSlots(appData);
        draftMap = Object.assign({}, appData.periodSlotMap || api.getDefaultMap());
        renderRows();
        modal.style.display = 'flex';
    });

    document.getElementById('timetablePeriodModalClose')?.addEventListener('click', closeModal);
    document.getElementById('timetablePeriodCancelBtn')?.addEventListener('click', closeModal);

    document.getElementById('timetablePeriodRows')?.addEventListener('click', (e) => {
        const btn = e.target.closest('.timetable-period-remove');
        if (!btn) {
            return;
        }
        const api = getTimetablePeriodsApi();
        const tr = btn.closest('tr');
        const periodNum = tr && tr.dataset.period;
        if (!api || !periodNum) {
            return;
        }
        const inUse = api.findClassesUsingPeriod(appData, periodNum);
        if (inUse.length) {
            const names = inUse.map((c) => c.name || c.id).join(', ');
            alert(t('timetablePeriodInUse').replace('{period}', periodNum).replace('{classes}', names));
            return;
        }
        const collected = collectDraftFromDom();
        const result = api.removePeriod(collected.slots, collected.map, periodNum);
        if (!result.ok) {
            return;
        }
        draftSlots = result.slots;
        draftMap = result.map;
        renderRows();
    });

    document.getElementById('timetablePeriodAddBtn')?.addEventListener('click', () => {
        const api = getTimetablePeriodsApi();
        if (!api) {
            return;
        }
        const collected = collectDraftFromDom();
        const result = api.addPeriod(collected.slots, collected.map);
        if (!result.ok) {
            return;
        }
        draftSlots = result.slots;
        draftMap = result.map;
        renderRows();
    });

    document.getElementById('timetablePeriodResetBtn')?.addEventListener('click', () => {
        const api = getTimetablePeriodsApi();
        if (!api || !confirm(t('timetablePeriodResetDefaults'))) {
            return;
        }
        const defaults = api.resetToDefaultSchedule();
        draftSlots = defaults.slots;
        draftMap = defaults.map;
        renderRows();
    });

    document.getElementById('timetablePeriodSaveBtn')?.addEventListener('click', () => {
        const api = getTimetablePeriodsApi();
        if (!api) {
            return;
        }
        const collected = collectDraftFromDom();
        const validation = api.validatePeriodSchedule(collected.slots, collected.map);
        if (!validation.ok) {
            const bad = validation.errors.find((err) => err.startsWith('invalid_range:'));
            if (bad) {
                const period = collected.map ? api.getPeriodNumbers(collected.map)[0] : '';
                alert(t('timetablePeriodInvalidTime').replace('{period}', period || '?'));
            }
            return;
        }
        appData.timetableTimeSlots = validation.slots;
        appData.periodSlotMap = api.normalizePeriodSlotMap(collected.map, validation.slots);
        saveData();
        refreshAllClassPeriodSelects();
        const selector = getTimetableTeacherSelectorFromUi();
        if (selector) {
            renderTimetableView(selector);
        }
        closeModal();
        showSyncToast(t('saved'), false);
    });
}

function refreshAllClassPeriodSelects() {
    if (elements.classPeriod) {
        upgradeClassPeriodFieldToSelect(elements.classPeriod);
    }
    document.querySelectorAll('.class-period-by-day').forEach((sel) => {
        const val = sel.value;
        sel.innerHTML = buildClassPeriodSelectInnerHtml(val);
    });
    document.querySelectorAll('.class-teacher-placement-row select.class-teacher-placement-period').forEach((sel) => {
        const val = sel.value;
        sel.innerHTML = buildClassPeriodSelectInnerHtml(val);
    });
}

function initTimetableExport() {
    const btn = document.getElementById('timetableExportXlsBtn');
    if (!btn || btn.dataset.timetableInit) {
        return;
    }
    btn.dataset.timetableInit = '1';
    btn.addEventListener('click', async () => {
        const selector = getTimetableTeacherSelectorFromUi();
        if (!selector) {
            alert(t('timetableSelectTeacher'));
            return;
        }
        const api = getTimetableApi();
        const exportApi = typeof CCPTimetableExport !== 'undefined' ? CCPTimetableExport : null;
        if (!api || !exportApi) {
            alert(t('timetableExportExcelFailed'));
            return;
        }
        const lang = currentLanguage === 'ko' ? 'ko' : 'en';
        const grid = api.buildTeacherWeeklyGrid(appData, selector, { lang });
        btn.disabled = true;
        try {
            await exportApi.exportTeacherTimetableXlsx(grid, {
                lang,
                filename: grid.teacherName || selector.displayName || 'timetable',
                calendarName: appData.calendarName || '',
                termStart: appData.termStart || '',
                timeHeader: t('timetableTimeHeader'),
                homeroomLineLabel: t('timetableHomeroomLabel')
            });
        } catch (err) {
            console.error('Timetable export failed:', err);
            alert(t('timetableExportExcelFailed'));
        } finally {
            btn.disabled = false;
        }
    });
}

function initTimetableTabListeners() {
    initTimetablePeriodSchedule();
    initTimetableExport();
    const teacherSearch = document.getElementById('timetableTeacherSearch');
    if (teacherSearch && !teacherSearch.dataset.timetableInit) {
        teacherSearch.dataset.timetableInit = '1';
        teacherSearch.addEventListener('input', () => renderTimetableTeacherList());
    }
    const classSearch = document.getElementById('timetableClassListSearch');
    if (classSearch && !classSearch.dataset.timetableInit) {
        classSearch.dataset.timetableInit = '1';
        classSearch.addEventListener('input', () => {
            const selector = getTimetableTeacherSelectorFromUi();
            if (selector) {
                renderTimetableClassList(selector);
            }
        });
    }
    const myBtn = document.getElementById('timetableMyScheduleBtn');
    if (myBtn && !myBtn.dataset.timetableInit) {
        myBtn.dataset.timetableInit = '1';
        myBtn.addEventListener('click', () => {
            const me = typeof TeamAuth !== 'undefined' ? TeamAuth.getUser() : null;
            if (!me || !me.id) {
                return;
            }
            const teachers = listTimetableTeachers();
            let row = teachers.find((r) => r.userId === me.id);
            if (!row) {
                row = { userId: me.id, displayName: me.displayName || me.email || me.id };
            }
            selectTimetableTeacher({ userId: row.userId, displayName: row.displayName });
        });
    }
    const printBtn = document.getElementById('timetablePrintBtn');
    if (printBtn && !printBtn.dataset.timetableInit) {
        printBtn.dataset.timetableInit = '1';
        printBtn.addEventListener('click', () => openTimetablePrintOptionsModal());
    }
    initTimetablePrintControls();
}

function initHomeworkTabListeners() {
    initDailySummaryPrintControls();
    if (!debouncedSaveHomeworkGrading && typeof debounce === 'function') {
        debouncedSaveHomeworkGrading = debounce(() => persistHomeworkTextareaToSyllabus('grading'), 600);
        debouncedSaveHomeworkAssign = debounce(() => persistHomeworkTextareaToSyllabus('assign'), 600);
    }
    const search = document.getElementById('homeworkClassListSearch');
    if (search && !search.dataset.homeworkInit) {
        search.dataset.homeworkInit = '1';
        search.addEventListener('input', () => renderHomeworkClassList());
    }
    const refreshBtn = document.getElementById('homeworkRefreshSyllabiBtn');
    if (refreshBtn && !refreshBtn.dataset.homeworkInit) {
        refreshBtn.dataset.homeworkInit = '1';
        refreshBtn.addEventListener('click', () => {
            if (syncAllClassSyllabusRowsFromCalendar()) {
                renderHomeworkEditor();
                setAppStatusMessage(t('homeworkTabSyllabiRefreshed'), false);
            }
        });
    }
    const openClassBtn = document.getElementById('homeworkOpenClassBtn');
    if (openClassBtn && !openClassBtn.dataset.homeworkInit) {
        openClassBtn.dataset.homeworkInit = '1';
        openClassBtn.addEventListener('click', () => {
            const id = appData.ui.homeworkTabClassId;
            if (id) {
                navigateToTab('syllabus', { classId: id });
            }
        });
    }
    const gradingTa = document.getElementById('homeworkGradingText');
    if (gradingTa && !gradingTa.dataset.homeworkInit) {
        gradingTa.dataset.homeworkInit = '1';
        gradingTa.addEventListener('input', () => debouncedSaveHomeworkGrading());
        gradingTa.addEventListener('blur', () => persistHomeworkTextareaToSyllabus('grading'));
    }
    const assignTa = document.getElementById('homeworkAssignText');
    if (assignTa && !assignTa.dataset.homeworkInit) {
        assignTa.dataset.homeworkInit = '1';
        assignTa.addEventListener('input', () => debouncedSaveHomeworkAssign());
        assignTa.addEventListener('blur', () => persistHomeworkTextareaToSyllabus('assign'));
    }
    const copyGrading = document.getElementById('homeworkCopyGradingBtn');
    if (copyGrading && !copyGrading.dataset.homeworkInit) {
        copyGrading.dataset.homeworkInit = '1';
        copyGrading.addEventListener('click', async () => {
            const state = homeworkEditorState;
            const classData = state?.classId
                ? appData.classes.find((c) => c.id === state.classId)
                : null;
            const body = document.getElementById('homeworkGradingText')?.value || '';
            const formatted = classData && state?.packet
                ? formatHomeworkPasteBlock(body, classData, state.packet, 'grading')
                : body;
            showHomeworkCopyStatus(await copyTextToClipboard(formatted));
        });
    }
    const copyAssign = document.getElementById('homeworkCopyAssignBtn');
    if (copyAssign && !copyAssign.dataset.homeworkInit) {
        copyAssign.dataset.homeworkInit = '1';
        copyAssign.addEventListener('click', async () => {
            const state = homeworkEditorState;
            const classData = state?.classId
                ? appData.classes.find((c) => c.id === state.classId)
                : null;
            const body = document.getElementById('homeworkAssignText')?.value || '';
            const formatted = classData && state?.packet
                ? formatHomeworkPasteBlock(body, classData, state.packet, 'assign')
                : body;
            showHomeworkCopyStatus(await copyTextToClipboard(formatted));
        });
    }
    const copyDueDate = document.getElementById('homeworkCopyDueDateBtn');
    if (copyDueDate && !copyDueDate.dataset.homeworkInit) {
        copyDueDate.dataset.homeworkInit = '1';
        copyDueDate.addEventListener('click', async () => {
            const dueDate = homeworkEditorState?.packet?.dueDate || '';
            if (!dueDate) {
                return;
            }
            showHomeworkCopyStatus(await copyTextToClipboard(dueDate));
        });
    }
    const copyBoth = document.getElementById('homeworkCopyBothBtn');
    if (copyBoth && !copyBoth.dataset.homeworkInit) {
        copyBoth.dataset.homeworkInit = '1';
        copyBoth.addEventListener('click', async () => {
            const state = homeworkEditorState;
            const classData = state?.classId
                ? appData.classes.find((c) => c.id === state.classId)
                : null;
            const packet = state?.packet;
            const gBody = document.getElementById('homeworkGradingText')?.value || '';
            const aBody = document.getElementById('homeworkAssignText')?.value || '';
            const g = classData && packet
                ? formatHomeworkPasteBlock(gBody, classData, packet, 'grading')
                : gBody.trim();
            const a = classData && packet
                ? formatHomeworkPasteBlock(aBody, classData, packet, 'assign')
                : aBody.trim();
            const due = packet?.dueDate || '';
            const combined = [
                '=== ' + t('homeworkTabGradingTitle') + ' ===',
                g.trim(),
                '',
                '=== ' + t('homeworkTabAssignTitle') + ' ===',
                t('homeworkTabDueLabel') + ': ' + due,
                a.trim()
            ].join('\n');
            showHomeworkCopyStatus(await copyTextToClipboard(combined));
        });
    }
}

function openClassEditor(classData, context, options = {}) {
    if (isTeamCalendarViewOnly() && !classData) {
        if (isTeamAutoLockOnLoginPending()) {
            return;
        }
        showLockFlash(t('teamReadOnlySave'), false);
        warnEditRequiresLockOnce();
        return;
    }
    void ensureExtensionScriptsLoaded()
        .then(() => openClassEditorAfterLoad(classData, context, options))
        .catch((err) => {
            console.error(err);
            showSyncToast(t('syllabusModuleMissing'), true);
        });
}

function openClassEditorAfterLoad(classData, context, options = {}) {
    const ctx = context || 'tab';
    populateClassForm(classData, options);
    if (ctx === 'tab') {
        navigateToTab('classes');
        mountClassForm('tab');
        updateClassEditorEmptyState();
        renderClassList();
    } else {
        mountClassForm('modal');
        openModal(elements.classModal);
    }
}

function openEventEditor(holidayData, context, options = {}) {
    if (isTeamCalendarViewOnly() && !holidayData) {
        if (isTeamAutoLockOnLoginPending()) {
            return;
        }
        showLockFlash(t('teamReadOnlySave'), false);
        warnEditRequiresLockOnce();
        return;
    }
    const ctx = context || 'tab';
    populateHolidayForm(holidayData, options);
    if (ctx === 'tab') {
        navigateToTab('events');
        mountHolidayForm('tab');
        updateEventEditorEmptyState();
        renderEventList();
    } else {
        mountHolidayForm('modal');
        openModal(elements.holidayModal);
    }
}

