function getCalendarOptionsTermSelector() {
    const termSelector = document.querySelector('#topBarDetails .term-selector');
    if (!termSelector || termSelector.closest('#teamCalendarRow')) {
        return null;
    }
    return termSelector;
}

function cleanupMisplacedKrHolidayControls() {
    const teamRow = document.getElementById('teamCalendarRow');
    if (!teamRow) {
        return;
    }
    teamRow.querySelectorAll('#fetchKrHolidaysBtn, #krHolidaysSourceHint').forEach((el) => el.remove());
}

function ensureKrHolidaysSourceHint() {
    if (document.getElementById('krHolidaysSourceHint')) {
        return;
    }
    const termSelector = getCalendarOptionsTermSelector();
    if (!termSelector) {
        return;
    }
    const hint = document.createElement('p');
    hint.id = 'krHolidaysSourceHint';
    hint.className = 'kr-holidays-source-hint';
    hint.setAttribute('data-i18n', 'krHolidaysSourceHint');
    hint.textContent = t('krHolidaysSourceHint');
    const footer = document.getElementById('termSelectorFooter') || termSelector;
    footer.appendChild(hint);
}

function ensureKrHolidaysImportButton() {
    if (document.getElementById('fetchKrHolidaysBtn')) {
        return;
    }
    const termSelector = getCalendarOptionsTermSelector();
    if (!termSelector) {
        return;
    }
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'fetchKrHolidaysBtn';
    btn.className = 'btn btn-outline';
    btn.setAttribute('data-i18n', 'fetchKrHolidays');
    btn.textContent = t('fetchKrHolidays');
    btn.addEventListener('click', importKoreanPublicHolidays);
    const footer = document.getElementById('termSelectorFooter') || termSelector;
    footer.appendChild(btn);
}

function warnIfOpenedFromNetworkFile() {
    if (window.location.protocol !== 'file:') {
        return;
    }
    const banner = document.getElementById('openFromDriveBanner');
    if (banner) {
        banner.style.display = 'block';
    }
}

function getBookIdForClass(classData) {
    const effective = getEffectiveClassForViewer(classData) || classData;
    if (!effective || !window.CCPBooksEditor || !window.CCPBooksEditor.deriveBookKey) {
        return null;
    }
    if (effective.curriculumId) {
        const cid = String(effective.curriculumId).trim();
        if (window.CCPBooksEditor && window.CCPBooksEditor.isNoCurriculum(cid)) {
            return null;
        }
        return cid;
    }
    const def = getClassTypeDefinitionById(effective.classTypeId);
    if (def) {
        return window.CCPBooksEditor.deriveBookKey(def);
    }
    return null;
}

function getBookIdForSelectedHomeworkClass() {
    ensureUiState();
    const classId = appData.ui.homeworkTabClassId;
    if (!classId) {
        return null;
    }
    const classData = appData.classes.find((c) => c.id === classId);
    return classData ? getBookIdForClass(classData) : null;
}

function renderHomeworkSourceBook(classData) {
    const row = document.getElementById('homeworkSourceBookRow');
    const nameEl = document.getElementById('homeworkSourceBookName');
    const editBtn = document.getElementById('homeworkEditBookBtn');
    if (!row || !nameEl) {
        return;
    }
    const bookId = getBookIdForClass(classData);
    if (!bookId || !window.CCPBooksEditor) {
        row.hidden = true;
        return;
    }
    const book = window.CCPBooksEditor.getBookById(bookId, appData);
    row.hidden = false;
    nameEl.textContent = book ? book.name : bookId;
    if (editBtn) {
        editBtn.dataset.bookId = bookId;
    }
}

async function openWorkspacePage(tab, bookId, options = {}) {
    if (typeof CalendarSync !== 'undefined' && CalendarSync.flushPendingSave) {
        try {
            await CalendarSync.flushPendingSave();
        } catch (err) {
            if (err.status !== 423) {
                console.warn('Flush before content expand failed:', err);
            }
        }
    }
    const isBooks = tab === 'books';
    const zoneId = isBooks ? APP_ZONE_CLASSES : APP_ZONE_SCHEDULE;
    const segment = isBooks ? 'curriculum' : 'homework';
    document.documentElement.setAttribute('data-content-expanded', '1');
    updateContentExpandChrome();
    const navOpts = { ...options };
    if (bookId) {
        navOpts.curriculumId = bookId;
    }
    ensureUiState();
    const classId = options.classId || appData.ui.homeworkTabClassId;
    if (classId && segment === 'homework') {
        navOpts.classId = classId;
    }
    navigateToZone(zoneId, segment, navOpts);
}

async function reloadWorkspaceCalendar() {
    if (typeof CalendarSync === 'undefined' || !teamSyncEnabled) {
        return;
    }
    const id = CalendarSync.getActiveCalendarId();
    if (!id) {
        return;
    }
    const doc = await CalendarSync.loadCalendar(id);
    applyServerDocument(doc);
    refreshWorkspaceHomeworkUi();
    const banner = document.getElementById('workspaceRemoteBanner');
    if (banner) {
        banner.hidden = true;
    }
    CalendarSync.state.remoteNewer = false;
    const label = document.getElementById('workspaceCalendarLabel');
    if (label) {
        label.textContent = appData.calendarName || '';
    }
    setAppStatusMessage(t('syncReload') || 'Reloaded', false);
}

if (typeof window !== 'undefined') {
    window.openWorkspacePage = openWorkspacePage;
    window.openNotesPage = openNotesPage;
    window.getCurrentClassContext = getCurrentClassContext;
    window.reloadNotesCalendar = reloadNotesCalendar;
    window.clearViewAsSessionDayNotes = clearViewAsSessionDayNotes;
}

function initActiveContextUi() {
    if (typeof CCPCohortContextChip !== 'undefined') {
        CCPCohortContextChip.init({
            getAppData: () => appData,
            t,
            onCohortCleared() {
                renderClassList();
                renderEventList();
                renderHomeworkClassList();
            }
        });
    }
    if (typeof CCPActiveContext !== 'undefined' && CCPActiveContext.subscribe) {
        CCPActiveContext.subscribe((detail) => {
            if (!detail || detail.cohortId === undefined) {
                return;
            }
            if (typeof CCPCohortContextChip !== 'undefined') {
                CCPCohortContextChip.render();
            }
            renderClassList();
            renderEventList();
            renderHomeworkClassList();
        });
    }
}

document.addEventListener('DOMContentLoaded', async () => {
    setupClipboardNormalizeHandlers();
    if (document.body.classList.contains('workspace-page')) {
        return;
    }
    if (document.body.classList.contains('notes-page')) {
        return;
    }
    const useTeamSync = hasTeamSyncStatusEl();
    try {
        try {
            if (typeof CCPTemplateLoader !== 'undefined' && CCPTemplateLoader.ensureTemplatesLoaded) {
                await CCPTemplateLoader.ensureTemplatesLoaded();
            }
            initAppShellFromTemplates();
            refreshMountedFormElementRefs();
        } catch (err) {
            console.error('Template load failed:', err);
            if (useTeamSync) {
                updateTeamSyncStatus('error', t('errorReadingFile'));
            }
            alert(t('errorReadingFile') || 'Could not load editor templates. Check your connection and refresh.');
            return;
        }
        if (useTeamSync) {
            updateTeamSyncStatus('connecting');
            scheduleTeamSyncBootWatchdog();
        }
        ensureClassFormExtendedMarkup();
        repairCorruptedLangToggleButton();
        setupTeamLockButtons();
        setupTeamLockPendingButtons();
        setupTeamLockDebugPanel();
        loadLanguage();
        loadTheme();
        warnIfOpenedFromNetworkFile();
        if (typeof TeamAuth !== 'undefined' && location.protocol !== 'file:') {
            try {
                await TeamAuth.ensure();
                setupTeamUserBar();
                if (
                    typeof CCPSessionRestore !== 'undefined' &&
                    CCPSessionRestore.maybeRestoreLastPath &&
                    CCPSessionRestore.maybeRestoreLastPath()
                ) {
                    return;
                }
            } catch (e) {
                if (e && e.message === 'redirect') {
                    return;
                }
            }
        }
        setupSchoolGradeControls();
        setupSimsonLevelControls();
        setupClassMeetingDaysUI();
        bindClassScheduleInputsForSyllabusDistribute();
        initAppStoreAndRenderOrchestrator();
        initListViewModules();
        initActiveContextUi();
        loadData();
        ensureUiState();
        if (typeof CCPActiveContext !== 'undefined' && CCPActiveContext.resolveDefaults) {
            CCPActiveContext.resolveDefaults(appData);
        }
        if (typeof TeamAuth !== 'undefined' && location.protocol !== 'file:') {
            try {
                await ensureTeamTeacherAccountsLoaded();
                if (linkClassTeachersToTeamAccounts()) {
                    saveData();
                }
            } catch (_) {
                /* accounts list optional */
            }
        }
        initializeTermStart();
        cleanupMisplacedKrHolidayControls();
        ensureKrHolidaysImportButton();
        ensureKrHolidaysSourceHint();
        setupEventListeners();
        initAppTabs();
        setupAppModalA11y();
        document.body.dataset.activeTab = getActiveTab();
        initCalendarContextMenu();
        initDayNotesUi();
        initNowClassPopup();
        initTermSettingsToggle();
        initViewportTier();
        initCalendarViewToggle();
        initAppChromeStickyTop();
        applyLanguage();

        appShellBootComplete = true;

        if (useTeamSync) {
            showCalendarBootLoading(true);
            await runTeamSyncBoot();
        } else {
            teamSyncCalendarHydrated = true;
            renderCalendar();
            requestAnimationFrame(syncAppChromeStickyTop);
        }

        const savedTab = getActiveTab();
        showSavedTabPanelsOnly(savedTab);

        try {
            restoreAppSessionState();
        } catch (restoreErr) {
            console.error('restoreAppSessionState failed:', restoreErr);
        }
        refreshActiveTabAfterHydration();
        updateSetupGuideBanner();
        syncSetupTabsVisibility();
        if (typeof CCPSessionRestore !== 'undefined' && CCPSessionRestore.capturePageSession) {
            CCPSessionRestore.capturePageSession();
        }

        scheduleIdleTabPrefetch();
    } finally {
        if (useTeamSync) {
            teamSyncInitialBootDone = true;
            if (!teamSyncBootAttempted) {
                clearTeamSyncBootWatchdog();
                finishTeamSyncBoot();
            }
        }
    }
});

function initializeTermStart() {
    ensureUiState();
    ensureTermStartData();
    if (elements.termStart) {
        elements.termStart.value = normalizeTermStartDate(appData.termStart);
    }
    if (elements.termEnd) {
        elements.termEnd.value = getResolvedTermEndISO();
        appData.termEnd = elements.termEnd.value;
    }
    if (elements.termUseAutoTermEnd) {
        elements.termUseAutoTermEnd.checked = appData.useAutoTermEnd !== false;
    }
    applyCalendarTermEndUiState();
    if (elements.termMonthCount) {
        elements.termMonthCount.value = String(getTermMonthCount());
    }
    if (elements.calendarName) {
        elements.calendarName.value = appData.calendarName || '';
    }
    updateCalendarTitle();
    updateTopBarCalendarLabel();
    applyVisibilityFiltersToDom();
    syncHolidaysFromEvents();
}

// ============================================
// Event Listeners Setup
// ============================================
let openHeaderFixedPopoverId = null;
let fixedAnchorPopoverRepositionRaf = 0;

function getHeaderFixedPopoverTrigger(popoverId) {
    return document.querySelector(`[aria-controls="${popoverId}"]`);
}

function positionHeaderFixedPopover(trigger, popover, align) {
    return positionFixedPopoverBelowTrigger(trigger, popover, {
        align: align === 'left' ? 'left' : 'right',
        minMaxHeight: 120
    });
}

function repositionLessonFilterPopoverIfOpen(force) {
    if (!isLessonFilterPopoverOpen()) {
        return;
    }
    const popover = document.getElementById('lessonFilterPopover');
    const btn = document.getElementById('lessonFilterBtn');
    if (!popover || !btn) {
        return;
    }
    const rect = btn.getBoundingClientRect();
    if (!isFixedAnchorTriggerVisible(rect)) {
        closeLessonFilterPopover();
        return;
    }
    if (!force && shouldSkipFixedAnchorReposition('lessonFilterPopover', rect)) {
        return;
    }
    if (!positionFixedPopoverBelowTrigger(btn, popover, { align: 'left', minMaxHeight: 280 })) {
        closeLessonFilterPopover();
    }
}

function repositionEventApplicabilityPopoverIfOpen(force) {
    if (!isEventApplicabilityPopoverOpen()) {
        return;
    }
    const popover = document.getElementById('eventApplicabilityPopover');
    const btn = document.getElementById('eventApplicabilityFilterBtn');
    if (!popover || !btn) {
        return;
    }
    const rect = btn.getBoundingClientRect();
    if (!isFixedAnchorTriggerVisible(rect)) {
        closeEventApplicabilityPopover();
        return;
    }
    if (!force && shouldSkipFixedAnchorReposition('eventApplicabilityPopover', rect)) {
        return;
    }
    if (!positionFixedPopoverBelowTrigger(btn, popover, { align: 'left', minMaxHeight: 280 })) {
        closeEventApplicabilityPopover();
    }
}

function repositionAllFixedAnchorPopovers(force) {
    repositionOpenHeaderFixedPopover(force);
    repositionLessonFilterPopoverIfOpen(force);
    repositionEventApplicabilityPopoverIfOpen(force);
}

function repositionOpenHeaderFixedPopover(force) {
    if (!openHeaderFixedPopoverId) {
        return;
    }
    const popover = document.getElementById(openHeaderFixedPopoverId);
    const trigger = getHeaderFixedPopoverTrigger(openHeaderFixedPopoverId);
    if (!popover || !trigger || popover.hidden) {
        return;
    }
    const rect = trigger.getBoundingClientRect();
    if (!isFixedAnchorTriggerVisible(rect)) {
        closeHeaderFixedPopover(openHeaderFixedPopoverId);
        return;
    }
    if (!force && shouldSkipFixedAnchorReposition(openHeaderFixedPopoverId, rect)) {
        return;
    }
    const align = popover.dataset.popoverAlign === 'left' ? 'left' : 'right';
    if (!positionHeaderFixedPopover(trigger, popover, align)) {
        closeHeaderFixedPopover(openHeaderFixedPopoverId);
    }
}

function scheduleRepositionAllFixedAnchorPopovers() {
    const hasOpen =
        openHeaderFixedPopoverId ||
        isLessonFilterPopoverOpen() ||
        isEventApplicabilityPopoverOpen();
    if (!hasOpen) {
        return;
    }
    if (fixedAnchorPopoverRepositionRaf) {
        return;
    }
    fixedAnchorPopoverRepositionRaf = requestAnimationFrame(() => {
        fixedAnchorPopoverRepositionRaf = 0;
        repositionAllFixedAnchorPopovers(false);
    });
}

function scheduleForcedRepositionAllFixedAnchorPopovers() {
    if (fixedAnchorPopoverRepositionRaf) {
        cancelAnimationFrame(fixedAnchorPopoverRepositionRaf);
        fixedAnchorPopoverRepositionRaf = 0;
    }
    repositionAllFixedAnchorPopovers(true);
}

function closeHeaderFixedPopover(popoverId) {
    const popover = document.getElementById(popoverId);
    const trigger = getHeaderFixedPopoverTrigger(popoverId);
    if (!popover) {
        return;
    }
    popover.hidden = true;
    if (trigger) {
        trigger.setAttribute('aria-expanded', 'false');
    }
    clearFixedAnchorPopoverRectCache(popoverId);
    if (openHeaderFixedPopoverId === popoverId) {
        openHeaderFixedPopoverId = null;
    }
}

function isHeaderFixedPopoverOpen(popoverId) {
    const popover = document.getElementById(popoverId);
    return popover && !popover.hidden;
}

function openHeaderFixedPopover(trigger, popover, align) {
    if (!trigger || !popover) {
        return;
    }
    const rect = trigger.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
        return;
    }
    if (openHeaderFixedPopoverId && openHeaderFixedPopoverId !== popover.id) {
        closeHeaderFixedPopover(openHeaderFixedPopoverId);
    }
    popover.hidden = false;
    trigger.setAttribute('aria-expanded', 'true');
    openHeaderFixedPopoverId = popover.id;
    clearFixedAnchorPopoverRectCache(popover.id);
    scheduleForcedRepositionAllFixedAnchorPopovers();
    requestAnimationFrame(() => {
        if (!isHeaderFixedPopoverOpen(popover.id)) {
            return;
        }
        repositionOpenHeaderFixedPopover(true);
    });
}

function setupHeaderFixedPopoverDismiss() {
    if (document.body.dataset.headerFixedPopoverDismissBound === '1') {
        return;
    }
    document.body.dataset.headerFixedPopoverDismissBound = '1';
    document.addEventListener('click', (e) => {
        if (!openHeaderFixedPopoverId) {
            return;
        }
        const popover = document.getElementById(openHeaderFixedPopoverId);
        const trigger = getHeaderFixedPopoverTrigger(openHeaderFixedPopoverId);
        const target = e.target;
        if (
            popover &&
            (popover.contains(target) || (trigger && trigger.contains(target)))
        ) {
            return;
        }
        closeHeaderFixedPopover(openHeaderFixedPopoverId);
    });
    window.addEventListener('resize', scheduleForcedRepositionAllFixedAnchorPopovers);
    window.addEventListener('scroll', scheduleRepositionAllFixedAnchorPopovers, { passive: true });
    if (window.visualViewport) {
        window.visualViewport.addEventListener('resize', scheduleForcedRepositionAllFixedAnchorPopovers);
        window.visualViewport.addEventListener('scroll', scheduleRepositionAllFixedAnchorPopovers);
    }
    document.querySelectorAll('.app-header-unified__tools, .app-tab-subnav-wrap').forEach((el) => {
        el.addEventListener('scroll', scheduleRepositionAllFixedAnchorPopovers, { passive: true });
    });
    const appTopBar = document.getElementById('appTopBar');
    if (appTopBar && typeof ResizeObserver !== 'undefined') {
        const headerPopoverResizeObserver = new ResizeObserver(() => {
            scheduleForcedRepositionAllFixedAnchorPopovers();
        });
        headerPopoverResizeObserver.observe(appTopBar);
    }
}

function setupHeaderFixedPopover(popoverId, align) {
    const popover = document.getElementById(popoverId);
    const trigger = getHeaderFixedPopoverTrigger(popoverId);
    if (!popover || !trigger || trigger.dataset.headerPopoverBound === '1') {
        return;
    }
    trigger.dataset.headerPopoverBound = '1';
    popover.dataset.popoverAlign = align === 'left' ? 'left' : 'right';
    if (popover.parentElement !== document.body) {
        document.body.appendChild(popover);
    }
    trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        if (isHeaderFixedPopoverOpen(popoverId)) {
            closeHeaderFixedPopover(popoverId);
        } else {
            openHeaderFixedPopover(trigger, popover, align);
        }
    });
}

function setupHeaderDropdowns() {
    document.querySelectorAll('.header-dropdown-panel .header-dropdown-item').forEach((el) => {
        if (el.dataset.dropdownBound === '1') {
            return;
        }
        el.dataset.dropdownBound = '1';
        el.addEventListener('click', () => {
            const fixedPopover = el.closest('.header-fixed-popover');
            if (fixedPopover && fixedPopover.id) {
                closeHeaderFixedPopover(fixedPopover.id);
            }
            const details = el.closest('details.header-dropdown');
            if (details) {
                details.open = false;
            }
        });
    });
}

function setupEventListeners() {
    setupHeaderFixedPopoverDismiss();
    setupHeaderFixedPopover('teamAccountPopover', 'right');
    setupHeaderFixedPopover('teamCalendarPopover', 'left');
    setupHeaderDropdowns();

    // Calendar Name Change
    elements.calendarName.addEventListener('input', (e) => {
        appData.calendarName = e.target.value;
        updateActiveTeamCalendarOptionLabel();
        updateCalendarTitle();
        updateTopBarCalendarLabel();
        saveData();
    });
    
    // Term Start Change
    elements.termStart.addEventListener('change', (e) => {
        appData.termStart = normalizeTermStartDate(e.target.value);
        syncCalendarTermEndFromSettings();
        updateTermSettingsToggleSummary();
        saveData();
        renderCalendar();
    });

    if (elements.termEnd) {
        elements.termEnd.addEventListener('change', (e) => {
            appData.termEnd = e.target.value;
            appData.useAutoTermEnd = false;
            if (elements.termUseAutoTermEnd) {
                elements.termUseAutoTermEnd.checked = false;
            }
            applyCalendarTermEndUiState();
            updateTermSettingsToggleSummary();
            saveData();
            renderCalendar();
        });
    }

    if (elements.termUseAutoTermEnd) {
        elements.termUseAutoTermEnd.addEventListener('change', (e) => {
            appData.useAutoTermEnd = e.target.checked;
            applyCalendarTermEndUiState();
            if (appData.useAutoTermEnd) {
                syncCalendarTermEndFromSettings();
            }
            updateTermSettingsToggleSummary();
            saveData();
            renderCalendar();
        });
    }

    if (elements.termMonthCount) {
        elements.termMonthCount.addEventListener('change', (e) => {
            const parsed = parseInt(e.target.value, 10);
            if (!Number.isNaN(parsed)) {
                appData.termMonthCount = Math.min(
                    SCHEDULE_CONFIG.maxTermMonthCount,
                    Math.max(SCHEDULE_CONFIG.minTermMonthCount, parsed)
                );
            }
            if (appData.useAutoTermEnd !== false) {
                syncCalendarTermEndFromSettings();
            }
            updateTermSettingsToggleSummary();
            saveData();
            renderCalendar();
        });
    }

    VISIBILITY_FILTER_FIELDS.forEach(({ uiId }) => {
        const el = document.getElementById(uiId);
        if (el && !el.dataset.delegatedVisibility) {
            el.dataset.delegatedVisibility = '1';
        }
    });

    function handleVisibilityFilterChange() {
        ensureUiState();
        dispatchUiMerge({ visibilityFilters: readVisibilityFiltersFromDom() });
        saveUiStateToLocalStorage();
        updateLessonFilterButtonLabel();
        invalidateScheduleCache();
        requestUiCalendarRender();
    }

    if (typeof CCPAppDelegation !== 'undefined') {
        CCPAppDelegation.initAppDelegation({
            setPrintCalendarVisibilityCheckboxes,
            setPrintSummaryOptionCheckboxes,
            openWorkspaceBooks: () => {
                void openWorkspacePage('books');
            },
            applyPrintUseCalendarFiltersState,
            visibilityFilterIds: VISIBILITY_FILTER_FIELDS.map(({ uiId }) => uiId),
            onVisibilityFilterChange: handleVisibilityFilterChange,
            printSummaryOptionIds: PRINT_SUMMARY_OPTION_IDS,
            savePrintSummaryVisibilityToUi
        });
        CCPAppDelegation.initDynamicPanelDelegation({
            commitLessonFiltersFromPopover,
            commitEventApplicabilityFromPopover
        });
    } else {
        VISIBILITY_FILTER_FIELDS.forEach(({ uiId }) => {
            const el = document.getElementById(uiId);
            if (!el || el.dataset.visibilityBound === '1') {
                return;
            }
            el.dataset.visibilityBound = '1';
            el.addEventListener('change', handleVisibilityFilterChange);
        });
    }

    const fetchKrBtn = document.getElementById('fetchKrHolidaysBtn');
    if (fetchKrBtn) {
        fetchKrBtn.addEventListener('click', importKoreanPublicHolidays);
    }
    
    // Language Toggle
    document.getElementById('langToggleBtn').addEventListener('click', toggleLanguage);
    const themeToggleBtn = document.getElementById('themeToggleBtn');
    if (themeToggleBtn) {
        themeToggleBtn.addEventListener('click', toggleTheme);
    }
    const nowPopupToggleBtn = document.getElementById('nowClassPopupToggleBtn');
    if (nowPopupToggleBtn) {
        nowPopupToggleBtn.addEventListener('click', () => {
            setNowClassPopupEnabled(!getNowClassPopupEnabled());
        });
    }
    
    // Button Clicks
    document.getElementById('addClassBtn')?.addEventListener('click', () => openClassEditor(null, 'tab'));
    document.getElementById('addHolidayBtn').addEventListener('click', () => openEventEditor(null, 'calendar-popout'));
    setupImportDestinationModal();
    setupChangePasswordModal();
    setupEditDisplayNameModal();
    document.getElementById('importFile').addEventListener('change', importData);
    setupLessonFilterUi();
    setupEventApplicabilityFilterUi();
    document.getElementById('clearDataBtn').addEventListener('click', clearAllData);
    setupPrintSyllabusControls();
    setupDataTabCalendarBackup();
    setupPrintColorModeIsolation();
    setupAppPrintOpenerSafeties();
    setupCalendarTileTypographyObserver();

    // Modal Close Buttons
    document.getElementById('closeClassModal')?.addEventListener('click', () => closeModal(elements.classModal));
    document.getElementById('closeHolidayModal')?.addEventListener('click', () => closeModal(elements.holidayModal));
    setupClassTeachersFormDelegation();
    // Form Submissions
    elements.classForm?.addEventListener('submit', handleClassSubmit);
    elements.holidayForm?.addEventListener('submit', handleHolidaySubmit);
    elements.printForm?.addEventListener('submit', handlePrint);
    
    // Delete Buttons
    const deleteClassBtnEl = document.getElementById('deleteClassBtn');
    if (deleteClassBtnEl) {
        deleteClassBtnEl.addEventListener('click', deleteClass);
        elements.deleteClassBtn = deleteClassBtnEl;
    }
    elements.deleteHolidayBtn?.addEventListener('click', deleteHoliday);
    const deleteHolidayFooterBtn = document.getElementById('deleteHolidayBtnFooter');
    if (deleteHolidayFooterBtn) {
        deleteHolidayFooterBtn.addEventListener('click', deleteHoliday);
    }

    const printUseCalendarFilters = document.getElementById('printUseCalendarFilters');
    if (printUseCalendarFilters) {
        printUseCalendarFilters.dataset.delegatedPrint = '1';
    }

    const syllabusRefreshHeaderBtn = document.getElementById('syllabusRefreshHeaderBtn');
    if (syllabusRefreshHeaderBtn && !syllabusRefreshHeaderBtn.dataset.bound) {
        syllabusRefreshHeaderBtn.dataset.bound = '1';
        syllabusRefreshHeaderBtn.addEventListener('click', () => refreshSyllabusFromCalendar());
    }
    const syllabusRefreshCurriculumHeaderBtn = document.getElementById('syllabusRefreshCurriculumHeaderBtn');
    if (syllabusRefreshCurriculumHeaderBtn && !syllabusRefreshCurriculumHeaderBtn.dataset.bound) {
        syllabusRefreshCurriculumHeaderBtn.dataset.bound = '1';
        syllabusRefreshCurriculumHeaderBtn.addEventListener('click', () => refreshSyllabusFromCurriculum());
    }
    
    // Holiday "All Classes" toggle
    elements.holidayAllClasses?.addEventListener('change', (e) => {
        if (e.target.checked) {
            closeEventApplicabilityPopover();
            eventApplicabilityDraft = { ...EMPTY_EVENT_APPLICABILITY };
        } else if (!holidayHasAnyTargetFilter(eventApplicabilityDraft)) {
            eventApplicabilityDraft = getDefaultAllSelectedEventApplicability();
        }
        syncEventApplicabilityUiFromDraft();
    });
    
    // Class Name autocomplete + auto-fill levels when name exactly matches a class
    const onClassNameInput = debounce(() => {
        showClassNameSuggestions();
        autoFillLevelsFromExactClassNameMatch();
    }, 300);
    elements.className.addEventListener('input', onClassNameInput);
    elements.className.addEventListener('focus', showClassNameSuggestions);
    elements.className.addEventListener('blur', () => {
        // Delay hiding to allow click on suggestion
        setTimeout(hideClassNameSuggestions, 200);
    });
    
    // Handle keyboard navigation in autocomplete
    elements.className.addEventListener('keydown', handleAutocompleteKeydown);

    elements.classLevelCustom.addEventListener(
        'input',
        debounce(autoFillLevelPresetFromCustomLevelInput, 250)
    );

    if (elements.classLevel) {
        elements.classLevel.addEventListener('change', handleClassLevelPresetChange);
    }
    
    // Holiday "Date Range" toggle
    elements.holidayIsRange.addEventListener('change', (e) => {
        const isRange = e.target.checked;
        elements.holidaySingleDate.style.display = isRange ? 'none' : 'block';
        elements.holidayDateRange.style.display = isRange ? 'grid' : 'none';
        if (isRange) {
            if (!elements.holidayStartDate.value && elements.holidayDate.value) {
                elements.holidayStartDate.value = elements.holidayDate.value;
            }
            syncHolidayRangeEndFromStart();
        }
    });

    if (elements.holidayStartDate) {
        elements.holidayStartDate.addEventListener('change', () => {
            if (elements.holidayIsRange.checked) {
                syncHolidayRangeEndFromStart();
            }
        });
    }

    if (elements.eventType) {
        elements.eventType.addEventListener('change', applyEventTypeDefaultColors);
    }
    
    // Custom Schedule toggle
    elements.customScheduleEnabled.addEventListener('change', (e) => {
        elements.customScheduleSection.style.display = e.target.checked ? 'block' : 'none';
        syncPeriodByDayUi();
    });

    if (elements.classTypeSelect) {
        elements.classTypeSelect.addEventListener('change', () => {
            syncDeleteCustomClassTypeButtonVisibility();
            updateCompressionUiForScheduleModel();
            syncClassTypeHint();
        });
    }
    setupClassCurriculumControls();
    if (elements.openClassTypeModalBtn) {
        elements.openClassTypeModalBtn.addEventListener('click', openClassTypeManagerModal);
    }
    if (elements.deleteCustomClassTypeBtn) {
        elements.deleteCustomClassTypeBtn.addEventListener('click', deleteSelectedCustomClassType);
    }
    if (elements.classTypeForm) {
        elements.classTypeForm.addEventListener('submit', handleClassTypeFormSubmit);
    }
    const closeClassTypeModalBtn = document.getElementById('closeClassTypeModal');
    if (closeClassTypeModalBtn && elements.classTypeModal) {
        closeClassTypeModalBtn.addEventListener('click', () => closeModal(elements.classTypeModal));
    }
    if (elements.classTypeModal) {
        bindModalBackdropClose(elements.classTypeModal);
    }

    // Total lessons change
    elements.classTotalLessons.addEventListener('input', () => {
        const totalLessons = getTotalLessonsValue();
        const currentDates = getCustomLessonDatesFromInputs();
        const currentMerges = getSelectedCompressionMerges();
        renderCustomLessonDates(totalLessons, currentDates);
        renderCompressionOptions(totalLessons, currentMerges);
    });

    elements.addBookMonthRowBtn.addEventListener('click', () => addBookPeriodRow(null));
    elements.fillBooksFromDefaultBtn.addEventListener('click', fillBooksFromTermDefaultBook);
    document.querySelectorAll('input[name="compressionMode"]').forEach((radio) => {
        radio.addEventListener('change', () => syncCompressionSectionsForMode());
    });

    elements.classUseAutoTermEnd.addEventListener('change', () => {
        applyClassTermEndUiState();
        if (elements.classUseAutoTermEnd.checked) {
            syncClassTermEndAndBooks();
        }
    });
    elements.classStartDate.addEventListener('change', () => {
        if (elements.classUseAutoTermEnd.checked) {
            syncClassTermEndAndBooks();
        }
    });
    elements.classTermMonths.addEventListener('input', () => {
        if (elements.classUseAutoTermEnd.checked) {
            syncClassTermEndAndBooks();
        }
    });
    const classTermEndMode = document.getElementById('classTermEndMode');
    if (classTermEndMode && !classTermEndMode.dataset.bound) {
        classTermEndMode.dataset.bound = '1';
        classTermEndMode.addEventListener('change', () => {
            if (elements.classUseAutoTermEnd.checked) {
                syncClassTermEndAndBooks();
            }
        });
    }
    
    // Close modals on backdrop click (safe for text selection dragging)
    [elements.classModal, elements.holidayModal, elements.classTypeModal, elements.printOptionsModal,
        elements.timetablePrintOptionsModal]
        .filter(Boolean)
        .forEach(bindModalBackdropClose);

    const closePrintOptionsModalBtn = document.getElementById('closePrintOptionsModal');
    if (closePrintOptionsModalBtn && elements.printOptionsModal) {
        closePrintOptionsModalBtn.addEventListener('click', closePrintOptionsModal);
    }
    
    // Close modals on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            closeModal(elements.classModal);
            closeModal(elements.holidayModal);
            if (elements.classTypeModal) {
                closeModal(elements.classTypeModal);
            }
            if (elements.printOptionsModal) {
                closePrintOptionsModal();
            }
            if (elements.timetablePrintOptionsModal) {
                closeTimetablePrintOptionsModal();
            }
        }
    });
    
    // Popup handling
    document.addEventListener('mousemove', handlePopupPosition);
}

// ============================================
// Modal Functions
// ============================================
const EXCLUSIVE_MODAL_IDS = [
    'defaultClassEditorModal',
    'changePasswordModal',
    'editDisplayNameModal',
    'classModal',
    'holidayModal',
    'printOptionsModal',
    'timetablePrintOptionsModal',
    'dailySummaryPrintModal',
    'conflictModal',
    'newCalendarModal',
    'classTypeModal',
    'cohortEditorModal'
];

const CCPModalRegistry = {
    _entries: new Map(),
    register(id, options = {}) {
        if (typeof CCPModal !== 'undefined') {
            CCPModal.register(id, options);
            this._entries.set(id, { el: document.getElementById(id), onClose: options.onClose || null });
            return;
        }
        const el = document.getElementById(id);
        if (!el) {
            return;
        }
        this._entries.set(id, { el, onClose: options.onClose || null });
        if (options.backdropClose !== false) {
            bindModalBackdropClose(el);
        }
        if (options.a11y !== false && options.onClose) {
            bindModalA11y(el, options.onClose);
        }
    },
    open(id, triggerEl) {
        const entry = this._entries.get(id);
        if (!entry || !entry.el) {
            return;
        }
        openModal(entry.el, triggerEl);
    },
    close(id) {
        const entry = this._entries.get(id);
        if (!entry) {
            return;
        }
        if (typeof entry.onClose === 'function') {
            entry.onClose();
        } else {
            closeModal(entry.el);
        }
    },
    init() {
        this.register('classModal', { onClose: () => closeModal(elements.classModal) });
        this.register('holidayModal', { onClose: () => closeModal(elements.holidayModal) });
        this.register('printOptionsModal', { onClose: () => closePrintOptionsModal() });
        this.register('timetablePrintOptionsModal', { onClose: () => closeTimetablePrintOptionsModal() });
        this.register('dailySummaryPrintModal', { onClose: () => closeDailySummaryPrintModal() });
        this.register('conflictModal', {
            onClose: () => closeModal(document.getElementById('conflictModal'))
        });
        this.register('newCalendarModal', {
            onClose: () => closeModal(document.getElementById('newCalendarModal'))
        });
        if (elements.classTypeModal) {
            this.register('classTypeModal', { onClose: () => closeModal(elements.classTypeModal) });
        }
        this.register('cohortEditorModal', {
            onClose: () => closeModal(document.getElementById('cohortEditorModal'))
        });
    }
};

function closeExclusiveModalsExcept(keepModal) {
    EXCLUSIVE_MODAL_IDS.forEach((id) => {
        const el = document.getElementById(id);
        if (el && el !== keepModal && el.classList.contains('active')) {
            closeModal(el);
        }
    });
}

function getModalFocusables(modal) {
    if (typeof CCPModal !== 'undefined') {
        return CCPModal.getModalFocusables(modal);
    }
    if (!modal) {
        return [];
    }
    return Array.from(
        modal.querySelectorAll(
            'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
        )
    ).filter((el) => el.offsetParent !== null || modal.contains(el));
}

function bindModalA11y(modal, onClose) {
    if (typeof CCPModal !== 'undefined') {
        CCPModal.bindA11y(modal, onClose);
        return;
    }
    if (!modal || modal.dataset.a11yBound === '1') {
        return;
    }
    modal.dataset.a11yBound = '1';
    modal.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            onClose();
        }
        if (e.key === 'Tab') {
            const focusables = getModalFocusables(modal);
            if (focusables.length < 2) {
                return;
            }
            const first = focusables[0];
            const last = focusables[focusables.length - 1];
            if (e.shiftKey && document.activeElement === first) {
                e.preventDefault();
                last.focus();
            } else if (!e.shiftKey && document.activeElement === last) {
                e.preventDefault();
                first.focus();
            }
        }
    });
}

function setupAppModalA11y() {
    CCPModalRegistry.init();
}

function openModal(modal, triggerEl) {
    if (!modal) {
        return;
    }
    if (modal.id && EXCLUSIVE_MODAL_IDS.includes(modal.id)) {
        closeExclusiveModalsExcept(modal);
    }
    const trigger = triggerEl || document.activeElement;
    if (trigger && trigger instanceof HTMLElement) {
        modal._ccpTrigger = trigger;
    }
    modal.removeAttribute('hidden');
    modal.style.removeProperty('display');
    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    if (!modal.getAttribute('role')) {
        modal.setAttribute('role', 'dialog');
        modal.setAttribute('aria-modal', 'true');
    }
    const focusables = getModalFocusables(modal);
    if (focusables.length) {
        focusables[0].focus();
    }
}

function closeModal(modal) {
    if (!modal) {
        return;
    }
    const trigger = modal._ccpTrigger;
    modal.classList.remove('active');
    modal.style.removeProperty('display');
    modal.setAttribute('aria-hidden', 'true');
    modal.setAttribute('hidden', '');
    if (modal === elements.holidayModal) {
        closeEventApplicabilityPopover();
    }
    if (trigger && typeof trigger.focus === 'function') {
        try {
            trigger.focus();
        } catch (_) {
            /* ignore */
        }
    }
    delete modal._ccpTrigger;
}

/**
 * Close modal on backdrop interaction only when press+release both start on the overlay.
 * Otherwise, dragging to select text can end on the dimmed area and incorrectly fire click there.
 */
function bindModalBackdropClose(modal) {
    if (typeof CCPModal !== 'undefined') {
        CCPModal.bindBackdropClose(modal, () => closeModal(modal));
        return;
    }
    let pressStartedOnBackdrop = false;
    modal.addEventListener('pointerdown', (e) => {
        pressStartedOnBackdrop = e.target === modal;
    });
    modal.addEventListener('click', (e) => {
        if (e.target === modal && pressStartedOnBackdrop) {
            closeModal(modal);
        }
        pressStartedOnBackdrop = false;
    });
}

function renderSyllabusUnitsRows(units = []) {
    if (!elements.syllabusUnitsRows) return;
    elements.syllabusUnitsRows.innerHTML = '';
    (units || []).forEach(unit => {
        addSyllabusUnitRow(
            unit.title || '',
            unit.notes || '',
            unit.id,
            unit.speakingPages || '',
            unit.writingPages || ''
        );
    });
}

function addSyllabusUnitRow(title = '', notes = '', unitId = null, speakingPages = '', writingPages = '') {
    if (!elements.syllabusUnitsRows) return;
    const row = document.createElement('div');
    row.className = 'syllabus-unit-row';
    row.dataset.unitId = unitId || generateId();
    const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    row.innerHTML = `
        <div class="syllabus-unit-title-wrap">
            <label class="syllabus-unit-field syllabus-unit-field-title">
                <span>${escapeHtml(t('syllabusUnitTitle'))}</span>
                <input type="text" class="syllabus-unit-title" value="${esc(title)}">
            </label>
            <button type="button" class="btn btn-outline btn-small syllabus-unit-remove" aria-label="Remove">×</button>
        </div>
        <div class="syllabus-unit-field">
            <label>${escapeHtml(t('syllabusUnitSpeakingPages'))}</label>
            <textarea class="syllabus-unit-speaking" rows="2">${esc(speakingPages)}</textarea>
        </div>
        <div class="syllabus-unit-field">
            <label>${escapeHtml(t('syllabusUnitWritingPages'))}</label>
            <textarea class="syllabus-unit-writing" rows="2">${esc(writingPages)}</textarea>
        </div>
        <div class="syllabus-unit-field syllabus-unit-field-full">
            <label>${escapeHtml(t('notes'))}</label>
            <textarea class="syllabus-unit-notes" rows="2">${esc(notes)}</textarea>
        </div>
    `;
    row.querySelector('.syllabus-unit-remove').addEventListener('click', () => row.remove());
    elements.syllabusUnitsRows.appendChild(row);
}

function collectSyllabusUnitsFromForm() {
    if (!elements.syllabusUnitsRows) return [];
    const rows = elements.syllabusUnitsRows.querySelectorAll('.syllabus-unit-row');
    return Array.from(rows).map(row => {
        const speakingEl = row.querySelector('.syllabus-unit-speaking');
        const writingEl = row.querySelector('.syllabus-unit-writing');
        const notesEl = row.querySelector('.syllabus-unit-notes');
        return {
            id: row.dataset.unitId || generateId(),
            title: (row.querySelector('.syllabus-unit-title')?.value || '').trim(),
            notes: notesEl ? (notesEl.value || '').trim() : '',
            speakingPages: speakingEl ? (speakingEl.value || '').trim() : '',
            writingPages: writingEl ? (writingEl.value || '').trim() : ''
        };
    }).filter(u => u.title.length > 0);
}

function getSyllabusModule() {
    return typeof window !== 'undefined' ? window.CCPSyllabus : null;
}

function buildJindoPrintTitle(classData, period) {
    if (!classData) {
        return '';
    }
    const parts = [];
    const name = (classData.name || '').trim();
    if (name) {
        parts.push(name);
    }
    const periodBook = period && period.book ? String(period.book).trim() : '';
    const book = periodBook || (classData.book || '').trim();
    if (book) {
        parts.push(book);
    }
    const days = formatMeetingDaysSummary(classData);
    if (days && days !== '—') {
        parts.push(t('syllabusPrintMeetingDaysSuffix').replace('{days}', days));
    }
    return parts.join(' · ');
}

function normalizeDebateSyllabusExportScope(scope) {
    if (scope === 'allPeriods' || scope === 'singlePeriod') {
        return scope;
    }
    return 'full';
}

function formatDebatePeriodDateRange(rangeStartDate, rangeEndDate) {
    if (!rangeStartDate || !rangeEndDate) {
        return '';
    }
    return `${formatDateDisplay(rangeStartDate)} – ${formatDateDisplay(rangeEndDate)}`;
}

function countSyllabusLessonRows(rows) {
    return (rows || []).filter((row) => (row.kind || 'lesson') === 'lesson' && row.date).length;
}

function buildSyllabusSectionsFromClassRows(classData, rows, exportOptions = {}) {
    const meta = getSyllabusSectionMeta(classData);
    const scope = normalizeDebateSyllabusExportScope(exportOptions.debatePeriodScope);

    if (!classUsesDebateCompression(classData) || scope === 'full') {
        return [{
            classData,
            rows,
            classTitle: meta.classTitle,
            jindoTitle: buildJindoPrintTitle(classData),
            tableYear: meta.tableYear,
            subtitle: meta.subtitle,
            termRange: meta.termRange
        }];
    }

    const mod = getSyllabusModule();
    const debateApi = typeof globalThis !== 'undefined' ? globalThis.CCPDebatePeriods : null;
    if (!mod || typeof mod.filterRowsForDebatePeriod !== 'function' || !debateApi) {
        return [{
            classData,
            rows,
            classTitle: meta.classTitle,
            jindoTitle: buildJindoPrintTitle(classData),
            tableYear: meta.tableYear,
            subtitle: meta.subtitle,
            termRange: meta.termRange
        }];
    }

    let periods = debateApi.enumerateDebatePeriodsInTerm(classData) || [];
    if (scope === 'singlePeriod' && exportOptions.debatePeriodId) {
        periods = periods.filter((p) => p.id === exportOptions.debatePeriodId);
    }

    const sections = [];
    periods.forEach((period) => {
        const filtered = mod.filterRowsForDebatePeriod(
            rows,
            period.rangeStartDate,
            period.rangeEndDate
        );
        if (countSyllabusLessonRows(filtered) === 0) {
            return;
        }
        sections.push({
            classData,
            rows: filtered,
            classTitle: meta.classTitle,
            jindoTitle: buildJindoPrintTitle(classData, period),
            tableYear: meta.tableYear,
            subtitle: meta.subtitle,
            termRange: formatDebatePeriodDateRange(period.rangeStartDate, period.rangeEndDate),
            periodMeta: {
                periodId: period.id,
                book: period.book,
                rangeStartDate: period.rangeStartDate,
                rangeEndDate: period.rangeEndDate
            }
        });
    });
    return sections;
}

function getStudentSyllabusExportOptionsFromDialog() {
    const fullEl = document.getElementById('studentSyllabusScopeFull');
    const allEl = document.getElementById('studentSyllabusScopeAllPeriods');
    const oneEl = document.getElementById('studentSyllabusScopeOnePeriod');
    const periodEl = document.getElementById('studentSyllabusPrintPeriod');
    let scope = 'full';
    if (oneEl?.checked) {
        scope = 'singlePeriod';
    } else if (allEl?.checked) {
        scope = 'allPeriods';
    } else if (fullEl?.checked) {
        scope = 'full';
    }
    scope = normalizeDebateSyllabusExportScope(scope);
    const options = { debatePeriodScope: scope };
    if (scope === 'singlePeriod' && periodEl && periodEl.value) {
        options.debatePeriodId = periodEl.value;
    }
    return options;
}

function renderStudentSyllabusPeriodPicker(classData) {
    const select = document.getElementById('studentSyllabusPrintPeriod');
    if (!select || !classData) {
        return;
    }
    const debateApi = typeof globalThis !== 'undefined' ? globalThis.CCPDebatePeriods : null;
    const periods = debateApi ? (debateApi.enumerateDebatePeriodsInTerm(classData) || []) : [];
    const prev = select.value;
    select.innerHTML = periods.map((p) => {
        const book = (p.book || classData.book || '').trim() || '—';
        const label = `${p.startDate}: ${book}`;
        return `<option value="${escapeAttr(p.id)}">${escapeHtml(label)}</option>`;
    }).join('');
    if (prev && periods.some((p) => p.id === prev)) {
        select.value = prev;
    }
}

function syncStudentSyllabusPrintDialogForClass(classData) {
    const isDebate = classData && classUsesDebateCompression(classData);
    const allRow = document.getElementById('studentSyllabusScopeAllPeriodsRow');
    const oneRow = document.getElementById('studentSyllabusScopeOnePeriodRow');
    const hint = document.getElementById('studentSyllabusPeriodHint');
    const fullEl = document.getElementById('studentSyllabusScopeFull');
    if (allRow) {
        allRow.hidden = !isDebate;
    }
    if (oneRow) {
        oneRow.hidden = !isDebate;
    }
    if (hint) {
        hint.hidden = !isDebate;
    }
    if (!isDebate && fullEl) {
        fullEl.checked = true;
    }
    if (isDebate) {
        renderStudentSyllabusPeriodPicker(classData);
    }
    syncStudentSyllabusPeriodPickVisibility();
}

function syncStudentSyllabusPeriodPickVisibility() {
    const oneEl = document.getElementById('studentSyllabusScopeOnePeriod');
    const pickRow = document.getElementById('studentSyllabusPeriodPickRow');
    if (pickRow) {
        pickRow.hidden = !oneEl?.checked;
    }
}

function getSyllabusSnapshotForStudentPrint() {
    let classId = elements.classId && elements.classId.value;
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        classId = appData.ui.syllabusTabClassId || classId;
    }
    if (!classId) {
        return null;
    }
    const saved = appData.classes.find((c) => c.id === classId);
    if (!saved) {
        return null;
    }
    return {
        snapshot: {
            ...saved,
            id: classId,
            syllabusUnits: collectSyllabusUnitsFromForm(),
            syllabusGeneralNotes: getSyllabusGeneralNotesFromForm() || saved.syllabusGeneralNotes || ''
        },
        classId
    };
}

function openStudentSyllabusPrintDialog() {
    const packed = getSyllabusSnapshotForStudentPrint();
    if (!packed) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const mod = getSyllabusModule();
    if (!mod) {
        alert(t('syllabusModuleMissing'));
        return;
    }
    const rows = resolveSyllabusRowsForPrint(packed.snapshot);
    if (!rows.length) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    syncStudentSyllabusPrintDialogForClass(packed.snapshot);
    const modal = document.getElementById('studentSyllabusPrintModal');
    if (modal) {
        openModal(modal);
    }
}

function closeStudentSyllabusPrintModal() {
    const modal = document.getElementById('studentSyllabusPrintModal');
    if (modal) {
        closeModal(modal);
    }
}

function printStudentSyllabusFromDialog(e) {
    if (e) {
        e.preventDefault();
    }
    const packed = getSyllabusSnapshotForStudentPrint();
    if (!packed) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const mod = getSyllabusModule();
    if (!mod) {
        alert(t('syllabusModuleMissing'));
        return;
    }
    const { snapshot } = packed;
    const syllabusRows = resolveSyllabusRowsForPrint(snapshot);
    if (!syllabusRows.length) {
        alert(t('syllabusTableEmptyHint'));
        return;
    }
    const exportOptions = getStudentSyllabusExportOptionsFromDialog();
    const sections = buildSyllabusSectionsFromClassRows(snapshot, syllabusRows, exportOptions);
    if (!sections.length) {
        alert(t('studentSyllabusEmptyPeriod'));
        return;
    }
    const sectionMeta = getSyllabusSectionMeta(snapshot);
    const meta = {
        title: (appData.calendarName && appData.calendarName.trim()) || t('syllabusTables'),
        subtitle: appData.termStart ? appData.termStart : ''
    };
    const labels = {
        ...getSyllabusStudentPrintLabels(snapshot),
        classTitle: sectionMeta.classTitle,
        jindoTitle: buildJindoPrintTitle(snapshot),
        tableYear: sectionMeta.tableYear,
        subtitle: sectionMeta.subtitle,
        termRange: sectionMeta.termRange
    };
    closeStudentSyllabusPrintModal();
    printSyllabusDocument(
        mod.renderSyllabusDocumentHtml(meta, sections, labels),
        sectionMeta.classTitle
    );
}

function setupStudentSyllabusPrintUi() {
    const form = document.getElementById('studentSyllabusPrintForm');
    if (form && !form.dataset.bound) {
        form.dataset.bound = '1';
        form.addEventListener('submit', printStudentSyllabusFromDialog);
    }
    document.getElementById('studentSyllabusPrintCancelBtn')?.addEventListener('click', closeStudentSyllabusPrintModal);
    document.getElementById('closeStudentSyllabusPrintModal')?.addEventListener('click', closeStudentSyllabusPrintModal);
    ['studentSyllabusScopeFull', 'studentSyllabusScopeAllPeriods', 'studentSyllabusScopeOnePeriod'].forEach((id) => {
        document.getElementById(id)?.addEventListener('change', syncStudentSyllabusPeriodPickVisibility);
    });
}

