function debateLessonGroupIncludesDay(group, dayNum) {
    if (!group || !Array.isArray(group.days)) {
        return false;
    }
    return group.days.includes(dayNum);
}

/**
 * Debate only: tag lessons so syllabus rows pull Combined or month-bridge templates.
 */
function annotateDebateTemplateHints(classData, items) {
    if (!classUsesDebateCompression(classData) || !Array.isArray(items)) {
        return;
    }
    const dated = items.filter((item) => item.date
        && !item.__syllabusHoliday
        && !item.__syllabusExtraPeriod
        && !item.__syllabusOverflowIntro
        && !item.__syllabusUnscheduled);
    dated.forEach((item) => {
        if (item.compressed && item.group
            && item.group.start === 2 && item.group.end === 3) {
            item.__debateTemplateKey = 'day2and3combined';
        }
    });
    const periodOrder = [];
    dated.forEach((item) => {
        const key = item.periodId || item.periodStartDate || item.monthKey;
        if (key && !periodOrder.includes(key)) {
            periodOrder.push(key);
        }
    });
    periodOrder.forEach((periodKey, periodIndex) => {
        const inPeriod = dated.filter((item) => {
            const key = item.periodId || item.periodStartDate || item.monthKey;
            return key === periodKey;
        });
        if (!inPeriod.length) {
            return;
        }
        const last = inPeriod[inPeriod.length - 1];
        const nextPeriodKey = periodOrder[periodIndex + 1];
        const hasNextPeriod = !!(nextPeriodKey && dated.some((item) => {
            const key = item.periodId || item.periodStartDate || item.monthKey;
            return key === nextPeriodKey;
        }));
        const isLastPeriodInTerm = periodIndex === periodOrder.length - 1;
        if ((hasNextPeriod || isLastPeriodInTerm)
            && debateLessonGroupIncludesDay(last.group, 4)
            && last.__debateTemplateKey !== 'day2and3combined') {
            last.__debateTemplateKey = 'day4and1bridge';
        }
    });
    if (dated.length) {
        const termLast = dated[dated.length - 1];
        if (debateLessonGroupIncludesDay(termLast.group, 4)
            && termLast.__debateTemplateKey !== 'day2and3combined') {
            termLast.__debateTemplateKey = 'day4and1bridge';
        }
    }
}

function lessonsForSyllabusBuild(classData) {
    const { slots, unscheduledLessonNumbers } = buildSyllabusTimelineForClass(classData);
    const items = [];

    slots.forEach(slot => {
        if (slot.kind === 'holiday') {
            items.push({
                date: slot.date,
                monthKey: slot.monthKey,
                label: '',
                __syllabusHoliday: true
            });
            return;
        }
        if (slot.kind === 'extra') {
            items.push({
                date: slot.date,
                monthKey: slot.monthKey,
                label: '',
                __syllabusExtraPeriod: true
            });
            return;
        }
        const lesson = slot.lesson || {};
        const dateStr = slot.date || (lesson.date instanceof Date ? formatDateISO(lesson.date) : lesson.date);
        items.push({
            ...lesson,
            date: dateStr,
            monthKey: slot.monthKey || lesson.monthKey || (dateStr ? dateStr.slice(0, 7) : ''),
            label: slot.label || lesson.label
        });
    });

    if (unscheduledLessonNumbers.length > 0) {
        items.push({ __syllabusOverflowIntro: true });
        unscheduledLessonNumbers.forEach(lessonNum => {
            items.push({
                __syllabusUnscheduled: true,
                lessonNum,
                label: getSequentialLessonLabel(classData, lessonNum)
            });
        });
    }

    const totalLessons = sanitizeTotalLessons(classData.totalLessons || 8);
    const skipped = getSkippedLessonsFromClass(classData, totalLessons);
    const placedNums = new Set();
    items.forEach(item => {
        if (item.group && item.group.days) {
            item.group.days.forEach(d => placedNums.add(d));
        }
    });
    skipped.forEach(lessonNum => {
        if (!placedNums.has(lessonNum)) {
            items.push({
                __syllabusSkipped: true,
                lessonNum,
                label: getSequentialLessonLabel(classData, lessonNum)
            });
        }
    });

    annotateDebateTemplateHints(classData, items);
    return items;
}

/** General notes from Curriculum tab (saved sessions, team default, or factory). */
function getCurriculumGeneralNotesForClass(classData) {
    const editor = window.CCPBooksEditor;
    if (!editor || !classData || editor.isNoCurriculum(classData.curriculumId)) {
        return '';
    }
    const level = (classData.levelPreset || classData.levelCustom || classData.level || '').trim();
    let curriculumId = (classData.curriculumId || '').trim();
    if (!curriculumId) {
        return '';
    }
    if (editor.isDebateCurriculum(curriculumId) || curriculumId === editor.DEBATE_CURRICULUM_ID) {
        curriculumId = editor.normalizeDebateCurriculumId(curriculumId, level, appData) || curriculumId;
    }
    const presetId = editor.resolvePresetFromLevelAndBook(level, curriculumId, appData)
        || classData.classTypeId
        || '';
    return editor.getCurriculumSyllabusGeneralNotes(curriculumId, presetId, appData);
}

function getSyllabusRowTemplatesForClass(classData) {
    if (!classData) {
        return [];
    }
    const editor = window.CCPBooksEditor;
    if (editor) {
        const level = (classData.levelPreset || classData.levelCustom || classData.level || '').trim();
        let curriculumId = (classData.curriculumId || '').trim();
        if (!curriculumId && classData.classTypeId) {
            curriculumId = getBookIdForClass(classData) || '';
        }
        if (editor.isDebateCurriculum(curriculumId) || curriculumId === editor.DEBATE_CURRICULUM_ID) {
            curriculumId = editor.normalizeDebateCurriculumId(curriculumId, level, appData) || curriculumId;
        }
        if (curriculumId && !editor.isNoBookCurriculum(curriculumId)) {
            const fromBook = editor.getTemplatesForBookId(curriculumId, appData);
            if (fromBook.length) {
                return fromBook;
            }
        }
    }
    const def = getClassTypeDefinitionById(classData.classTypeId);
    return def && Array.isArray(def.defaultSyllabusRowTemplates)
        ? def.defaultSyllabusRowTemplates
        : [];
}

function buildGeneratedSyllabusRows(classData) {
    const mod = getSyllabusModule();
    if (!mod) {
        return [];
    }
    const rowTemplates = getSyllabusRowTemplatesForClass(classData);
    const hooks = {
        ...syllabusScheduleHooks(),
        rowTemplates
    };
    if (rowTemplates.length && window.CCPSyllabusTemplates) {
        hooks.templateIndexes = window.CCPSyllabusTemplates.buildTemplateIndexes(rowTemplates);
    }
    return mod.buildSyllabusRowsFromSchedule(
        classData,
        lessonsForSyllabusBuild(classData),
        hooks
    );
}

function localizeSyllabusRowsForCurrentLanguage(rows, classData) {
    const mod = getSyllabusModule();
    return (rows || []).map((row) => {
        if (row.kind === 'holiday' && row.date && classData) {
            const hol = getBlockingEventForClass(row.date, classData);
            if (!hol || !hol.name) {
                return row;
            }
            const d = parseISODateLocal(row.date);
            let shortDate = '';
            if (!Number.isNaN(d.getTime())) {
                shortDate = mod && typeof mod.formatSyllabusShortDate === 'function'
                    ? mod.formatSyllabusShortDate(d)
                    : formatDateDisplay(row.date);
            }
            return { ...row, planTitle: `${shortDate} ${hol.name}`.trim() };
        }
        return row;
    });
}

function getSyllabusRowsForClass(classData, options = {}) {
    invalidateScheduleCache();
    const generated = buildGeneratedSyllabusRows(classData);
    const saved = Array.isArray(classData.syllabusRows) ? classData.syllabusRows : [];
    const mergeOpts = options.refreshScheduleTitles ? { refreshScheduleTitles: true } : undefined;
    let rows;
    if (options.preferMerged && saved.length > 0) {
        const mod = getSyllabusModule();
        if (mod) {
            rows = mod.mergeSyllabusRows(saved, generated, mergeOpts);
        } else {
            rows = saved;
        }
    } else if (saved.length > 0 && !options.preferFresh) {
        rows = saved;
    } else {
        rows = generated;
    }
    return enrichSyllabusRowColors(
        localizeSyllabusRowsForCurrentLanguage(rows, classData),
        classData
    );
}

/** Rows for syllabus print: form edits + calendar colors. */
function resolveSyllabusRowsForPrint(snapshot) {
    const mod = getSyllabusModule();
    if (!mod) {
        return [];
    }
    if (elements.syllabusTableBody) {
        const formRows = collectSyllabusRowsFromForm();
        const generated = buildGeneratedSyllabusRows(snapshot);
        return enrichSyllabusRowColors(mod.mergeSyllabusRows(formRows, generated), snapshot);
    }
    return getSyllabusRowsForClass(snapshot, { preferMerged: true });
}

function buildClassSnapshotFromRecord(classData) {
    if (!classData) {
        return {};
    }
    return { ...classData };
}

/**
 * Curriculum → Class: read curriculum link (book + class type) from the class form.
 * @param {{ includeTeacherFields?: boolean }} [options]
 */
function resolveClassCurriculumLinkFromForm(options = {}) {
    const includeTeacherFields = options.includeTeacherFields !== false;
    const editor = window.CCPBooksEditor;
    const level = getClassFormCurriculumLevel();
    const curriculumBookSel = document.getElementById('classCurriculumBook');
    let curriculumId = (curriculumBookSel && curriculumBookSel.value)
        ? curriculumBookSel.value.trim()
        : '';
    const hiddenType = document.getElementById('classTypeIdHidden');
    const rawClassTypeId = (hiddenType && hiddenType.value)
        ? hiddenType.value
        : (elements.classTypeSelect ? (elements.classTypeSelect.value || '') : '');
    let classTypeId = resolveClassTypeId(rawClassTypeId) || rawClassTypeId;
    if (!curriculumId && classTypeId && editor) {
        curriculumId = getBookIdForClass({ classTypeId }) || '';
    }
    if (editor) {
        curriculumId = editor.normalizeCurriculumIdForStorage(curriculumId);
    }
    if (includeTeacherFields) {
        const teacherFields = collectClassTeacherFieldsForSave();
        if (teacherFields.classTypeId) {
            classTypeId = teacherFields.classTypeId;
        }
        if (teacherFields.curriculumId) {
            curriculumId = teacherFields.curriculumId;
        }
    } else if (editor && level && curriculumId
        && !editor.isNoCurriculum(curriculumId)
        && !editor.isNoBookCurriculum(curriculumId)) {
        const presetId = editor.resolvePresetFromLevelAndBook(level, curriculumId, appData);
        if (presetId) {
            classTypeId = presetId;
        }
    }
    return {
        curriculumId: curriculumId || '',
        classTypeId: classTypeId || '',
        level: level || ''
    };
}

function classCurriculumLinkKey(classData) {
    if (!classData) {
        return '';
    }
    const editor = window.CCPBooksEditor;
    const cid = String(classData.curriculumId || '').trim();
    const tid = String(classData.classTypeId || '').trim();
    if (editor && editor.isNoCurriculum(cid)) {
        return `none:${tid}`;
    }
    return `${cid}:${tid}`;
}

function classCurriculumLinkChanged(before, after) {
    return classCurriculumLinkKey(before) !== classCurriculumLinkKey(after);
}

/** Write curriculum book + class type from the class form onto the saved class record. */
function persistCurriculumLinkToSavedClass(classId, link) {
    const id = (classId || '').trim();
    if (!id || !link) {
        return;
    }
    const index = appData.classes.findIndex((c) => c.id === id);
    if (index === -1) {
        return;
    }
    const editor = window.CCPBooksEditor;
    const curriculumId = editor
        ? editor.normalizeCurriculumIdForStorage(link.curriculumId || '')
        : (link.curriculumId || '').trim();
    if (curriculumId) {
        appData.classes[index].curriculumId = curriculumId;
    }
    if (link.classTypeId) {
        appData.classes[index].classTypeId = link.classTypeId;
    }
    if (link.level && getSimsonLevelById(link.level)) {
        appData.classes[index].levelPreset = link.level;
    }
    saveData();
}

/** Class draft from form: schedule + curriculum link (overrides stale saved curriculumId). */
function buildClassDraftFromForm() {
    const snap = buildClassSnapshotFromForm();
    const link = resolveClassCurriculumLinkFromForm();
    snap.curriculumId = link.curriculumId;
    snap.classTypeId = link.classTypeId;
    if (link.level && getSimsonLevelById(link.level)) {
        snap.levelPreset = link.level;
    }
    const levelCustom = (elements.classLevelCustom && elements.classLevelCustom.value || '').trim();
    snap.levelCustom = levelCustom;
    snap.level = getClassLevelDisplayFromParts(snap.levelPreset, levelCustom);
    return snap;
}

function getSyllabusRowsForCurriculumPush(classData) {
    const classId = classData && classData.id;
    if (elements.syllabusTableBody && classId) {
        const openOnSyllabus = getActiveTab() === 'syllabus'
            && syllabusEditorMode === 'class'
            && appData.ui.syllabusTabClassId === classId;
        const openOnClassForm = elements.classId && elements.classId.value === classId;
        if (openOnSyllabus || openOnClassForm) {
            const fromForm = collectSyllabusRowsFromForm();
            if (fromForm.length) {
                return fromForm;
            }
        }
    }
    if (classData && Array.isArray(classData.syllabusRows) && classData.syllabusRows.length) {
        return classData.syllabusRows.slice();
    }
    return buildGeneratedSyllabusRows(classData);
}

/**
 * Class → Syllabus: merge curriculum session templates into syllabusRows via class link.
 * Templates always come from getSyllabusRowTemplatesForClass(classData) (never bypass class).
 */
function pushCurriculumToClassSyllabus(classData, options = {}) {
    const silent = !!options.silent;
    const skipConfirm = !!options.skipConfirm;
    const persist = options.persist !== false;
    const updateEditor = options.updateEditor !== false;
    const api = getSyllabusTemplatesApi();
    if (!api || !classData) {
        if (!silent) {
            alert(t('syllabusModuleMissing'));
        }
        return { ok: false, applied: 0, rows: null, cancelled: false };
    }
    const editor = window.CCPBooksEditor;
    if (editor && editor.isNoCurriculum(classData.curriculumId)) {
        if (!silent) {
            alert(t('refreshSyllabusFromCurriculumNoTemplates'));
        }
        return { ok: false, applied: 0, rows: null, cancelled: false };
    }
    const templates = getSyllabusRowTemplatesForClass(classData);
    if (!templates.length) {
        if (!silent) {
            alert(t('refreshSyllabusFromCurriculumNoTemplates'));
        }
        return { ok: false, applied: 0, rows: null, cancelled: false };
    }
    let rows = getSyllabusRowsForCurriculumPush(classData);
    if (!rows.length) {
        if (!silent) {
            alert(t('homeworkImportNoRows'));
        }
        return { ok: false, applied: 0, rows: null, cancelled: false };
    }
    const confirmMsg = options.confirmMessage || t('refreshSyllabusFromCurriculumConfirm');
    if (!skipConfirm && !silent && !confirm(confirmMsg)) {
        return { ok: false, applied: 0, rows: null, cancelled: true };
    }
    const result = api.applyRowTemplatesToSyllabusRows(rows, templates, {
        force: options.force !== false
    });
    const mergedRows = result.rows;
    const forceApply = options.force !== false;
    const copyGeneralNotes = options.copyGeneralNotes !== false;
    let generalNotes = null;
    if (forceApply && copyGeneralNotes && editor && !editor.isNoCurriculum(classData.curriculumId)) {
        generalNotes = getCurriculumGeneralNotesForClass(classData);
        classData.syllabusGeneralNotes = generalNotes;
    }
    if (persist && classData.id) {
        const index = appData.classes.findIndex((c) => c.id === classData.id);
        if (index !== -1) {
            appData.classes[index].syllabusRows = mergedRows;
            classData.syllabusRows = mergedRows;
            if (generalNotes !== null) {
                appData.classes[index].syllabusGeneralNotes = generalNotes;
            }
            saveData();
            updateClassSyllabusSummary(appData.classes[index]);
        }
    } else {
        classData.syllabusRows = mergedRows;
    }
    if (updateEditor && classData.id && elements.syllabusTableBody) {
        const onSyllabusTab = getActiveTab() === 'syllabus' && syllabusEditorMode === 'class';
        const openId = onSyllabusTab
            ? appData.ui.syllabusTabClassId
            : (elements.classId && elements.classId.value);
        if (openId === classData.id) {
            renderSyllabusEditorTable(mergedRows);
            if (generalNotes !== null) {
                setSyllabusGeneralNotesInForm(generalNotes);
            }
        }
    } else if (updateEditor && generalNotes !== null) {
        setSyllabusGeneralNotesInForm(generalNotes);
    }
    if (!result.applied) {
        if (!silent) {
            alert(t('refreshSyllabusFromCurriculumNone'));
        }
        return { ok: false, applied: 0, rows: mergedRows, cancelled: false };
    }
    if (!silent) {
        setAppStatusMessage(
            t('refreshSyllabusFromCurriculumDone').replace('{n}', String(result.applied)),
            false
        );
    }
    return { ok: true, applied: result.applied, rows: mergedRows, cancelled: false };
}

function getClassesUsingCurriculumIdForPipeline(curriculumId) {
    if (window.CCPClassCurriculumSlices && window.CCPClassCurriculumSlices.getClassesUsingCurriculumId) {
        return window.CCPClassCurriculumSlices.getClassesUsingCurriculumId(curriculumId, appData);
    }
    const editor = window.CCPBooksEditor;
    const norm = (cid) => {
        const raw = String(cid || '').trim();
        if (!raw) {
            return '';
        }
        return editor && editor.normalizeCurriculumIdForStorage
            ? editor.normalizeCurriculumIdForStorage(raw)
            : raw;
    };
    const target = norm(curriculumId);
    if (!target) {
        return [];
    }
    return (appData.classes || []).filter((c) => {
        if (norm(c.curriculumId) === target) {
            return true;
        }
        const rows = Array.isArray(c.classTeachers) ? c.classTeachers : [];
        return rows.some((row) => norm(row && row.curriculumId) === target);
    });
}

function hideCurriculumUpdatedBanner(options = {}) {
    const persist = options.persist !== false;
    pendingCurriculumBannerId = null;
    ensureUiState();
    appData.ui.pendingCurriculumSyllabiUpdateId = '';
    if (persist) {
        saveData();
    }
    scheduleTabWarningsRefresh();
}

function showCurriculumUpdatedBanner(curriculumId) {
    const id = (curriculumId || '').trim();
    if (!id) {
        hideCurriculumUpdatedBanner({ persist: false });
        return;
    }
    if (!window.CCPBooksEditor) {
        return;
    }
    const editor = window.CCPBooksEditor;
    if (editor.isNoCurriculum(id) || editor.isNoBookCurriculum(id)) {
        hideCurriculumUpdatedBanner();
        return;
    }
    const classes = getClassesUsingCurriculumIdForPipeline(id);
    if (!classes.length) {
        hideCurriculumUpdatedBanner();
        return;
    }
    pendingCurriculumBannerId = id;
    ensureUiState();
    const prevPending = appData.ui.pendingCurriculumSyllabiUpdateId;
    appData.ui.pendingCurriculumSyllabiUpdateId = id;
    if (prevPending !== id) {
        saveData();
    }
    scheduleCurriculumSyllabiUpdateNotification();
}

function refreshCurriculumUpdatedBanner() {
    ensureUiState();
    const id = (appData.ui.pendingCurriculumSyllabiUpdateId || '').trim();
    if (!id) {
        pendingCurriculumBannerId = null;
        scheduleTabWarningsRefresh();
        return;
    }
    showCurriculumUpdatedBanner(id);
}

function handleCurriculumUpdatedBannerAction() {
    const curriculumId = pendingCurriculumBannerId;
    if (!curriculumId) {
        return;
    }
    const classes = getClassesUsingCurriculumIdForPipeline(curriculumId);
    if (!classes.length) {
        hideCurriculumUpdatedBanner();
        return;
    }
    if (!confirm(t('curriculumUpdatedBatchConfirm').replace('{n}', String(classes.length)))) {
        return;
    }
    let updatedClassCount = 0;
    classes.forEach((cls) => {
        const draft = { ...cls };
        const result = pushCurriculumToClassSyllabus(draft, {
            skipConfirm: true,
            force: true,
            updateEditor: true,
            silent: true
        });
        if (result.ok) {
            updatedClassCount += 1;
        }
    });
    hideCurriculumUpdatedBanner({ persist: false });
    invalidateScheduleCache();
    saveData();
    renderCalendar();
    renderClassList();
    if (getActiveTab() === 'homework') {
        renderHomeworkEditor();
    }
    if (getActiveTab() === 'syllabus') {
        const selected = getSelectedSyllabusClass();
        if (selected) {
            renderSyllabusEditorTable(selected.syllabusRows || []);
        }
    }
    setAppStatusMessage(
        t('curriculumUpdatedBatchDone').replace('{n}', String(updatedClassCount)),
        false
    );
}

function buildClassSnapshotForSyllabusContext() {
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        const classData = getSelectedSyllabusClass();
        if (classData) {
            return buildClassSnapshotFromRecord(classData);
        }
    }
    if (elements.classId && elements.className) {
        return buildClassDraftFromForm();
    }
    const classData = getSelectedSyllabusClass();
    if (classData) {
        return buildClassSnapshotFromRecord(classData);
    }
    return buildClassDraftFromForm();
}

function buildClassSnapshotFromForm() {
    const id = elements.classId && elements.classId.value;
    const existing = id ? appData.classes.find(c => c.id === id) : null;
    const scheduleModel = getScheduleModelFromForm();
    const isDebateSchedule = scheduleModel === SCHEDULE_MODEL_DEBATE_MONTHLY;
    const isCustomSchedule = elements.customScheduleEnabled.checked;
    const compressionFields = collectClassCompressionForSave({ isDebateSchedule, isCustomSchedule });
    const totalLessons = getTotalLessonsValue();
    const meetingDays = readMeetingDaysFromFormScope('#classForm', MEETING_DAY_INPUT_CLASS);
    const normalizedMeetings = isCustomSchedule ? [] : normalizeMeetingDaysArray(meetingDays);
    return {
        ...(existing || {}),
        id: id || 'draft-syllabus',
        name: (elements.className.value || '').trim() || 'Class',
        classTypeId: elements.classTypeSelect ? elements.classTypeSelect.value : '',
        scheduleModel,
        startDate: elements.classStartDate.value,
        endDate: elements.classEndDate.value,
        totalLessons,
        meetingDays: normalizedMeetings,
        dayOfWeek: !isCustomSchedule && normalizedMeetings.length === 1 ? normalizedMeetings[0] : null,
        compressionMode: compressionFields.compressionMode,
        compressionMerges: compressionFields.compressionMerges,
        skippedLessons: compressionFields.skippedLessons,
        compressionMergesByMonth: existing?.compressionMergesByMonth,
        compressionMergesByPeriod: isDebateSchedule
            ? compressionFields.compressionMergesByPeriod
            : (existing?.compressionMergesByPeriod || {}),
        debateBookPeriods: isDebateSchedule ? collectDebateBookPeriodsFromForm() : (existing?.debateBookPeriods || []),
        customSchedule: isCustomSchedule ? {
            enabled: true,
            days: getCustomLessonDatesFromInputs(totalLessons)
        } : (existing?.customSchedule || null),
        syllabusUnits: collectSyllabusUnitsFromForm(),
        book: elements.classBook.value,
        grade: (elements.classGrade.value || '').trim(),
        levelPreset: elements.classLevel.value,
        levelCustom: (elements.classLevelCustom.value || '').trim(),
        lessonLabelMode: getLessonLabelModeForSave(),
        homeworkImportMode: getHomeworkImportModeForSave()
    };
}

function renderSyllabusEditorTable(rows) {
    if (!elements.syllabusTableBody) {
        return;
    }
    const mod = getSyllabusModule();
    const normalized = mod ? mod.normalizeRows(rows) : (rows || []);
    elements.syllabusTableBody.innerHTML = '';
    normalized.forEach(row => {
        const tr = document.createElement('tr');
        const rowKind = row.kind || 'lesson';
        const eventTypeClass = row.eventType ? ` syllabus-row-${row.eventType}` : '';
        tr.className = `syllabus-row syllabus-row-${rowKind}${eventTypeClass}`;
        tr.dataset.rowId = row.id;
        tr.dataset.rowKind = rowKind;
        tr.dataset.rowSource = row.source || 'generated';
        if (row.rowBg) {
            tr.dataset.rowBg = row.rowBg;
        }
        if (row.rowColor) {
            tr.dataset.rowColor = row.rowColor;
        }
        if (row.eventType) {
            tr.dataset.eventType = row.eventType;
        }
        if (row.date) {
            tr.dataset.rowDate = row.date;
        }
        if (row.monthKey) {
            tr.dataset.rowMonthKey = row.monthKey;
        }
        if (row.sessionNumber != null) {
            tr.dataset.rowSession = String(row.sessionNumber);
        }
        const lessonNum = row.lessonNumber != null && row.lessonNumber > 0
            ? row.lessonNumber
            : (rowKind === 'lesson' || rowKind === 'overflow' ? row.sessionNumber : 0);
        if (lessonNum > 0) {
            tr.dataset.rowLessonNumber = String(lessonNum);
        }
        if (row.overflowIntro === true) {
            tr.dataset.overflowIntro = '1';
        }
        const weekDisplay = row.weekLabel || (row.date && mod ? mod.getSchoolWeekLabel(row.date) : '');
        const isNote = row.kind === 'note';
        const titleReadonly = !isNote;
        tr.innerHTML = `
            <td class="syllabus-ed-week syllabus-col-week">${escapeHtml(weekDisplay)}</td>
            <td class="syllabus-ed-num syllabus-col-num">${row.sessionNumber > 0 ? row.sessionNumber : ''}</td>
            <td class="syllabus-col-plan"><input type="text" class="syllabus-ed-title" value="${escapeAttr(row.planTitle || '')}" ${titleReadonly ? 'readonly' : ''}></td>
            <td class="syllabus-col-pages"><textarea class="syllabus-ed-detail" rows="4"></textarea></td>
            <td class="syllabus-col-note"><textarea class="syllabus-ed-note" rows="2"></textarea></td>
            <td class="syllabus-col-actions"><button type="button" class="btn btn-outline btn-small syllabus-row-remove" aria-label="Remove">×</button></td>
        `;
        const detailEl = tr.querySelector('.syllabus-ed-detail');
        if (detailEl) {
            detailEl.value = row.planDetail || '';
        }
        const noteEl = tr.querySelector('.syllabus-ed-note');
        if (noteEl) {
            noteEl.value = row.note || '';
        }
        tr.querySelector('.syllabus-row-remove').addEventListener('click', () => tr.remove());
        if (row.rowBg || row.rowColor) {
            let cellStyle = '';
            if (row.rowBg) {
                cellStyle += `background-color:${row.rowBg};`;
            }
            if (row.rowColor) {
                cellStyle += `color:${row.rowColor};`;
            }
            tr.querySelectorAll('td').forEach(td => {
                td.style.cssText = cellStyle;
            });
        }
        elements.syllabusTableBody.appendChild(tr);
    });
    if (elements.syllabusTableEmptyHint) {
        elements.syllabusTableEmptyHint.style.display = normalized.length === 0 ? 'block' : 'none';
    }
}

/** Syllabus rows for save: merge stored edits with calendar-generated schedule. */
function resolveSyllabusRowsForSave() {
    const mod = getSyllabusModule();
    const snapshot = buildClassDraftFromForm();
    const generated = buildGeneratedSyllabusRows(snapshot);
    const classId = elements.classId && elements.classId.value;
    const existing = classId
        ? (appData.classes.find(c => c.id === classId)?.syllabusRows || [])
        : [];
    if (mod && existing.length) {
        return mod.mergeSyllabusRows(existing, generated);
    }
    return generated;
}

function collectSyllabusRowsFromForm() {
    if (!elements.syllabusTableBody) {
        return resolveSyllabusRowsForSave();
    }
    const mod = getSyllabusModule();
    return Array.from(elements.syllabusTableBody.querySelectorAll('tr')).map(tr => {
        const kind = tr.dataset.rowKind || 'lesson';
        const planTitle = (tr.querySelector('.syllabus-ed-title')?.value || '').trim();
        const planDetail = tr.querySelector('.syllabus-ed-detail')?.value || '';
        const noteEl = tr.querySelector('.syllabus-ed-note');
        const note = noteEl ? (noteEl.value || '') : '';
        let source = tr.dataset.rowSource || 'generated';
        if (kind === 'note') {
            source = 'manual';
        } else if (planDetail.trim() && source === 'generated') {
            source = 'manual';
        }
        const sessionNumber = parseInt(tr.dataset.rowSession, 10);
        const lessonNumber = parseInt(tr.dataset.rowLessonNumber, 10);
        const row = {
            id: tr.dataset.rowId || (mod ? mod.newRowId() : generateId()),
            kind,
            date: tr.dataset.rowDate || '',
            monthKey: tr.dataset.rowMonthKey || (tr.dataset.rowDate ? tr.dataset.rowDate.slice(0, 7) : ''),
            weekLabel: (tr.querySelector('.syllabus-ed-week')?.textContent || '').trim(),
            sessionNumber: Number.isNaN(sessionNumber) ? 0 : sessionNumber,
            planTitle,
            planDetail,
            note,
            source
        };
        if (!Number.isNaN(lessonNumber) && lessonNumber > 0) {
            row.lessonNumber = lessonNumber;
        }
        if (tr.dataset.overflowIntro === '1') {
            row.overflowIntro = true;
        }
        if (mod && row.date && !row.weekLabel) {
            row.weekLabel = mod.getSchoolWeekLabel(row.date);
        }
        if (tr.dataset.rowBg) {
            row.rowBg = tr.dataset.rowBg;
        }
        if (tr.dataset.rowColor) {
            row.rowColor = tr.dataset.rowColor;
        }
        if (tr.dataset.eventType) {
            row.eventType = tr.dataset.eventType;
        }
        return row;
    });
}

/**
 * Build syllabus rows from each class calendar schedule and save on the class record.
 */
function syncAllClassSyllabusRowsFromCalendar() {
    if (!getSyllabusModule()) {
        return false;
    }
    syncHolidaysFromEvents();
    let changed = false;
    getClassesInDisplayOrder().forEach((classData) => {
        const merged = syncClassSyllabusRowsFromCalendar(classData, { refreshScheduleTitles: true });
        if (merged && merged.length) {
            changed = true;
        }
    });
    if (changed) {
        saveData();
    }
    return true;
}

function syncClassSyllabusRowsFromCalendar(classData, options = {}) {
    const mod = getSyllabusModule();
    if (!mod || !classData || !classData.id) {
        return null;
    }
    invalidateScheduleCache();
    const generated = buildGeneratedSyllabusRows(classData);
    if (!generated.length) {
        return Array.isArray(classData.syllabusRows) ? classData.syllabusRows : [];
    }
    const saved = Array.isArray(classData.syllabusRows) ? classData.syllabusRows : [];
    const mergeOpts = { refreshScheduleTitles: options.refreshScheduleTitles !== false };
    const merged = saved.length > 0
        ? mod.mergeSyllabusRows(saved, generated, mergeOpts)
        : generated;
    const idx = appData.classes.findIndex(c => c.id === classData.id);
    if (idx >= 0) {
        appData.classes[idx].syllabusRows = merged;
        appData.classes[idx]._syllabusNeedsCalendarSync = false;
        classData.syllabusRows = merged;
        classData._syllabusNeedsCalendarSync = false;
    }
    return merged;
}

function refreshSyllabusFromCalendar() {
    const mod = getSyllabusModule();
    if (!mod) {
        alert(t('syllabusModuleMissing'));
        return;
    }
    invalidateScheduleCache();
    let snapshot;
    let classId;
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        const classData = getSelectedSyllabusClass();
        if (!classData) {
            return;
        }
        snapshot = mergeSyllabusCompressionIntoRecord(classData) || buildClassSnapshotFromRecord(classData);
        classId = classData.id;
    } else {
        snapshot = buildClassSnapshotFromForm();
        classId = elements.classId && elements.classId.value;
    }
    if (!snapshot.customSchedule?.enabled && !maybeConfirmScheduleAdjustments(snapshot)) {
        return;
    }
    const refreshSurface = (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') ? 'syllabus' : 'classForm';
    if (snapshot.compressionMerges || snapshot.skippedLessons) {
        applyScheduleAdjustmentsToForm(
            snapshot.compressionMerges || [],
            snapshot.skippedLessons || [],
            refreshSurface
        );
        if (classId) {
            const idx = appData.classes.findIndex(c => c.id === classId);
            if (idx >= 0) {
                appData.classes[idx].compressionMerges = snapshot.compressionMerges || [];
                appData.classes[idx].skippedLessons = snapshot.skippedLessons || [];
                if (snapshot.compressionMode) {
                    appData.classes[idx].compressionMode = snapshot.compressionMode;
                }
            }
        }
    }
    const existing = collectSyllabusRowsFromForm();
    const generated = buildGeneratedSyllabusRows(snapshot);
    const merged = mod.mergeSyllabusRows(existing, generated, { refreshScheduleTitles: true });
    renderSyllabusEditorTable(merged);

    if (classId) {
        const index = appData.classes.findIndex(c => c.id === classId);
        if (index !== -1) {
            appData.classes[index].syllabusRows = merged;
            appData.classes[index]._syllabusNeedsCalendarSync = false;
            saveData();
            const saved = appData.classes[index];
            updateClassSyllabusSummary(saved);
            if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
                renderSyllabusScheduleAdjustment(saved);
                syncSyllabusEditorChrome();
            }
        }
    }
}

function addSyllabusNoteRow() {
    const mod = getSyllabusModule();
    const rows = collectSyllabusRowsFromForm();
    rows.unshift({
        id: mod ? mod.newRowId() : generateId(),
        kind: 'note',
        planTitle: '',
        planDetail: '',
        note: '',
        source: 'manual',
        sessionNumber: 0,
        weekLabel: '',
        monthKey: '',
        date: ''
    });
    renderSyllabusEditorTable(rows);
}

function getSelectedClassTypeDefinitionFromForm() {
    const hidden = document.getElementById('classTypeIdHidden');
    const typeId = (hidden && hidden.value)
        ? hidden.value
        : (elements.classTypeSelect ? elements.classTypeSelect.value : '');
    return getClassTypeDefinitionById(typeId);
}

function getHomeworkImportModeForForm() {
    const syllabusForm = getSyllabusEditorFormEl();
    if (syllabusForm && syllabusForm.dataset.homeworkImportMode) {
        return syllabusForm.dataset.homeworkImportMode;
    }
    const def = getSelectedClassTypeDefinitionFromForm();
    if (def && def.homeworkImportMode) {
        return def.homeworkImportMode;
    }
    const form = elements.classForm;
    if (form && form.dataset.homeworkImportMode) {
        return form.dataset.homeworkImportMode;
    }
    const snapshot = buildClassSnapshotForSyllabusContext();
    if (classUsesDebateCompression(snapshot)) {
        return 'debate';
    }
    if (classUsesGrWeeklyUnitLabels(snapshot)) {
        return 'grUnit';
    }
    if (classUsesUnitPairLessonLabels(snapshot)) {
        return 'unitPair';
    }
    return 'unitPair';
}

function applyPresetSyllabusRowsToTable(options = {}) {
    const silent = !!options.silent;
    let def;
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        def = getClassTypeDefinitionForSyllabusClass(getSelectedSyllabusClass());
    } else {
        def = getSelectedClassTypeDefinitionFromForm();
    }
    const templates = def && Array.isArray(def.defaultSyllabusRowTemplates)
        ? def.defaultSyllabusRowTemplates
        : [];
    if (!templates.length) {
        if (!silent) {
            alert(t('applyPresetSyllabus') + ': ' + t('applyPresetSyllabusNoTemplates'));
        }
        return;
    }
    const rows = collectSyllabusRowsFromForm();
    if (!rows.length) {
        if (!silent) {
            alert(t('homeworkImportNoRows'));
        }
        return;
    }
    const api = getSyllabusTemplatesApi();
    const result = api
        ? api.applyRowTemplatesToSyllabusRows(rows, templates)
        : { rows, applied: 0 };
    renderSyllabusEditorTable(result.rows);
    if (!result.applied && !silent) {
        alert(t('syllabusNoMatchingSessions'));
    }
}

/** Class record (or form draft) used to resolve live curriculum session templates. */
function getClassDataForSyllabusCurriculumTemplates() {
    let classData = null;
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        classData = getSelectedSyllabusClass();
    }
    if (!classData) {
        const classId = elements.classId && elements.classId.value;
        if (classId) {
            const saved = appData.classes.find((c) => c.id === classId);
            if (saved && !(isClassPopoutOpen() || (getActiveTab() === 'classes' && classEditorMount === 'tab'))) {
                classData = saved;
            }
        }
    }
    if (!classData) {
        classData = buildClassDraftFromForm();
    }
    if (classData && classData.id && elements.classId && elements.classId.value === classData.id) {
        const link = resolveClassCurriculumLinkFromForm({ includeTeacherFields: false });
        if (link.curriculumId) {
            classData = {
                ...classData,
                curriculumId: link.curriculumId,
                classTypeId: link.classTypeId || classData.classTypeId
            };
            if (link.level && getSimsonLevelById(link.level)) {
                classData.levelPreset = link.level;
            }
        }
    }
    return classData;
}

function persistSyllabusRowsToOpenClass(rows) {
    let classId = null;
    if (getActiveTab() === 'syllabus' && syllabusEditorMode === 'class') {
        const classData = getSelectedSyllabusClass();
        classId = classData && classData.id;
    } else {
        classId = elements.classId && elements.classId.value;
    }
    if (!classId) {
        return;
    }
    const index = appData.classes.findIndex((c) => c.id === classId);
    if (index === -1) {
        return;
    }
    appData.classes[index].syllabusRows = rows;
    saveData();
    updateClassSyllabusSummary(appData.classes[index]);
}

function refreshSyllabusFromCurriculum(options = {}) {
    const classData = getClassDataForSyllabusCurriculumTemplates();
    if (!classData) {
        return;
    }
    const onSyllabusTab = getActiveTab() === 'syllabus' && syllabusEditorMode === 'class';
    const useFormDraft = classData.id && (
        isClassPopoutOpen()
        || (getActiveTab() === 'classes' && classEditorMount === 'tab')
    );
    const draft = useFormDraft ? buildClassDraftFromForm() : { ...classData };
    if (draft.id) {
        const fromForm = elements.syllabusTableBody ? collectSyllabusRowsFromForm() : [];
        if (fromForm.length) {
            draft.syllabusRows = fromForm;
        } else {
            const saved = appData.classes.find((c) => c.id === draft.id);
            if (saved && Array.isArray(saved.syllabusRows)) {
                draft.syllabusRows = saved.syllabusRows;
            }
        }
    }
    const result = pushCurriculumToClassSyllabus(draft, {
        silent: !!options.silent,
        skipConfirm: !!options.skipConfirm,
        force: true,
        persist: true,
        updateEditor: true
    });
    if (onSyllabusTab && result.rows && draft.id && appData.ui.syllabusTabClassId === draft.id) {
        renderSyllabusEditorTable(result.rows);
        const saved = appData.classes.find((c) => c.id === draft.id);
        if (saved) {
            setSyllabusGeneralNotesInForm(saved.syllabusGeneralNotes || '');
        }
    }
}

function fillSyllabusPagesFromUnits() {
    const mod = getSyllabusModule();
    if (!mod || !mod.planDetailFromUnits) {
        return;
    }
    const units = collectSyllabusUnitsFromForm();
    if (!units.length) {
        alert(t('syllabusAddUnitsFirst'));
        return;
    }
    const rows = collectSyllabusRowsFromForm();
    if (!rows.length) {
        alert(t('homeworkImportNoRows'));
        return;
    }
    let applied = 0;
    rows.forEach(row => {
        if (row.kind !== 'lesson') {
            return;
        }
        const lessonNum = mod.getCurriculumLessonNumber
            ? mod.getCurriculumLessonNumber(row)
            : row.sessionNumber;
        if (!lessonNum) {
            return;
        }
        const detail = mod.planDetailFromUnits(lessonNum, units, row.planTitle);
        if (detail) {
            row.planDetail = detail;
            row.source = 'manual';
            applied += 1;
        }
    });
    renderSyllabusEditorTable(rows);
    if (!applied) {
        alert(t('syllabusNoPagesFilled'));
    }
}

function previewHomeworkImport() {
    const pasteEl = elements.homeworkImportPaste;
    const previewEl = elements.homeworkImportPreview;
    if (!pasteEl || !previewEl || !window.CCPHomeworkImport) {
        return;
    }
    const text = pasteEl.value;
    if (!text.trim()) {
        alert(t('homeworkImportNoPaste'));
        return;
    }
    const rows = collectSyllabusRowsFromForm();
    if (!rows.length) {
        alert(t('homeworkImportNoRows'));
        return;
    }
    const snapshot = buildClassSnapshotForSyllabusContext();
    const mode = window.CCPHomeworkImport.detectImportMode(text, snapshot);
    const blocks = window.CCPHomeworkImport.parseByMode(text, mode);
    const result = window.CCPHomeworkImport.mapBlocksToSyllabusTargets(blocks, rows, mode);
    const header = t('homeworkImportPreviewHeader')
        .replace('{matched}', String(result.mappings.length))
        .replace('{unmatched}', String(result.unmatched.length));
    const lines = [header, `Mode: ${mode}`, ''];
    result.mappings.forEach(m => {
        lines.push(`✓ #${m.sessionNumber} ${m.planTitle || m.blockTitle}`);
        lines.push(m.planDetail.split('\n').slice(0, 3).join('\n'));
        lines.push('');
    });
    result.unmatched.forEach(u => {
        lines.push(`? ${u.blockTitle}`);
    });
    previewEl.textContent = lines.join('\n');
    previewEl.dataset.importMode = mode;
    previewEl.dataset.importPayload = JSON.stringify(result.mappings);
}

function applyHomeworkImport() {
    const previewEl = elements.homeworkImportPreview;
    if (!previewEl || !previewEl.dataset.importPayload) {
        previewHomeworkImport();
        if (!previewEl || !previewEl.dataset.importPayload) {
            return;
        }
    }
    let mappings = [];
    try {
        mappings = JSON.parse(previewEl.dataset.importPayload);
    } catch (e) {
        previewHomeworkImport();
        try {
            mappings = JSON.parse(previewEl.dataset.importPayload);
        } catch (err) {
            return;
        }
    }
    const rows = collectSyllabusRowsFromForm();
    const byId = new Map(rows.map(r => [r.id, r]));
    let applied = 0;
    mappings.forEach(m => {
        const row = byId.get(m.rowId);
        if (row && m.planDetail) {
            row.planDetail = m.planDetail;
            row.source = 'imported';
            applied += 1;
        }
    });
    renderSyllabusEditorTable(rows);
    alert(t('homeworkImportApplied').replace('{n}', String(applied)));
}

