// ============================================
// Team sync (NAS server)
// ============================================
let conflictResolver = null;

function showConflictModal(serverDoc, localData) {
    return new Promise((resolve) => {
        const modal = document.getElementById('conflictModal');
        if (!modal) {
            resolve('mine');
            return;
        }
        const summaryMount = document.getElementById('conflictMergeSummary');
        if (summaryMount && typeof CCPConflictMerge !== 'undefined') {
            const lines = CCPConflictMerge.summarizeConflict(localData, serverDoc && serverDoc.data);
            summaryMount.innerHTML = CCPConflictMerge.renderSummaryHtml(lines, t, escapeHtml);
        } else if (summaryMount) {
            summaryMount.innerHTML = '';
        }
        conflictResolver = resolve;
        modal.style.display = 'flex';

        const close = () => {
            modal.style.display = 'none';
            if (summaryMount) {
                summaryMount.innerHTML = '';
            }
            conflictResolver = null;
        };

        document.getElementById('conflictUseTheirs').onclick = () => {
            close();
            resolve('theirs');
        };
        document.getElementById('conflictUseMine').onclick = () => {
            close();
            resolve('mine');
        };
        document.getElementById('conflictSmartMerge').onclick = () => {
            close();
            resolve('merge');
        };
        document.getElementById('conflictModalClose').onclick = () => {
            close();
            resolve('cancel');
        };
    });
}

function hasTeamSyncStatusEl() {
    return (
        location.protocol !== 'file:' &&
        typeof CalendarSync !== 'undefined' &&
        Boolean(document.getElementById('teamSyncStatus'))
    );
}

function isTeamSyncBootIncomplete(el) {
    if (!el) {
        return false;
    }
    return !TEAM_SYNC_TERMINAL_STATUSES.some((status) => el.classList.contains('status-' + status));
}

function clearTeamSyncBootWatchdog() {
    if (teamSyncBootWatchdogTimer != null) {
        clearTimeout(teamSyncBootWatchdogTimer);
        teamSyncBootWatchdogTimer = null;
    }
}

function scheduleTeamSyncBootWatchdog() {
    if (!hasTeamSyncStatusEl()) {
        return;
    }
    clearTeamSyncBootWatchdog();
    teamSyncBootWatchdogTimer = setTimeout(() => {
        teamSyncBootWatchdogTimer = null;
        const el = document.getElementById('teamSyncStatus');
        if (!el || !isTeamSyncBootIncomplete(el)) {
            return;
        }
        console.warn('Team sync boot watchdog: clearing stuck status');
        teamSyncBootInProgress = false;
        finishTeamSyncBoot();
        if (isTeamSyncBootIncomplete(el)) {
            const id =
                teamSyncEnabled &&
                typeof CalendarSync !== 'undefined' &&
                CalendarSync.getActiveCalendarId
                    ? CalendarSync.getActiveCalendarId()
                    : null;
            updateTeamSyncStatus(teamSyncEnabled ? (id ? 'saved' : 'connected') : 'connected');
        }
    }, TEAM_SYNC_BOOT_WATCHDOG_MS);
}

function isTransientSyncError(err) {
    if (!err) {
        return false;
    }
    const status = err.status;
    if (status === 401 || status === 403 || status === 404) {
        return false;
    }
    if (status === 408) {
        return true;
    }
    if (err.name === 'AbortError' || err.name === 'TypeError') {
        return true;
    }
    const msg = String(err.message || '').toLowerCase();
    return msg.includes('timed out') || msg.includes('network') || msg.includes('failed to fetch');
}

async function withBootRetry(fn) {
    try {
        return await fn();
    } catch (err) {
        if (!isTransientSyncError(err)) {
            throw err;
        }
        await new Promise((resolve) => setTimeout(resolve, 500));
        return await fn();
    }
}

function isAppDataCalendarEmpty() {
    if (!appData) {
        return true;
    }
    const hasClasses = Array.isArray(appData.classes) && appData.classes.length > 0;
    const hasEvents = Array.isArray(appData.events) && appData.events.length > 0;
    return !hasClasses && !hasEvents && !appData.termStart;
}

function isCalendarContainerEmpty() {
    if (!elements.calendarContainer) {
        return true;
    }
    return !elements.calendarContainer.querySelector('.month-calendar, .calendar-agenda-list');
}

function showCalendarBootLoading(show) {
    if (!elements.calendarContainer) {
        return;
    }
    if (!show) {
        return;
    }
    elements.calendarContainer.innerHTML =
        `<p class="calendar-boot-loading section-hint">${escapeHtml(t('syncSyncing'))}</p>`;
}

function refreshActiveTabAfterHydration() {
    if (isNotesPage() || isWorkspacePage()) {
        return;
    }
    const tab = getActiveTab();
    if (tab === 'cohorts') {
        void initCohortsTabControls();
    } else if (
        tab === 'students'
        || tab === 'attendance'
        || tab === 'homework-tracking'
        || tab === 'points'
        || tab === 'tests'
    ) {
        void initClassroomTabControls(tab);
    } else if (tab === 'timetable') {
        initTimetableTabControls();
    } else if (tab === 'calendar') {
        ensureTermStartData();
        initializeTermStart();
        renderCalendarNow({ forceFull: true });
        requestAnimationFrame(syncAppChromeStickyTop);
    } else if (tab === 'classes') {
        renderClassList();
    } else if (tab === 'events') {
        renderEventList();
    } else if (tab === 'homework') {
        renderHomeworkClassList();
        renderHomeworkEditor();
    } else if (tab === 'syllabus') {
        initSyllabusTabControls();
    } else if (tab === 'notes' || isClassNotesUiActive()) {
        ensureClassNotesShell();
        renderClassNotesTab();
    }
}

async function ensureActiveCalendarLoaded(options) {
    const opts = options || {};
    if (typeof CalendarSync === 'undefined' || location.protocol === 'file:') {
        teamSyncCalendarHydrated = true;
        return { ok: false, offline: true, calendarId: null };
    }
    if (
        teamSyncCalendarHydrated &&
        !opts.forceIfStale &&
        !isAppDataCalendarEmpty()
    ) {
        const hydratedId = CalendarSync.getActiveCalendarId();
        if (hydratedId && teamSyncEnabled) {
            try {
                await CalendarSync.loadNotificationMeta(hydratedId);
            } catch (_) {
                /* offline or API unavailable */
            }
        }
        return {
            ok: true,
            offline: !teamSyncEnabled,
            calendarId: hydratedId
        };
    }

    const connected = await withBootRetry(() => CalendarSync.checkHealth());
    if (!connected) {
        teamSyncEnabled = false;
        setTeamCalendarRowVisible(false);
        setTeamLockBarVisible(false);
        updateTeamSyncStatus('offline');
        if (!isAppDataCalendarEmpty()) {
            teamSyncCalendarHydrated = true;
        }
        updateSetupGuideBanner();
        return { ok: false, offline: true, calendarId: CalendarSync.getActiveCalendarId() };
    }

    teamSyncEnabled = true;
    setTeamCalendarRowVisible(true);

    const canCreateCalendars =
        typeof TeamAuth !== 'undefined' && TeamAuth.hasPermission('create_calendars');
    let calendars = await withBootRetry(() => CalendarSync.listCalendars());
    let activeId = CalendarSync.getActiveCalendarId();

    if (calendars.length === 0 && !canCreateCalendars) {
        location.replace('/pending-access.html');
        return { ok: false, offline: false, calendarId: null };
    }

    if (calendars.length === 0 && canCreateCalendars) {
        calendars = await ensureStarterTeamCalendar();
        activeId = CalendarSync.getActiveCalendarId();
    }

    if (
        (isNotesPage() || isWorkspacePage()) &&
        calendars.length > 0 &&
        (!activeId || !calendars.some((c) => c.id === activeId))
    ) {
        activeId = calendars[0].id;
    }

    populateCalendarSelect(calendars, activeId);

    if (calendars.length > 0) {
        if (!activeId || !calendars.some((c) => c.id === activeId)) {
            activeId = calendars[0].id;
        }
        if (opts.forceIfStale || isAppDataCalendarEmpty() || !teamSyncCalendarHydrated) {
            await withBootRetry(() =>
                switchToTeamCalendar(activeId, calendars, { skipSessionRestore: true })
            );
        }
    } else {
        teamSyncCalendarHydrated = true;
        updateSetupGuideBanner();
    }

    const id = CalendarSync.getActiveCalendarId();
    if (id && isAppDataCalendarEmpty()) {
        try {
            await reloadActiveCalendarFromServer();
        } catch (err) {
            console.warn('ensureActiveCalendarLoaded reload failed:', err);
        }
    }

    if (isNotesPage()) {
        refreshNotesPageIfMounted();
    }

    return {
        ok: teamSyncCalendarHydrated,
        offline: false,
        calendarId: id
    };
}

/** Clear boot-time Connecting/Syncing if init exited without reaching a terminal status. */
function finishTeamSyncBoot() {
    if (!teamSyncCalendarHydrated && !teamSyncBootAttempted) {
        teamSyncCalendarHydrated = true;
    } else if (!teamSyncCalendarHydrated && teamSyncEnabled && !isAppDataCalendarEmpty()) {
        teamSyncCalendarHydrated = true;
    } else if (!teamSyncCalendarHydrated && !teamSyncEnabled && !isAppDataCalendarEmpty()) {
        teamSyncCalendarHydrated = true;
    }
    updateSetupGuideBanner();
    scheduleTabWarningsRefresh();
    const el = document.getElementById('teamSyncStatus');
    if (!el || !isTeamSyncBootIncomplete(el)) {
        return;
    }
    if (teamSyncEnabled) {
        const id =
            typeof CalendarSync !== 'undefined' && CalendarSync.getActiveCalendarId
                ? CalendarSync.getActiveCalendarId()
                : null;
        updateTeamSyncStatus(id ? 'saved' : 'connected');
    } else if (teamSyncBootAttempted) {
        updateTeamSyncStatus('offline', t('teamSyncOffline'));
    } else {
        updateTeamSyncStatus('connected');
    }
}

async function runTeamSyncBoot() {
    if (teamSyncBootInProgress) {
        return;
    }
    teamSyncBootAttempted = true;
    teamSyncBootInProgress = true;
    updateTeamSyncStatus('syncing');
    scheduleTeamSyncBootWatchdog();
    try {
        await initTeamSync();
        ensureTermStartData();
        initializeTermStart();
        renderCalendarNow({ forceFull: true });
        if (teamSyncEnabled && isCalendarContainerEmpty()) {
            try {
                await reloadActiveCalendarFromServer();
                initializeTermStart();
                renderCalendarNow({ forceFull: true });
            } catch (reloadErr) {
                console.warn('Post-boot calendar reload failed:', reloadErr);
            }
        }
        if (!teamSyncEnabled) {
            renderCalendar();
        }
        requestAnimationFrame(syncAppChromeStickyTop);
    } catch (err) {
        console.error('initTeamSync failed:', err);
        updateTeamSyncStatus('error', (err && err.message) || t('syncError'));
        showSyncErrorToast(err);
    } finally {
        teamSyncBootInProgress = false;
        clearTeamSyncBootWatchdog();
        finishTeamSyncBoot();
    }
}

function updateTeamSyncStatus(status, detail) {
    const el = document.getElementById('teamSyncStatus');
    if (!el) {
        return;
    }
    const map = {
        connecting: 'syncConnecting',
        syncing: 'syncSyncing',
        connected: 'syncConnected',
        offline: 'syncOffline',
        saving: 'syncSaving',
        saved: 'syncSaved',
        queued: 'syncOfflineQueued',
        error: 'syncError',
        conflict: 'syncConflictTitle'
    };
    const resolvedDetail = detail ? translateSyncError(detail) : '';
    el.textContent = resolvedDetail || t(map[status] || 'syncConnecting');
    el.className = 'team-sync-status status-' + (status || 'connecting');
}

/** Recover team sync after bfcache or return from admin/other pages with stuck boot status. */
async function ensureTeamSyncReady() {
    if (document.body.classList.contains('workspace-page') || isNotesPage()) {
        return;
    }
    const el = document.getElementById('teamSyncStatus');
    if (!el || location.protocol === 'file:') {
        return;
    }
    if (!isTeamSyncBootIncomplete(el)) {
        return;
    }
    if (teamSyncBootInProgress) {
        return;
    }
    if (typeof CalendarSync === 'undefined') {
        finishTeamSyncBoot();
        return;
    }
    try {
        if (!teamSyncEnabled) {
            teamSyncBootInProgress = true;
            await initTeamSync();
        } else {
            const id = CalendarSync.getActiveCalendarId();
            if (id) {
                await CalendarSync.refreshLockMeta(id);
                updateTeamSyncStatus('saved');
            } else {
                updateTeamSyncStatus('connected');
            }
        }
    } catch (err) {
        console.error('ensureTeamSyncReady failed:', err);
        updateTeamSyncStatus('error', (err && err.message) || t('syncError'));
    } finally {
        teamSyncBootInProgress = false;
    }
    finishTeamSyncBoot();
}

if (typeof window !== 'undefined' && !window.__ccpPageshowSyncInit) {
    window.__ccpPageshowSyncInit = true;
    window.addEventListener('pageshow', (ev) => {
        if (document.body.classList.contains('workspace-page')) {
            return;
        }
        const statusEl = document.getElementById('teamSyncStatus');
        const teamRow = document.getElementById('teamCalendarRow');
        const incomplete = statusEl && isTeamSyncBootIncomplete(statusEl);
        const rowVisible = teamRow && !teamRow.hidden;
        const willRun = ev.persisted || (teamSyncInitialBootDone && incomplete && rowVisible);
        if (willRun) {
            void ensureTeamSyncReady();
        }
    });
}

if (typeof window !== 'undefined') {
    window.finishTeamSyncBoot = finishTeamSyncBoot;
    window.ensureTeamSyncReady = ensureTeamSyncReady;
    window.ensureActiveCalendarLoaded = ensureActiveCalendarLoaded;
    window.isTeamSyncBootIncomplete = isTeamSyncBootIncomplete;
}

function showSyncToast(message, isError) {
    if (!message || !window.CCPNotice || !window.CCPNotice.show) {
        return;
    }
    // #region agent log
    if (isError) {
        const _msg = String(message || '');
        if (/conflict|409|syncError|저장 충돌/i.test(_msg)) {
            fetch('http://127.0.0.1:7819/ingest/66f5e2ef-d4bf-4b46-be19-67f9a9ebf548',{method:'POST',headers:{'Content-Type':'application/json','X-Debug-Session-Id':'72a155'},body:JSON.stringify({sessionId:'72a155',runId:'pre-fix',hypothesisId:'H1-H3',location:'app.js:showSyncToast',message:'error toast shown',data:{toastMessage:_msg,syncStatus:typeof CalendarSync!=='undefined'&&CalendarSync.state?CalendarSync.state.syncStatus:null},timestamp:Date.now()})}).catch(()=>{});
        }
    }
    // #endregion
    window.CCPNotice.show(message, {
        type: isError ? 'error' : 'success',
        duration: 7000
    });
}

function highlightCalendarSelect() {
    const sel = document.getElementById('teamCalendarSelect');
    if (!sel) {
        return;
    }
    sel.classList.add('team-sync-select--highlight');
    sel.focus();
    sel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    setTimeout(() => sel.classList.remove('team-sync-select--highlight'), 3000);
}

function populateCalendarSelect(calendars, activeId) {
    const sel = document.getElementById('teamCalendarSelect');
    const delBtn = document.getElementById('teamDeleteCalendarBtn');
    if (!sel) {
        return;
    }
    sel.innerHTML = '';
    const list = calendars || [];
    if (list.length === 0) {
        const empty = document.createElement('option');
        empty.value = '';
        const canCreate =
            typeof TeamAuth !== 'undefined' &&
            TeamAuth.hasPermission &&
            TeamAuth.hasPermission('create_calendars');
        empty.textContent = canCreate ? t('teamCalendarEmpty') : t('teamCalendarNoneAssigned');
        empty.disabled = true;
        empty.selected = true;
        sel.appendChild(empty);
        if (delBtn) {
            delBtn.disabled = true;
            delBtn.hidden = true;
        }
        return;
    }
    list.forEach((c) => {
        const opt = document.createElement('option');
        opt.value = c.id;
        opt.textContent = c.name || c.id;
        sel.appendChild(opt);
    });
    if (activeId && list.some((c) => c.id === activeId)) {
        sel.value = activeId;
    } else {
        sel.value = list[0].id;
    }
    if (delBtn) {
        updateTeamDeleteCalendarButton(list, sel.value);
    }
    updateTopBarCalendarLabel();
}

async function switchToTeamCalendar(id, calendarsOptional, switchOptions) {
    const switchOpts = switchOptions || {};
    const previousId = typeof CalendarSync !== 'undefined' ? CalendarSync.getActiveCalendarId() : null;
    if (previousId && id && previousId !== id && typeof CalendarSync !== 'undefined') {
        try {
            await CalendarSync.flushPendingSave();
        } catch (err) {
            if (err.status !== 423) {
                console.warn('Flush before calendar switch failed:', err);
            }
        }
    }
    if (teamLockPreviousCalendarId && teamLockPreviousCalendarId !== id) {
        await CalendarSync.releaseLock(teamLockPreviousCalendarId);
    }
    const list = calendarsOptional || (await CalendarSync.listCalendars());
    populateCalendarSelect(list, id);
    if (!id || !list.some((c) => c.id === id)) {
        CalendarSync.setActiveCalendarId(null);
        teamSyncCalendarHydrated = true;
        if (list.length === 0) {
            appData = getDefaultAppData();
            loadUiStateFromLocalStorageIntoData(appData);
            initializeTermStart();
            renderCalendar();
            refreshCalendarScopedUi();
        }
        return;
    }
    teamSyncCalendarHydrated = false;
    CalendarSync.setActiveCalendarId(id);
    bindAppStoreMutationSync(id);
    if (typeof CCPStoragePrune !== 'undefined' && CCPStoragePrune.pruneOnCalendarSwitch) {
        CCPStoragePrune.pruneOnCalendarSwitch(previousId, id, list);
    }
    try {
        const doc = await CalendarSync.loadCalendar(id);
        teamLockPreviousCalendarId = null;
        if (!CalendarSync.state.readOnly && CalendarSync.state.holdsLock) {
            teamLockPreviousCalendarId = id;
        }
        applyTeamLockAccessState({
            readOnly: CalendarSync.state.readOnly,
            lock: CalendarSync.state.lock,
            holdsLock: CalendarSync.state.holdsLock,
            pendingEditRequest: CalendarSync.state.pendingEditRequest
        });
        applyServerDocument(doc, switchOpts);
        initializeTermStart();
        renderCalendar();
        updateTeamSyncStatus('saved');
        if (CalendarSync.state.pendingEditRequest && CalendarSync.state.readOnly) {
            showLockFlash(
                t('teamLockWaitingFlash').replace('{name}', formatLockParty(CalendarSync.state.lock)),
                false
            );
        }
        scheduleTabWarningsRefresh();
    } catch (err) {
        if (err.status === 404) {
            showSyncToast(t('teamCalendarAccessLost'), true);
            const freshList = await CalendarSync.listCalendars();
            if (freshList.length > 0) {
                await switchToTeamCalendar(freshList[0].id, freshList, switchOpts);
            } else {
                populateCalendarSelect([], null);
                CalendarSync.setActiveCalendarId(null);
                appData = getDefaultAppData();
                loadUiStateFromLocalStorageIntoData(appData);
                initializeTermStart();
                renderCalendar();
                refreshCalendarScopedUi();
            }
            return;
        }
        throw err;
    }
}

function renderAccessCheckboxList(container, items, inputName, options) {
    if (!container) {
        return;
    }
    const opts = options || {};
    container.innerHTML = '';
    if (!items || items.length === 0) {
        const p = document.createElement('p');
        p.className = 'section-hint';
        p.textContent = opts.emptyText || '';
        container.appendChild(p);
        return;
    }
    items.forEach((item) => {
        const label = document.createElement('label');
        label.className = 'access-checkbox-item';
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.name = inputName;
        cb.value = item.id;
        if (opts.checkedIds && opts.checkedIds.includes(item.id)) {
            cb.checked = true;
        }
        if (opts.disabledIds && opts.disabledIds.includes(item.id)) {
            cb.disabled = true;
            cb.checked = true;
        }
        label.appendChild(cb);
        label.appendChild(document.createTextNode(' ' + (item.displayName || item.name || item.email || item.id)));
        container.appendChild(label);
    });
}

function getNewCalendarAccessSelections() {
    const memberUserIds = [];
    document.querySelectorAll('#newCalendarTeachersList input[type="checkbox"]:checked').forEach((el) => {
        if (el.value && !el.disabled) {
            memberUserIds.push(el.value);
        }
    });
    const groupIds = [];
    document.querySelectorAll('#newCalendarGroupsList input[type="checkbox"]:checked').forEach((el) => {
        if (el.value) {
            groupIds.push(el.value);
        }
    });
    return { memberUserIds, groupIds };
}

async function populateCalendarAccessPicker(options) {
    const opts = options || {};
    const teachersEl = document.getElementById(opts.teachersListId || 'newCalendarTeachersList');
    const groupsEl = document.getElementById(opts.groupsListId || 'newCalendarGroupsList');
    const groupsLabel = opts.groupsLabelEl
        ? document.querySelector(opts.groupsLabelEl)
        : document.querySelector('.access-groups-label');
    const teacherInputName = opts.teacherInputName || 'newCalTeacher';
    const groupInputName = opts.groupInputName || 'newCalGroup';
    const me = typeof TeamAuth !== 'undefined' ? TeamAuth.getUser() : null;
    if (!teachersEl) {
        return;
    }
    let teachers = [];
    let groups = [];
    try {
        teachers = await CalendarSync.fetchTeachers();
        groups = await CalendarSync.fetchGroups();
    } catch (_) {
        teachers = [];
        groups = [];
    }
    const otherTeachers = (teachers || []).filter((u) => !me || u.id !== me.id);
    const disabledIds = me ? [me.id] : [];
    renderAccessCheckboxList(teachersEl, otherTeachers, teacherInputName, {
        emptyText: t('newCalendarNoAccessList'),
        disabledIds
    });
    if (groupsEl) {
        if (groups.length > 0) {
            if (groupsLabel) {
                groupsLabel.hidden = false;
            }
            renderAccessCheckboxList(groupsEl, groups, groupInputName, { emptyText: '' });
        } else {
            groupsEl.innerHTML = '';
            if (groupsLabel) {
                groupsLabel.hidden = true;
            }
        }
    }
}

